// OpenAPI documentation for every route, kept in one place and attached through an `onRoute`
// hook. Schemas are documentation only: validation stays in @claudio/core, so behaviour is unchanged.

type Json = Record<string, unknown>;

const ref = (name: string): Json => ({ $ref: `#/components/schemas/${name}` });
const list = (name: string): Json => ({ type: 'array', items: ref(name) });
const obj = (properties: Json, required: string[] = []): Json => ({ type: 'object', properties, required });
const str = (description?: string, extra: Json = {}): Json => ({ type: 'string', ...(description ? { description } : {}), ...extra });
const OK = obj({ ok: { type: 'boolean', const: true } }, ['ok']);

const PROJECT = str("Project id from `GET /projects`. Omit for the user scope (the Claude config dir).");
const VARIANT = str('`local` selects settings.local.json / CLAUDE.local.md (project scope only).', { enum: ['shared', 'local'], default: 'shared' });
const scopeQuery = (extra: Json = {}): Json => obj({ project: PROJECT, ...extra });
const KIND = str('Resource kind', { enum: ['agents', 'skills', 'commands', 'output-styles', 'rules', 'workflows'] });
const ROOT = str("`user` or a project id (see `GET /config/files/roots`)");
const ITEM = obj({ itemId: str('Work item id') });
const CHANGE_REQUEST = obj({ id: str("Change request id: the row id of a work item's or an orchestration's change request") });
const CHECK = obj({ id: str('Change request id'), checkId: str("The check's id (`Check.id`)") });
const MILESTONE =obj({ milestoneId: str('Milestone id') });
const WORK_ITEM_FILTER = obj({
  status: str('Comma separated columns: `backlog`, `todo`, `in_progress`, `in_review`, `done`'),
  type: str('Comma separated types: `epic`, `story`, `task`, `bug`'),
  priority: str('Comma separated priorities: `low`, `medium`, `high`, `urgent`'),
  labels: str('Comma separated labels, matched in any case'),
  assignee: str('Comma separated: `person`, `none` or `role:<role>`'),
  epicId: str('Items of this epic'),
  milestoneId: str('Items of this milestone'),
  q: str('Searched in the title and the description, and matched against the key (`AGN-12`)'),
});

// A page of a list: the filter, then where to start and how many
const WORK_ITEM_PAGE_QUERY = obj({
  ...(WORK_ITEM_FILTER.properties as Json),
  limit: str('Items on the page: a whole number from 1; default 100, and above 500 it is brought down to 500'),
  cursor: str("The previous page's `nextCursor`; absent for the first page. One this list did not hand out is refused with 400"),
});

const BOARD_QUERY = obj({
  ...(WORK_ITEM_FILTER.properties as Json),
  doneLimit: str('Items the Done column holds, its most recently closed: a whole number from 0; default 20, and above 500 it is brought down to 500. `more` counts those left out'),
});

const CARDS = 'Descriptions are left out: each item carries `description: ""` and `hasDescription`, and its own page (`GET /work-items/{itemId}`) has it whole.';

// What the change routes share: a scope (one commit, or the uncommitted work), and a diff's context
const SCOPE_PARAMS: Json = {
  commit: str('Only this commit (`<sha>^..<sha>`; a root commit against the empty tree). Refused with 400 unless it is on the branch since its base'),
  uncommitted: str('`1` for the working tree against `HEAD` only, untracked files included'),
};
const SCOPE_QUERY = obj(SCOPE_PARAMS);
const DIFF_QUERY = obj(
  {
    path: str('File to diff, relative to the checkout (required)'),
    context: str('Unchanged lines around each change, 0–500, or `full` for the whole file. Anything else is the default of 3'),
    ...SCOPE_PARAMS,
  },
  ['path'],
);
const SCOPE_NOTE =
  '`?commit=` narrows `files` to what that commit changed, `?uncommitted=1` to the working tree against `HEAD`; either way the rest of the summary still describes the branch, and `working` is left out. Asking for both is refused. `binary` marks a file git counts no lines for.';
const DIFF_NOTE =
  '`?commit=` and `?uncommitted=1` scope it as the summary does. `full` is true only when `context=full` was honoured: a file over 20 000 lines keeps the default context. A binary file is git\'s one line; a long diff ends in `… diff truncated`, and one too large answers `… diff too large to show`.';
const STEPS_NOTE =
  "Every successful `Edit`, `MultiEdit`, `Write` or `NotebookEdit` of the chat's main transcript (not its subagents'), oldest first, each with the patch the CLI stored for it as a unified diff (`''` when it kept none) and `intent`, the last thing the assistant wrote before the call. `path` is relative to the git top level of where the chat works, or to its directory outside git. `entryIndex` is the entry's index in `GET /chats/:id` with sidechains off. A call still waiting for its result is the last step, `pending`, only while the chat has an execution. A chat with no transcript yet is read from what its process streamed, without patches. Read once, then only what the transcript appended. `risk` scores the call from its path and where the chat works (its directory, its worktree and the checkout): absent when the call is low, `medium` for CI config, git internals, Claude settings, env files and keys, `high` for a write outside them. It is a reading aid; nothing is blocked by it.";

