interface RouteDoc {
  tags: [string];
  summary: string;
  description?: string;
  params?: Json;
  querystring?: Json;
  body?: Json;
  /** 200/201 response schema */
  ok?: Json;
  created?: boolean;
  /** 202 instead of 200 */
  accepted?: boolean;
  /** Non-JSON response content type (SSE) */
  produces?: string;
  /** Kept for old clients; the description names what replaces it */
  deprecated?: boolean;
  /** Request headers the route reads */
  headers?: Json;
}

const d = (tag: string, summary: string, rest: Omit<RouteDoc, 'tags' | 'summary'> = {}): RouteDoc => ({ tags: [tag], summary, ...rest });

/** Keyed by `METHOD /path` without the `/api` prefix. */
export const ROUTE_DOCS: Record<string, RouteDoc> = {
  // ---- System
  'GET /health': d('System', 'Liveness and readiness', { ok: obj({ ok: { type: 'boolean' }, cli: { type: 'boolean' }, loggedIn: { type: 'boolean' } }) }),
  'GET /ready': d('System', 'Readiness: can a chat run now', { description: 'Open like `/health`, and as cheap: it spawns nothing and reads the last detection. `200 { ready: true }` when the store is open, Claude Code is installed and an account is signed in; otherwise `503 { ready: false, reason }` with `cli-missing`, `signed-out`, `sign-in-expired` or `starting` (no detection has finished yet). It says nothing else about the account. `/health` stays the liveness probe: a signed-out Claudio is alive.', ok: ref('ReadyStatus') }),
  'GET /system': d('System', 'CLI installation, auth status and paths', { querystring: obj({ refresh: str('`1` bypasses the 30s cache') }), ok: ref('SystemInfo') }),
  'GET /system/cli-version': d('System', 'Claude Code version in use and the newest published', { description: 'What the last check learned; it never reads the registry itself. `checkedAt` says how old the answer is.', ok: ref('CliVersionInfo') }),
  'POST /system/cli-version/check': d('System', 'Check for a newer Claude Code now', { description: 'Reads the npm registry metadata of `@anthropic-ai/claude-code`. The server also does it once a day unless `CLAUDIO_CLI_UPDATE_CHECK=off`. A failure keeps the previous answer and reports `error`.', ok: ref('CliVersionInfo') }),
  'GET /system/storage': d('System', 'Whether the state survives replacing the container', { description: 'Reads the mounts this process sees and says, for the Claude config dir, the data dir and the workspace, whether each sits on a persistent volume, on a volume Docker made on its own (`anonymous`: the next `docker run` starts with an empty one), on the container\'s own layer or on a temporary one. Only a Docker distribution (`CLAUDIO_DISTRIBUTION=docker`) is checked; anywhere else `checked` is false and the list empty. `atRisk` is true when some folder will not survive an update.', ok: ref('StorageReport') }),
  'GET /system/load': d('System', 'What the machine is doing now and whether it admits a new chat', { description: 'Read from `/proc` on each call: the load average, memory and its available part, and the pressure (PSI) of the CPU, memory and I/O, each as `some10` and `full10` in percent. `admitting` is false while a chat would be refused for lack of memory (`refusal` says why); the limits are `CLAUDIO_ADMIT_MEMORY_PRESSURE` and `CLAUDIO_ADMIT_MEMORY_FLOOR_MB`. `limits` repeats the two limits in force. A figure this machine does not expose is null, never zero. Linux only: elsewhere every figure is null and `admitting` is true.', ok: ref('SystemLoad') }),
  'GET /system/processes': d('System', 'What each live chat\'s process tree uses: processes, resident memory and CPU time', { description: 'Every chat whose CLI is up, with its pid and the processes it started (`processes`, children included), the resident memory of the tree in MB (`rssMb`) and the CPU seconds it has used so far (`cpuSeconds`, user and system). Read from `/proc` on each call, and it walks the whole process table, so poll it at a human pace. A figure the kernel does not give is null: a total with one of them null is not a total. CPU use over a window is the difference between two readings. Linux only: no chats are listed elsewhere.', ok: ref('ProcessUsageReport') }),
  'GET /system/history': d('System', 'The machine\'s readings over time', { description: 'The rows of `system_samples`, oldest first: the figures `/system/load` and `/system/processes` give, read once a minute (`CLAUDIO_MACHINE_SAMPLE_SECONDS`, 0 turns it off) and kept for 7 days (`CLAUDIO_MACHINE_RETENTION_DAYS`). `bucket` folds the rows of each N seconds into one at the start of the bucket: the largest load, pressure, chats and resident memory, the smallest `availableMb`, and `admitting` false when any of them was refused. A figure the kernel did not give is null. `limit` keeps the newest rows of the range (default 2000, at most 20000). Empty on a machine with no `/proc`.', querystring: obj({ since: str('From this moment (ISO 8601)'), until: str('Until this moment (ISO 8601)'), limit: str('Max rows (default 2000)'), bucket: str('Seconds per point, to fold a long range into a few hundred points') }), ok: list('SystemSample') }),
  'GET /system/release': d('System', 'Claudio version in use and the newest release', { description: 'What the last check learned; it never asks GitHub itself. `distribution` (from `CLAUDIO_DISTRIBUTION`) says how this server was installed, and so how to update it.', ok: ref('ClaudioReleaseInfo') }),
  'POST /system/release/check': d('System', 'Check for a newer Claudio release now', { description: 'Reads the latest GitHub release of Claudio (never a draft or a pre-release), or `CLAUDIO_RELEASES_URL`. The server also does it once a day unless `CLAUDIO_UPDATE_CHECK=off`. A failure keeps the previous answer and reports `error`. A newer release is also announced once on `GET /api/events` as `system.release`.', ok: ref('ClaudioReleaseInfo') }),
  'POST /system/cli-version/install': d('System', 'Install a newer Claude Code inside the container', { description: "Owner only (a `token:*` or OIDC actor): `403 cli.needs-auth` under auth `none`, `403 cli.not-owner` for the desktop app, and a chat's token is refused by its denylist. Docker on Linux x64 only (`400 cli.unsupported` elsewhere, or with `CLAUDIO_SERVER_UPDATE=off`). Installs `version`, or the newest the last check found, from the npm registry's native package `@anthropic-ai/claude-code-linux-x64` (or the registry of `CLAUDIO_CLI_REGISTRY_URL`): it must be inside the driver's range (`422 cli.out-of-range`) and newer than the image's pin and the CLI in use (`422 cli.not-newer`); one install at a time (`409 cli.busy`). Answers at once; the download is checked against the registry's `dist.integrity` (SHA-512), only the binary is unpacked, no lifecycle script runs, and `--version` must report the version. It then goes to `/data/cli/<version>` and `/data/cli/current` is swapped, so new chats use it and running ones keep theirs. `install` in the answer follows it.", body: obj({ version: str('An exact version; the newest known when absent') }), ok: ref('CliVersionInfo'), accepted: true }),
  'DELETE /system/cli-version/install': d('System', "Go back to the image's Claude Code", { description: 'Owner only, like the install. Removes the `/data/cli/current` link, so new chats use the image\'s pinned CLI again; the launcher deletes the unused version at the next start. `409 cli.not-installed` when none is installed in `/data`.', ok: ref('CliVersionInfo') }),
  'GET /system/server-update': d('System', 'In-app updates of Claudio, in its container or under the desktop app', { description: 'Reads no network. Supported in the Docker image under its launcher, and in the desktop app (`appimage`, `deb`) when the desktop shell supervises the server (`CLAUDIO_LAUNCHER=desktop`). `unsupportedReason` says why this server cannot update itself (`not-docker`: a source install; `no-launcher`: not supervised by its launcher, or `CLAUDIO_SERVER_UPDATE=off`; `development`: a desktop app run from a checkout; `no-keys`, `needs-auth`, `read-only`). `base` says what the base payload ships in, the image or the desktop shell, and `image` is its version; `shell` is the desktop shell\'s facts (null elsewhere). `running` is the version running, from the base or an overlay under `<dataDir>/app`. `state`, `target`, `progress` and `error` follow a download; `needsImage` and `needsShell` say the newest release needs a newer image or desktop app. `offer` is the newest release as the last release check judged it, before any download: `installable` only when its bundle, manifest and signature are there, verified, and made for this base, else `blocked` says why (`no-bundle`, `unverified`, `needs-image`, `needs-shell`, `failed-before`). `lastRollback` is the launcher\'s last rollback. Changes are also sent on `GET /api/events` as `system.server-update`.', ok: ref('ServerUpdateStatus') }),
  'POST /system/server-update/download': d('System', 'Download the newest Claudio release', { description: "Owner only, or the desktop shell's own per-launch credential where it supervises the server (`CLAUDIO_LAUNCHER=desktop`, from this machine; under auth `none` too). Anyone else: `403 update.needs-auth` under auth `none`, `403 update.not-owner` otherwise; a chat's token is refused by its denylist. `400 update.unsupported` where this server cannot update itself. The release is the one the last release check found (`404 update.no-release` when there is none newer, when it attaches no server bundle, or when that version was rolled back here before); `version`, when given, must be it. Its manifest is fetched and its Ed25519 signature checked against the base's keys (any line of a multi-key `.sig`) before answering: `412 update.needs-image` when it needs a newer image, `412 update.needs-shell` when it needs a newer desktop app. Then it answers 202 and downloads the tarball, checks its sha256 and every file's, unpacks it into `<dataDir>/app/<version>` and makes it the launcher's trial (`state: ready`). `409 update.busy` while another download or restart is under way. Every refusal is `{ error, code }`; a client shows it from `code`.", body: obj({ version: str('The newest release; any other is refused') }), ok: ref('ServerUpdateStatus'), accepted: true }),
  'POST /system/server-update/apply': d('System', 'Restart onto the downloaded update', { description: "Owner only, or the desktop shell, as for the download. `409 update.not-ready` with nothing downloaded. With chats working or waiting, orchestrations running or terminals open, answers `409 update.live-work` with `live` (their counts) unless `force`; `whenIdle` schedules the restart for when nothing is running, checked every 15 s (`state: scheduled`). Otherwise answers 202 and the server closes like on SIGTERM and exits 75, which has the launcher (the image's, or the desktop shell) boot the new bundle on trial: kept once `/api/health` answers within 60 s (on the desktop, once its window rendered too), rolled back after two failed boots.", body: ref('ServerUpdateApplyRequest'), ok: ref('ServerUpdateStatus'), accepted: true }),
  'DELETE /system/server-update/scheduled': d('System', 'Call off a restart that waits for idleness', { description: 'Owner only, or the desktop shell, as for the download. The downloaded update stays ready.', ok: ref('ServerUpdateStatus') }),
  'POST /system/server-update/revert': d('System', 'Go back to the base version of Claudio', { description: "Owner only, or the desktop shell, as for the download. `409 update.not-overlay` when the base version already runs. Forgets every overlay and restarts onto the base payload (the image's `/app`, or the one bundled in the desktop app), with the same live-work rule as apply (`409 update.live-work`, `force`, `whenIdle`).", body: ref('ServerUpdateApplyRequest'), ok: ref('ServerUpdateStatus'), accepted: true }),
  'GET /overview': d('System', 'Everything the dashboard needs in one call', {
    description:
      'The CLI and its auth, the account view (`accounts`: the account new work starts on with its own reading, every account, whether every account is out and the earliest reset; the same view `GET /auth` names `inUse` from), the usage limit of each provider (`limits`; Claude\'s is the reading of the account in use, or of the account back first when every one is out), what is running and the newest chats. `system.models` is what `--model` may be given: the aliases the CLI always takes, and after them whatever the logged-in account may run, read from the options the CLI caches in its own state file — so a subscription that adds a model adds it here, and one the CLI cannot run yet comes back `disabled` with the reason.',
    ok: ref('Overview'),
  }),

  // ---- Account
  'GET /auth': d('Account', 'Fresh auth status', { description: 'The CLI\'s own login as `claude auth status` reports it, and `inUse`: the account new work starts on, the same one `GET /overview` serves as `accounts.inUse` (chosen as a chat\'s launch chooses: the preferred account while it has room, else the strategy), with its own usage reading. `inUseReason` says why it is null.', ok: ref('AuthStatus') }),
  'PUT /auth/credentials': d('Account', 'Store the account credential', { description: 'Exactly one of `oauthToken` (from `claude setup-token`) or `apiKey`. Kept in the secret vault (`secrets.json`, mode 600, sealed when there is a key) and handed to every new `claude` process in its environment, and to no other; overrides the container environment.', body: ref('SetCredentialsRequest'), ok: ref('AuthStatus') }),
  'DELETE /auth/credentials': d('Account', 'Remove the stored credential', { description: 'Falls back to the credential from the container environment, if any.', ok: ref('AuthStatus') }),
  'GET /setup': d('Setup', 'What the first setup has done', { description: 'The access mode, each enabled agent\'s readiness (and whether Claudio keeps a key for it), each code host\'s CLI and the hosts it is signed in to, whether YouTrack is configured, the Tailscale behind Remote access (`tailscale`: whether the tunnel is offered, whether Claudio runs the daemon itself and so may sign it in, its readiness and node name), the sign-in methods each tool offers (`methods`, a static table written from the vendors\' documentation), how the secrets Claudio keeps are stored (`secrets`: sealed, and whether the key sits beside the data) and whether the setup assistant was finished or skipped (`seen`).', ok: ref('SetupState') }),
  'POST /setup/seen': d('Setup', 'Record that the setup assistant was finished or skipped', { description: 'Writes `setupSeen` to `app-settings.json`, so no other browser shows the assistant again. 409 when the environment sets it off (`CLAUDIO_SETUP_SEEN`, or the older `CLAUDIO_PROVIDERS_STEP_SEEN`). Emits `settings.changed`.', ok: ref('SetupState') }),
  'POST /setup/logins': d('Setup', 'Start a sign-in', { description: '`method: key` with `secret`: for gh and glab the key goes once on stdin to the CLI\'s own login command (`gh auth login --with-token --hostname`, `glab auth login --hostname --stdin`), which stores it; for Tailscale it goes into a file of mode 0600 named in `tailscale up --reset --hostname=<name> --auth-key=file:<path>`, removed once the command ended, and tailscaled keeps the node key it gets; for Claude Code and YouTrack it is sealed in the vault and handed to that tool\'s processes in their environment (`variable` picks which one where there is a choice, `host` is YouTrack\'s address). Answers once it ended. `method: device` runs the vendor\'s documented device-code command with no terminal (glab, gh, and Tailscale\'s `tailscale up`, whose login URL comes with no code) and answers at once in `starting`; `login.updated` follows with the URL and the code (`waiting-for-person`), then the end. Success is the tool\'s readiness read again, never what the CLI printed; a failure is an `error` code. A device sign-in expires after 15 minutes, and a new one for the same tool and host cancels the one still waiting. 400 for an unknown tool, a method the tool lacks, a key that is empty or holds spaces, or a host that is not a host name. 409 for Tailscale where Claudio does not run the daemon itself (anywhere but its Docker image, or with `CLAUDIO_TUNNEL=off`): a machine\'s own Tailscale is the person\'s to sign in.', body: ref('StartLoginRequest'), ok: ref('LoginSession'), created: true }),
  'GET /setup/logins/:id': d('Setup', 'Read a sign-in', { description: 'Its state, and for a device sign-in the URL and the code. Ended sign-ins are kept for an hour; 404 after that, or for an id never started.', params: obj({ id: str('Sign-in id') }), ok: ref('LoginSession') }),
  'DELETE /setup/logins/:id': d('Setup', 'Cancel a sign-in', { description: 'Kills the device-code command\'s process group and ends it `cancelled`; an ended sign-in is answered as it is. Emits `login.updated`.', params: obj({ id: str('Sign-in id') }), ok: ref('LoginSession') }),
  'DELETE /setup/credentials/:tool': d('Setup', 'Sign a tool out', { description: 'Runs the documented sign-out (`gh auth logout --hostname`, `glab auth logout --hostname`, `claude auth logout` after forgetting the vault\'s credential) or forgets what the vault keeps (YouTrack). Tailscale closes the tunnel first, then runs `tailscale logout`, which takes the node off the tailnet; 409 where Claudio does not run the daemon.', params: obj({ tool: str('`claude-code`, `gh`, `glab`, `youtrack` or `tailscale`') }), querystring: obj({ host: str('For `gh` and `glab`: the host to sign out of (their default when absent)') }), ok: ref('SignOutResult') }),

  'POST /auth/verify': d('Account', 'Verify the credential with a real request', { description: '`claude auth status` only reports what is configured; this sends a minimal prompt to prove it works. Costs a few tokens.', ok: ref('AuthVerification') }),


  // ---- Projects
  'GET /projects': d('Projects', 'Imported projects', { description: "Only directories that were imported. Each carries its repository (`repo`: common dir, main checkout, subdir, remote with credentials stripped, bare; null for a directory in none), the repository's checkouts that exist (the main one first, then the linked worktrees git would not prune, each with the chats placed in it and `createdBy`: an orchestration task, a work item or a chat, null when made by hand; `createdBy` gained a `kind`), `removedWorktrees` (worktrees git no longer has, still named by chats), `insideWorktreeOf` (the main checkout plus subdir when the path lies inside a linked worktree) and the number of chats under it.", ok: list('Project') }),
  'GET /projects/candidates': d('Projects', 'Repositories worth importing', { description: "Chats that belong to no project, grouped by the git repository they ran in: one suggestion per repository (`kind: repository`: its main checkout, the remote with credentials stripped, the chats and the linked worktrees they ran in, and `sameRemoteAs` when another clone is already a project), at most 8, then up to 5 plain directories (`kind: directory`). A repository that already is a project is never offered. Left out: scratch directories, directories that are gone, `$HOME` and everything above it, this install's workspace itself, Claudio's own config, data and eval directories, the workspace roots of other Claudio installs, a folder that holds a known repository, and what the person hid. What a first start offers instead of an empty screen.", ok: list('ProjectCandidate') }),
  'POST /projects/candidates/hide': d('Projects', 'Hide a suggestion', { description: "Stops offering the suggestion with this `key` (a candidate's `key`: the repository's common dir, or the path of a directory), kept in `project-suggestions.json`. `204`, idempotent.", body: ref('CandidateKeyRequest') }),
  'POST /projects/candidates/unhide': d('Projects', 'Show a hidden suggestion again', { description: 'Undoes `hide` for this `key`. `204`, idempotent.', body: ref('CandidateKeyRequest') }),
  'GET /projects/templates': d('Projects', 'Project templates', { description: 'The five built-in templates a new project starts from: the modules each switches on, the work item types and column limits of its board, and the team it would offer. Applied once, when a project is created or imported.', ok: list('ProjectTemplate') }),
  'GET /projects/inspect': d('Projects', 'What a path is before it is imported', { description: "Reads only. Whether the path exists, the git repository it is in (null for none), the path Import would record (`importPath`: the path itself, or the folder holding a bare repository's `.bare` or `.git`), the conflict that would refuse it (`linked-worktree` with the main checkout plus the same subdir, or `already-a-project`), another project that is a clone of the same remote (`sameRemoteAs`) and how many linked worktrees the repository has. 400 without `path`.", querystring: obj({ path: str('The directory to inspect') }), ok: ref('ProjectPathInspection') }),
  'POST /projects/import': d('Projects', 'Import a directory as a project', { description: 'Every chat under the directory belongs to it from then on, retroactively. A path anywhere inside a linked worktree is refused with 400 and the code `linked-worktree` (`detail` is the main checkout plus the same subdir, the path to import instead), and a repository and subdir that already is a project with 409 and the code `already-a-project` (`detail` is its id). A bare repository is imported from the folder that holds its `.bare` or `.git`. `template` configures the project and `modules` replaces the template\'s choice; with neither, every module is off. A directory that was a project before takes its old id back, and with it its settings and work items; `modules` or `template`, when given, set which modules are on. Emits `project.created` when the directory was not imported already.', body: ref('ImportProjectRequest'), ok: ref('Project'), created: true }),
  'POST /projects': d('Projects', 'Create a project in the workspace', { description: 'Creates an empty directory, or clones `gitUrl` into it, and imports it. `template` and `modules` work as on import, and are checked before the directory is created. Emits `project.created`.', body: ref('CreateProjectRequest'), ok: ref('Project'), created: true }),
  'PATCH /projects/:id': d('Projects', 'Rename a project, re-point it, or change its key or modules', { description: 'Every field is optional. `path` re-points the project inside its own repository: a directory (400 `not-a-directory`) of the main checkout, not of a linked worktree (400 `linked-worktree`, `detail` names the main checkout plus subdir), of the same repository (400 `other-repository`), that no other project is (409 `already-a-project`, `detail` is its id); a project in no repository answers 400 `not-a-repository`. The id stays, so its chats, settings and work items stay with it; nothing on disk changes, and `project.updated` lists `path`. `key` is the prefix of its work items\' keys: 2 to 10 upper case letters or digits, starting with a letter, unique among the imported projects; existing items follow, since only their number is stored. `modules` is the whole set that is on afterwards: switching a module off hides it and keeps its data. Emits `project.updated` when something changed.', params: obj({ id: str('Project id') }), body: ref('UpdateProjectRequest'), ok: ref('Project') }),
  'GET /projects/:id/review-roles': d('Projects', 'The reviewers of the review gate', { description: "For each role (`correctness`, `tests`, `security`, `conventions`, `verifier`): the file it reads in the project's checkout (`.claude/agents/`), whether the text is the project's own or Claudio's built-in (`source`), its `sha` and size, and a `problem` when the file is not used. 404 for an id that is not an imported project.", params: obj({ id: str('Project id') }), ok: list('ReviewRoleInfo') }),
  'POST /projects/:id/review-roles/:role': d('Projects', "Write a reviewer's default role file", { description: "Writes Claudio's built-in text of the role into the project's checkout where no file exists, so a team can edit it; a file that is there is never overwritten. 404 for an unknown project or role; 409 `role-exists` when the file exists. Refused to a chat's token with 403.", params: obj({ id: str('Project id'), role: str('Role name') }), ok: ref('ReviewRoleInfo'), created: true }),
  'GET /projects/:id/settings': d('Projects', 'Read a project\'s settings', { description: 'The settings document: modules, template, key prefix and board configuration, and, once set, the team (`team.members`), the flow by column (`flow`) and the documents folder (`documents.path`). A project with none, such as one imported before modules existed, gets one written on first read with every module off and a key prefix derived from its name; a stored prefix another imported project holds is derived again and written as well. Nothing else is ever written by a read: a document a hand edit broke is answered part by part with defaults and left on disk as it is.', params: obj({ id: str('Project id') }), ok: ref('ProjectSettings') }),
  'PUT /projects/:id/settings': d('Projects', 'Replace a project\'s settings', { description: 'Replaces the document whole, validated: known modules, a template id or null, a key prefix no other imported project holds, at least one work item type and whole-number column limits; `team`, `flow` and `documents` are optional and checked the same way when present (each member an agent file name with its role, model, responsibility and relative `writes`; the flow\'s switch, columns and limits; a relative documents path). Unknown fields are dropped. Emits `project.updated` with what changed.', params: obj({ id: str('Project id') }), body: ref('ProjectSettings'), ok: ref('ProjectSettings') }),
  'GET /projects/:id/tracker': d('Projects', "A project's issue tracker", { description: "The tracker in the project's settings (`id`, `scope`, `query`, `statusMap`), or null when it has none.", params: obj({ id: str('Project id') }), ok: ref('ProjectTrackerSettings') }),
  'PUT /projects/:id/tracker': d('Projects', "Choose a project's issue tracker", { description: "Replaces the tracker and leaves the rest of the settings as they are; a null body clears it. Validated like the settings: a known tracker, a scope that is a repository for GitHub and GitLab, and a status map over `in_progress`, `in_review` and `done`. Refused to a chat's token with 403.", params: obj({ id: str('Project id') }), body: ref('ProjectTrackerSettings'), ok: ref('ProjectTrackerSettings') }),
  'GET /projects/:id/tracker/issues': d('Projects', "Search the project's tracker", { description: "One page of the tracker's own query, read through the CLI of the project's code host (the project's `query` when none is given). Each issue says whether it was already imported, as which item. Issue text is untrusted and is shown, never obeyed. 409 with a `code`: `unsupported-host` (the project is on another host), `not-recorded` (a tracker whose CLI is not recorded), `tracker-signed-out`, `auth-failed` and the other host reasons; 409 without one when the project has no tracker.", params: obj({ id: str('Project id') }), querystring: obj({ query: str('The tracker\'s own query; empty reads as the project\'s'), page: str('Page from 1 (default 1)') }), ok: ref('TrackerIssuesPage') }),
  'POST /projects/:id/tracker/import': d('Projects', "Import issues as work items", { description: "One work item per key, in the backlog, with the issue's body as a quoted source block and a link to the issue. Needs the Board module on. Each key is read again from the tracker; one already imported in the project, gone, or a pull request is in `skipped` with its reason and the rest go on. At most 100 keys. Refused to a chat's token with 403.", params: obj({ id: str('Project id') }), body: ref('TrackerImportRequest'), ok: ref('TrackerImportResult') }),
  'GET /projects/:id/export': d('Projects', 'Export a project\'s chats as Markdown or JSON', {
    description:
      'A download, streamed a chat at a time. `markdown` (default) opens with the project, the dates its chats span, the models that answered, the cost as the CLI reported it (chats started outside Claudio report none, and the header counts them) and a numbered list of the chats, then every chat oldest first as a section rendered like `GET /chats/:id/export`. `json` is a `ProjectExport`: the project and a `ChatExport` per chat. Housekeeping chats are left out.',
    params: obj({ id: str('Project id') }),
    querystring: obj({ format: str('Output format', { enum: ['markdown', 'json'] }) }),
    ok: ref('ProjectExport'),
  }),
  'DELETE /projects/:id': d('Projects', 'Remove a project from Claudio', { description: 'Harmless: nothing on disk changes, and importing the directory again adopts its chats again. Its settings document and its work items are kept as well, and come back when the directory is imported again. Distinct from `DELETE /projects/:id/state`. Emits `project.removed`.', params: obj({ id: str('Project id') }), ok: OK }),
  'DELETE /projects/:id/state': d('Projects', 'Purge everything Claude Code keeps about a project', { description: 'Transcripts, tasks, file history and the config entry, through `claude project purge`. Irreversible; the project stays imported.', params: obj({ id: str('Project id') }), ok: obj({ detail: str('What the CLI reported') }) }),

  // ---- Work items
  'GET /projects/:id/work-items': d('Work items', "List a project's work items", { description: `In board order: column by column, by rank inside one. Readable with the Board module off. Every list in the query is comma separated; its values are alternatives and the fields combine. An unknown status, type or priority is refused. ${CARDS} \`/page\` serves the same list a page at a time.`, params: obj({ id: str('Project id') }), querystring: WORK_ITEM_FILTER, ok: list('WorkItem') }),
  'GET /projects/:id/work-items/page': d('Work items', "A page of a project's work items", { description: `The list of \`GET /projects/{id}/work-items\`, with the same filter and order, \`limit\` items at a time. \`total\` counts every item that passes the filter; \`nextCursor\` is the next page's \`cursor\`, null on the last. The cursor is a place in the order, not an offset, so an item created or moved while paging neither repeats nor pushes another out. ${CARDS}`, params: obj({ id: str('Project id') }), querystring: WORK_ITEM_PAGE_QUERY, ok: ref('WorkItemPage') }),
  'POST /projects/:id/work-items': d('Work items', 'Create a work item', { description: 'Takes the next number of the project, never reused; the key is `<prefix>-<number>`. Goes last in its column, `backlog` by default. An epic has no epic, and `epicId` must name an epic of the same project. Refused with 409 while the Board module is off. Emits `workitem.created`.', params: obj({ id: str('Project id') }), body: ref('CreateWorkItemRequest'), ok: ref('WorkItem'), created: true }),
  'GET /projects/:id/work-items/board': d('Work items', "A project's board", { description: `The five columns in order, each with its limit, its real count and the items that pass the filter in rank order. The filter narrows the items, never the count: a limit is about the real load of a column. The Done column holds its \`doneLimit\` most recently closed items that pass the filter, still in rank order, and \`more\` counts the rest: asking again with a larger \`doneLimit\` shows them. Readable with the Board module off. \`pullRequestReadiness\` says whether approving an item opens its pull request, or why not (cached for 60 s), and \`checkout\`, from local git only, how far the project's checkout is behind \`origin/<default>\` and why it was not brought forward. ${CARDS}`, params: obj({ id: str('Project id') }), querystring: BOARD_QUERY, ok: ref('Board') }),
  'POST /projects/:id/work-items/triage': d('Work items', 'Suggest the type and priority of a draft', { description: 'The `board.triage` decision point for a draft being typed: the type and priority it would prefill and whether an open item already seems to cover it. `triage` is null unless the point is active and answered in time (in shadow the answer is only recorded), so the form is filled in by the person as it is today; `triage.decisionId` is the decision to mark as decided. Nothing is created. Refused with 409 while the Board module is off.', params: obj({ id: str('Project id') }), body: ref('TriageWorkItemRequest'), ok: ref('TriageWorkItemResult') }),
  'POST /projects/:id/work-items/orchestrate': d('Work items', 'Draft an orchestration from a selection', { description: 'A graph to review, not a launched one: one node per item in the order they were picked, each named `KEY · title` (the first line of its chat, which a chat is listed by), prompted with its item and naming it in `workItemId`, and `dependsOn` wherever one selected item blocks another. Blockers outside the selection that are not done come back in `externalBlockers`, since the graph cannot wait for them. Every node gets its own worktree when the project is a git repository. The objective is written in the language of `Accept-Language`. Epics are refused with 400, and so is an item of another project; an item already done, or one a chat or a node is working on now, with 409, as `POST /work-items/{itemId}/work` refuses them. `POST /orchestrations` launches the draft and links each node to its item. Refused with 409 while the Board module is off.', params: obj({ id: str('Project id') }), body: ref('OrchestrateWorkItemsRequest'), ok: ref('WorkItemOrchestrationDraft') }),
  'GET /projects/:id/milestones': d('Work items', "A project's milestones", { description: 'Oldest first, each with its progress derived from its work items, epics left out. Readable with the Board module off.', params: obj({ id: str('Project id') }), ok: list('Milestone') }),
  'POST /projects/:id/milestones': d('Work items', 'Create a milestone', { description: 'A name and a description, with no date. Starts open. Refused with 409 while the Board module is off. Emits `milestone.changed`.', params: obj({ id: str('Project id') }), body: ref('CreateMilestoneRequest'), ok: ref('Milestone'), created: true }),
  'GET /work-items': d('Work items', 'List the work items of every project', { description: `The All projects view: the items of every imported project whose Board module is on, each naming its project, column by column and by project then rank inside one. Takes the same filter as a project's list. ${CARDS} \`/work-items/page\` serves the same list a page at a time.`, querystring: WORK_ITEM_FILTER, ok: list('WorkItem') }),
  'GET /work-items/page': d('Work items', 'A page of the work items of every project', { description: `The All projects list of \`GET /work-items\`, with the same filter and order, \`limit\` items at a time, as \`GET /projects/{id}/work-items/page\` pages a project's. ${CARDS}`, querystring: WORK_ITEM_PAGE_QUERY, ok: ref('WorkItemPage') }),
  'GET /work-items/board': d('Work items', 'The board of every project', { description: `The All projects board: the five columns with no limit, counted over the imported projects whose Board module is on, and the items that pass the filter. The Done column holds its \`doneLimit\` most recently closed items, and \`more\` counts the rest, as on a project's board. ${CARDS}`, querystring: BOARD_QUERY, ok: ref('Board') }),
  'GET /work-items/by-key/:key': d('Work items', 'Read a work item by its key', { description: "The item a key names (`AGN-12`, in any case), with its page, as `GET /work-items/{itemId}` answers it. 404 when no project's item has it. A prefix is unique among the imported projects; when a removed project's items had the same prefix, the imported project's item is the one answered.", params: obj({ key: str('Work item key, such as `AGN-12`') }), ok: ref('WorkItemDetail') }),
  'GET /work-items/:itemId': d('Work items', 'Read a work item', { description: 'The item with its page: the items it groups as an epic, its links with their state, its comments and its history, oldest first. An item of a project that was removed from Claudio is still readable.', params: ITEM, ok: ref('WorkItemDetail') }),
  'PATCH /work-items/:itemId': d('Work items', 'Update a work item', { description: 'Only the fields present change, and `null` clears a nullable one. `acceptanceCriteria` replaces the checklist: an entry with an `id` keeps its check. The status and the place change through `/move`: a body naming `status` or `afterId` is refused with 400. Writes one history entry per field that changed and emits `workitem.updated` naming them.', params: ITEM, body: ref('UpdateWorkItemRequest'), ok: ref('WorkItem') }),
  'DELETE /work-items/:itemId': d('Work items', 'Delete a work item', { description: 'For good; its number is not handed out again. The items it grouped lose their epic and those related to it lose the relation, each with a history entry. Emits `workitem.removed`, and `workitem.updated` for each item it touched.', params: ITEM, ok: OK }),
  'POST /work-items/:itemId/move': d('Work items', 'Move a work item', { description: 'To a column and a place in it: right after `afterId`, first with `afterId: null`, last without it. `afterId` must be in the target column. Going over the column\'s limit is allowed and reported in `column.overLimit`. Entering `done` sets `closedAt`. A move to where the item already is changes nothing. Emits `workitem.moved`.', params: ITEM, body: ref('MoveWorkItemRequest'), ok: ref('MoveWorkItemResult') }),
  'PATCH /work-items/:itemId/criteria/:criterionId': d('Work items', 'Check or uncheck an acceptance criterion', { description: 'Records who checked it. Emits `workitem.updated` with `criterion`.', params: obj({ itemId: str('Work item id'), criterionId: str('Criterion id') }), body: ref('CheckAcceptanceCriterionRequest'), ok: ref('WorkItem') }),
  'GET /work-items/:itemId/comments': d('Work items', "A work item's comments", { description: 'Oldest first, by the person and by agents.', params: ITEM, ok: list('WorkItemComment') }),
  'POST /work-items/:itemId/comments': d('Work items', 'Comment on a work item', { description: 'Markdown, written as the person. Emits `workitem.updated` with `comment`.', params: ITEM, body: ref('CreateWorkItemCommentRequest'), ok: ref('WorkItemComment'), created: true }),
  'POST /work-items/:itemId/relations': d('Work items', 'Relate two work items', { description: '`blocks` or `blocked_by` another item of the same project, named by `itemId` in the body (the other item, which `DELETE …/relations/{otherId}` names in the path); an item of another project is refused with 400. Refused with 400 when it points at the item itself, and with 409 when it closes a cycle of `blocks`. Stored once and reported from both ends; both items record it and emit `workitem.updated`.', params: ITEM, body: ref('CreateWorkItemRelationRequest'), ok: ref('WorkItem'), created: true }),
  'DELETE /work-items/:itemId/relations/:otherId': d('Work items', 'Remove a relation', { description: 'Whichever way it points. Both items record it and emit `workitem.updated`.', params: obj({ itemId: str('Work item id'), otherId: str('The related work item') }), ok: ref('WorkItem') }),
  'GET /work-items/:itemId/links': d('Work items', "A work item's links", { description: 'Every chat and orchestration task that worked on it or that it was created from, oldest first, with their name and state as this process knows them.', params: ITEM, ok: list('WorkItemLink') }),
  'POST /work-items/:itemId/links': d('Work items', 'Link a chat, an orchestration task or a document', { description: 'A chat is named by `chatId`, an orchestration task by `orchestrationId` and `taskId`, each of which must exist and belong to the item\'s project (400 otherwise), a document by `documentPath`, which must be a Markdown file inside the project\'s documents folder, on disk, with the Documents module on (as `POST /work-items/{itemId}/documents`, but with any role). Linking the same thing twice answers with the link already there; a document is the same link whatever its role. Emits `workitem.updated` with `link`, and `document.changed` (`tied`) for a document.', params: ITEM, body: ref('CreateWorkItemLinkRequest'), ok: ref('WorkItemLink'), created: true }),
  'DELETE /work-items/:itemId/links/:linkId': d('Work items', 'Unlink a chat, an orchestration task or a document', { description: 'The chat, the orchestration or the file stays as it is. Emits `workitem.updated` with `link`, and `document.changed` (`untied`) for a document.', params: obj({ itemId: str('Work item id'), linkId: str('Link id') }), ok: OK }),
  'POST /work-items/:itemId/issues': d('Work items', 'Link an issue to a work item', { description: "Reads the issue from the project's tracker and links it. 409 with a `code` when the tracker cannot give it (`not-found`, `issue-is-pull-request`, `unsupported-host`, `not-recorded`, ...). Emits `workitem.updated`. Refused to a chat's token with 403.", params: ITEM, body: ref('LinkWorkItemIssueRequest'), ok: ref('WorkItem'), created: true }),
  'DELETE /work-items/:itemId/issues/:key': d('Work items', 'Unlink an issue from a work item', { description: 'Removes the link only; the issue is not touched. `tracker` and `scope` are needed only when the same key is linked under two trackers or two repositories. Refused to a chat\'s token with 403.', params: obj({ itemId: str('Work item id'), key: str('The issue key') }), querystring: obj({ tracker: str('Tracker id, when the key is ambiguous'), scope: str('The repository the issue was imported from, when the key is ambiguous') }), ok: ref('WorkItem') }),
  'POST /work-items/:itemId/issues/:key/sync': d('Work items', 'Sync an issue again', { description: "One more write to the tracker for the column the item is in, never retried by Claudio. Returns the item with the issue's `syncState` and `syncReason`. 409 when the column is not mapped in the project's tracker or the tracker does not write it, or a sync of this issue is already running. Refused to a chat's token with 403.", params: obj({ itemId: str('Work item id'), key: str('The issue key') }), querystring: obj({ tracker: str('Tracker id, when the key is ambiguous'), scope: str('The repository the issue was imported from, when the key is ambiguous') }), ok: ref('WorkItem') }),
  // ---- Claude Docs
  'GET /projects/:id/docs': d('Claude Docs', "A project's Claude Docs", { description: 'The registry as last read: each entry with its link, title, who added it (`createdBy`), `status` (`unread` until a refresh, then `ok` or `unavailable`) and `checkedAt`. Starts no session. 404 for an unknown project.', params: obj({ id: str('Project id') }), ok: ref('ProjectDocsOverview') }),
  'POST /projects/:id/docs': d('Claude Docs', 'Add or create a Claude Doc', { description: "Send exactly one of `url` (a claude.ai https link the person pasted) or `create` (`title`, optional `body`; an empty body asks Claude for a short outline in the language of `Accept-Language`). One confined session opens or creates the document through the Docs connector and reports its id, link and title. 400 for a bad link, both or neither field; 404 when the link does not open; 409 for a duplicate, 100 documents already, or a Docs connector that is missing or not connected; 502 when the session fails or takes over 180 seconds. Not open to a chat's token.", params: obj({ id: str('Project id') }), body: ref('AddProjectDocRequest'), ok: ref('ProjectDoc'), created: true }),
  'POST /projects/:id/docs/refresh': d('Claude Docs', "Read every Claude Doc's title again", { description: "One confined session reads each entry by link. One that no longer resolves is marked `unavailable` and kept, never dropped. An empty registry starts no session. Same refusals as adding. Not open to a chat's token.", params: obj({ id: str('Project id') }), ok: ref('ProjectDocsOverview') }),
  'DELETE /projects/:id/docs/:docId': d('Claude Docs', 'Remove a Claude Doc from the project', { description: "Drops the registry entry only; the document on claude.ai is never touched. `204`. 404 when it is not in the project. Not open to a chat's token.", params: obj({ id: str('Project id'), docId: str('Document id') }) }),
  'POST /projects/:id/docs/:docId/ask': d('Claude Docs', 'Ask Claude about a document', { description: "Opens a normal chat in the project's directory with the document's link in the prompt and the Docs connector available through the account, so the person watches and drives any change. The chat is titled in the language of `Accept-Language`. Answers what `POST /chats` answers. 404 for an unknown project or document. Not open to a chat's token.", params: obj({ id: str('Project id'), docId: str('Document id') }), ok: ref('ChatSummary'), created: true }),
  // ---- Documents
  'GET /projects/:id/documents': d('Documents', "A project's documents folder", { description: "The Markdown files (`.md`, `.markdown`) under the folder `documents.path` of the project's settings (`docs` by default) as a tree, directories first, each file with its first `# ` heading, its size, its modification time and the work items it is tied to. Hidden entries, `node_modules`, symbolic links and folders with no Markdown under them are left out; the walk stops at 16 levels and 5,000 files. `exists` is false while the folder is not on disk. Readable with the Documents module off.", params: obj({ id: str('Project id') }), ok: ref('ProjectDocuments') }),
  'GET /projects/:id/documents/file': d('Documents', 'Read a document', { description: 'A Markdown file of the documents folder, with the items it is tied to. `path` is relative to the project and `/`-separated (`docs/specs/agn-28.md`). Refused with 400 when it is absolute, climbs with `..`, has an empty, `.` or hidden part, is not Markdown, lies outside the folder, or resolves outside it through a symbolic link; 404 when it is not a file on disk. Readable with the Documents module off.', params: obj({ id: str('Project id') }), querystring: obj({ path: str('Relative to the project, inside the documents folder') }, ['path']), ok: ref('DocumentFile') }),
  'PUT /projects/:id/documents/file': d('Documents', 'Write a document', { description: "Creates or replaces a Markdown file of the documents folder, and the folders it needs, with the path rules of the read. With `baseUpdatedAt` (the `updatedAt` the editor read), a file changed or removed since is refused with 409 instead of overwritten. At most 1 MiB (1 048 576 bytes of UTF-8); a larger one is refused with 400. Refused with 409 while the Documents module is off. Emits `document.changed` (`written`).", params: obj({ id: str('Project id') }), querystring: obj({ path: str('Relative to the project, inside the documents folder') }, ['path']), body: ref('WriteDocumentRequest'), ok: ref('DocumentFile') }),
  'DELETE /projects/:id/documents/file': d('Documents', 'Delete a document', { description: 'Deletes the file and unties it from every work item, each untie recorded in its item\'s history. Refused with 409 while the Documents module is off. Emits `document.changed` (`removed`), and `workitem.updated` and `document.changed` (`untied`) for each tie.', params: obj({ id: str('Project id') }), querystring: obj({ path: str('Relative to the project, inside the documents folder') }, ['path']), ok: OK }),
  'POST /work-items/:itemId/documents': d('Documents', 'Tie a document to a work item', { description: "The shorthand of `POST /work-items/{itemId}/links` with `kind: document`, which is the general form and takes any role: a `document` link in the role `reference`, to a Markdown file of the item's project's documents folder that is on disk, with the path rules of the read. `kind` defaults to `doc`. Tying the same file twice answers with the tie already there. Needs the Board and the Documents modules on (409). Emits `workitem.updated` with `link` and `document.changed` (`tied`).", params: ITEM, body: ref('TieDocumentRequest'), ok: ref('WorkItemLink'), created: true }),
  'GET /work-items/:itemId/history': d('Work items', "A work item's history", { description: 'Written by the server, oldest first: one entry per field that changed, with who changed it and, when a chat or an orchestration did, the cause.', params: ITEM, ok: list('WorkItemHistoryEntry') }),
  'POST /work-items/:itemId/work': d('Work items', 'Work on a work item', { description: "Starts a chat in the item's project, prompted with its key, title, description and acceptance criteria, in its own git worktree on branch `claudio-task/<key>` in lower case, under the main checkout's `.claude/worktrees/`: made the first time from the project's HEAD (a linked worktree's, not the main checkout's), or from the branch of the orchestration node that worked on the item last, whose worktree it never works in; found again by every later chat on the item, and made again on the same branch if its directory was deleted by hand. A project that is not a git repository, or has no commit yet, is worked on in its directory. Takes what a new chat takes, except the prompt and the directory, each checked for its type before any chat starts (400). The item follows the chat: it enters `in_progress` when a turn starts and `in_review` when one ends well; a failed or stopped turn moves nothing, and a chat that ends failed before its turn gave any result puts the item back where it was (cause `chat.failed-to-start`). Automatic moves only go forward, never out of `done`, and never over a person who moved the item since the turn began; each is in the history with the chat as its cause. Refused with 400 for an epic, and with 409 for an item in `done`, while a chat or a node is already working on the item, when a plain directory that is not a worktree sits at the worktree's path, when the branch is checked out in another worktree, when another project of the same repository holds a worktree for the same key, or while the Board module is off. If the link cannot be written, the chat just started is stopped.", params: ITEM, body: ref('WorkOnWorkItemRequest'), ok: ref('WorkOnWorkItemResult'), created: true }),
  'POST /work-items/:itemId/pull-request': d('Work items', "Approve a work item into its pull request", { description: "The person's approval of an item waiting in `in_review`: Claudio's own process (never an agent) commits what is left uncommitted in the item's worktree as `chore(<key>): keep the work QA verified`, fetches and merges `origin/<default>` into `claudio-task/<key>`, pushes it with git and opens the pull request (GitHub) or merge request (GitLab) with the project's host CLI, `gh pr create` or `glab mr create`, `--base` the default branch. The title is `<type>: <title> (<KEY>)`, the type a Conventional label on the item or else `fix` for a bug and `feat` for the rest; the body is the description, each acceptance criterion as `[x]`/`[ ]` with QA's note from its newest passing verification, and a link to the card. Answers 202 at once with the item and `pullRequest.phase` `preparing`; each step reaches the feed as `workitem.updated`. Once open the item stays in `in_review` with `waiting: 'merge'`, and a watcher asks the host about it every 60 s: merged moves it to Done (cause `pr.merged`), closed unmerged leaves it waiting for approval. A merge conflict pushes nothing: the merge stays in progress in the worktree and the item goes back to `in_progress` (cause `pr.conflict`), where the flow's Developer resolves it and QA verifies again, which then opens the PR with no second approval. A failed step records its code and git's or the CLI's first line of error in `pullRequest.error`. Answers 200 with the PR already open (or being prepared), and opens nothing. Refused with 400 for an epic, and with 409 and a `code` for an item not in `in_review` (`not-in-review`), one a chat or a flow run is working on (`busy`), a branch with no commit ahead of the default branch and nothing uncommitted (`nothing-to-propose`), or a project that cannot open them: `reason` names why (`not-git`, `no-remote`, `unsupported-host`, `no-default-branch`, `cli-missing`, `cli-incompatible`, `cli-signed-out`) and the readiness carries the `host`, its `hostname` and a `remedy` (a link to follow, never a command). The work item's `pullRequest` carries its `host` and its `ref` (`#12` on GitHub, `!12` on GitLab).", params: ITEM, ok: ref('WorkItemPullRequestResult') }),
  'POST /work-items/:itemId/pull-request/refresh': d('Work items', "Ask the host about a work item's pull request now", { description: "Reads the item's open pull or merge request from its host at once, rather than waiting for the watcher's next pass, and writes what changed: its CI state (`none`, `pending`, `passing`, `failing`), a merge (the item moves to Done) or a close. Does nothing when the item has no open PR. Answers the item.", params: ITEM, ok: ref('WorkItem') }),
  'GET /work-items/:itemId/changes': d('Work items', 'What a work item changed on disk', { description: "Its worktree and branch, and what the branch changed against where it left the main checkout: commits, files and what is not committed yet, read from git as a chat's worktree is. `summary` is null while nothing has worked on the item in a worktree, and once both the worktree and the branch are gone. " + SCOPE_NOTE, params: ITEM, querystring: SCOPE_QUERY, ok: ref('WorkItemChanges') }),
  'GET /work-items/:itemId/changes/diff': d('Work items', 'The diff of one file of a work item', { description: `Everything its branch did to the file since its base, committed or not. Refused when the item has no worktree or branch left. ${DIFF_NOTE}`, params: ITEM, querystring: DIFF_QUERY, ok: ref('FileDiff') }),
  'POST /chats/:id/work-items': d('Work items', 'Create a task from a chat message', { description: "A work item in `backlog` of the chat's project, with the message as its description and, unless `title` is given, its first line as the title. Linked to the chat as its origin, and recorded with the chat as the cause. Refused with 409 when the chat is in no imported project, or while that project's Board module is off.", params: obj({ id: str('Chat (session) id') }), body: ref('CreateWorkItemFromMessageRequest'), ok: ref('WorkItem'), created: true }),
  'GET /chats/:id/work-items': d('Work items', 'The work items of a chat', { description: 'The items the chat works on or was the origin of, for its header, in the order the chat took them up. Items of projects no longer imported are left out; a chat with none answers an empty list. Descriptions are left out, as in every list (`hasDescription`).', params: obj({ id: str('Chat (session) id') }), ok: list('WorkItem') }),
  'GET /milestones/:milestoneId': d('Work items', 'Read a milestone', { params: MILESTONE, ok: ref('Milestone') }),
  'PATCH /milestones/:milestoneId': d('Work items', 'Update, close or reopen a milestone', { description: 'Only the fields present change. Emits `milestone.changed` with `updated`, `closed` or `reopened` when something did.', params: MILESTONE, body: ref('UpdateMilestoneRequest'), ok: ref('Milestone') }),
  'DELETE /milestones/:milestoneId': d('Work items', 'Delete a milestone', { description: 'Its work items stay, without a milestone, and each records it in its history. Emits `milestone.changed` with `deleted`.', params: MILESTONE, ok: OK }),

  // ---- Team
  'GET /projects/:id/team': d('Team', "A project's team", { description: "Every member with its agent file's state (`ok`, `missing`, or `drifted` with the frontmatter fields that disagree with the metadata), the columns it answers for under the flow and its flow runs, plus the agent files no member uses. Readable with the Team module off; `enabled` says whether it is on.", params: obj({ id: str('Project id') }), ok: ref('Team') }),
  'POST /projects/:id/team/from-template': d('Team', "Add the template's team", { description: "The roles of the project's template, or the Professional software team when it has none, that `roles` names (the team's roles without it: the template's optional roles, such as the silent failure hunter, type design analyst, build resolver and spec miner, are added only when `roles` names them, and take no flow column; an unknown role is refused with 400 listing both sets). A role with `tools` gets them as the `tools:` line of its agent file. Each gets its agent file in `.claude/agents/<role>.md` unless one exists, which is kept as it is; a role already on the team is left alone. Fills the flow's columns nobody answers for with the roles that take them (the flow stays off). Answers the whole team: 201 when it added a member, 200 when every role was already on the team, so sending it twice is harmless. Refused with 409 while the Team module is off. Emits `team.changed` with `template` and `project.updated`.", params: obj({ id: str('Project id') }), body: ref('TeamFromTemplateRequest'), ok: ref('Team') }),
  'PUT /projects/:id/team/:agent': d('Team', 'Create or replace a team member', { description: "The member's metadata, keyed by its agent file name. Two members may not share a role (409). `createFile` writes a starting agent file where there is none. An existing file follows the new metadata only while it is exactly what Claudio wrote; a file a person wrote or edited is kept and served as `drifted`. `commands` bounds the shell of the member's work runs to those patterns (`pnpm test`, `pnpm *`; `[]` is no shell, absent or null an unrestricted one). The file itself is edited through `/config/resources/agents/:name?project=`, which emits `team.changed` with `file`. Refused with 409 while the Team module is off. Emits `team.changed` with `created` or `updated`.", params: obj({ id: str('Project id'), agent: str('Agent file name, without `.md`') }), body: ref('PutTeamMemberRequest'), ok: ref('TeamMember') }),
  'DELETE /projects/:id/team/:agent': d('Team', 'Take a member off the team', { description: "Its agent file stays on disk, usable from a terminal and offered again in `unassignedAgents`. Refused with 409 while the Team module is off. Emits `team.changed` with `removed`.", params: obj({ id: str('Project id'), agent: str('Agent file name, without `.md`') }), ok: OK }),
  // ---- Evals
  'GET /projects/:id/evals': d('Evals', "A project's evals", { description: "The files of `.claude/claudio-evals/`, each with its parse problems (a file that does not parse is listed, never run), its SHA and the newest run of that eval. 404 for an unknown project; 409 `team-off` while the Team module is off.", params: obj({ id: str('Project id') }), ok: list('EvalFileListItem') }),
  'GET /projects/:id/eval-head': d('Evals', "A project's repository state for evals", { description: "Whether the checkout is a repository, its HEAD commit (the SHA and subject that `Pin to HEAD` pins) and the eval files the repository does not have as they are on disk. 404 for an unknown project.", params: obj({ id: str('Project id') }), ok: ref('EvalHead') }),
  'GET /projects/:id/evals/:name': d('Evals', 'One eval file', { description: 'The definition, its problems, the SHA of its bytes and `consented`: whether the person accepted this very content. 400 for a name that is not an eval name; 404.', params: obj({ id: str('Project id'), name: str('Eval name, without `.json`') }), ok: ref('EvalFileDetail') }),
  'PUT /projects/:id/evals/:name': d('Evals', 'Write an eval file', { description: 'A strict parse, then an atomic write. `ifMatch` is the SHA that was read (`null` for a file that should not exist yet): a file changed on disk since, by a `git pull` or another editor, is 409 `changed-on-disk` and is not overwritten. 400 with the path of each wrong field in `problems`; 413 over 256 KiB. Refused to a chat\'s token (403).', params: obj({ id: str('Project id'), name: str('Eval name, without `.json`') }), body: ref('PutEvalFileRequest'), ok: ref('EvalFileDetail') }),
  'DELETE /projects/:id/evals/:name': d('Evals', 'Remove an eval file', { description: 'Removes the file and its consent; the runs already made stay in the history. 404; 409 `eval-running` while the eval is running. Refused to a chat\'s token (403).', params: obj({ id: str('Project id'), name: str('Eval name, without `.json`') }), ok: OK }),
  'POST /projects/:id/evals/:name/estimate': d('Evals', 'Estimate an eval run', { description: 'What a start with this request would cost and need: the samples, the ceiling to repeat in `confirmMaxCostUsd`, the typical cost from the eval\'s history, every command to consent to, and warnings. Starts nothing. 422 `pin-missing`, `target-missing`, `not-git`, `no-commit`, `lanes-root-contaminated` or `user-scope-proposal`.', params: obj({ id: str('Project id'), name: str('Eval name, without `.json`') }), body: ref('EvalRunRequest'), ok: ref('EvalEstimate') }),
  'POST /projects/:id/evals/:name/consent': d('Evals', 'Accept what an eval file runs', { description: 'Records that the person saw every prompt, the setup and every assertion command of the file with this SHA. Any edit asks again. 409 `changed-on-disk` when the SHA is not the file\'s now. Refused to a chat\'s token (403).', params: obj({ id: str('Project id'), name: str('Eval name, without `.json`') }), body: ref('EvalConsentRequest'), ok: ref('EvalFileDetail') }),
  'POST /projects/:id/evals/:name/runs': d('Evals', 'Start an eval run', { description: 'Only a person\'s request starts a run. `confirmMaxCostUsd` must equal the estimate\'s ceiling: 409 `cost-not-confirmed` otherwise. 409 `eval-running` while the project has a run; 412 `consent-needed` until the file\'s content is accepted; 422 as for the estimate. Refused to a chat\'s token (403).', params: obj({ id: str('Project id'), name: str('Eval name, without `.json`') }), body: ref('EvalRunRequest'), ok: ref('EvalRunSummary'), created: true }),
  'GET /projects/:id/eval-runs': d('Evals', "A project's eval runs", { description: 'Newest first. `eval` keeps one eval\'s runs; pass `next` back as `before` for the following page. 404 for an unknown project.', params: obj({ id: str('Project id') }), querystring: obj({ eval: str('Eval name'), before: str('`next` of the previous page'), limit: { type: 'integer', description: 'Runs per page: at most 50' } }), ok: ref('EvalRunPage') }),
  'GET /eval-runs/:runId': d('Evals', 'An eval run', { description: 'The run with its definition as run, its variants and its samples with their checks. The tool calls are left out; they come with one sample.', params: obj({ runId: str('Run id') }), ok: ref('EvalRun') }),
  'GET /eval-runs/:runId/samples/:sampleId': d('Evals', 'One sample of an eval run', { description: 'The sample with its tool calls, its checks and its final text.', params: obj({ runId: str('Run id'), sampleId: str('Sample id') }), ok: ref('EvalSampleDetail') }),
  'GET /eval-runs/:runId/compare': d('Evals', 'Compare two variants of an eval run', { description: 'Per case, how many scored samples passed in each variant, and whether the case regressed, improved or stayed the same. It states facts and gives no verdict on whether to promote. 400 when a variant is not in the run.', params: obj({ runId: str('Run id') }), querystring: obj({ base: str('Variant to compare from (`current` by default)', { enum: ['pinned', 'current', 'proposed'] }), other: str('Variant to compare with (`proposed` by default)', { enum: ['pinned', 'current', 'proposed'] }) }), ok: ref('EvalComparison') }),
  'POST /eval-runs/:runId/cancel': d('Evals', 'Cancel an eval run', { description: 'Stops the running samples and ends the run `cancelled`. Idempotent: a run that already ended is answered as it is.', params: obj({ runId: str('Run id') }), ok: ref('EvalRunSummary') }),
  'POST /eval-runs/:runId/resume': d('Evals', 'Resume an eval run', { description: 'Re-queues the unscored samples of an `interrupted` or `capped` run, from the variants as that run stored them. `confirmMaxCostUsd` must equal the new ceiling: what was spent plus the worst case of what is left. 409 `not-resumable`, `cost-not-confirmed` or `eval-running`; 412 `consent-needed` when the file\'s content is no longer accepted. Refused to a chat\'s token (403).', params: obj({ runId: str('Run id') }), body: ref('ResumeEvalRunRequest'), ok: ref('EvalRunSummary') }),
  'GET /eval-runs/:runId/gate': d('Evals', 'The promotion gate of an eval run', { description: 'Phase 2. For a run with `current` and `proposed`: `may-promote`, `regressed` (with the cells that fell; a fall of the mean alone leaves the list empty) or `incomplete` (unjudged, unscored or too few samples in a `mustHold` cell, or an unaccepted unreliable judge). It states a verdict and applies nothing. 404 when the run has no gate yet; 409 `evals-phase2-off` while the switch is off.', params: obj({ runId: str('Run id') }), ok: ref('EvalGate') }),
  'POST /eval-runs/:runId/rejudge': d('Evals', 'Re-judge the unjudged samples of an eval run', { description: 'Phase 2. Judges again the samples a judge could not decide (a usage limit, an error), from their stored calls and final text: no sample runs again. Re-scores them and recomputes the gate. 409 `eval-running` while a re-judge of this run is in progress; 409 `evals-phase2-off`. Refused to a chat\'s token (403).', params: obj({ runId: str('Run id') }), ok: obj({ rejudged: { type: 'integer' }, unjudged: { type: 'integer' } }) }),
  'POST /eval-runs/:runId/accept-judge': d('Evals', 'Accept an unreliable judge', { description: 'Phase 2. The person accepts a judge that disagreed with its calibration examples, so the gate stops being `incomplete` for it. Answers the recomputed gate. 400 for a bad body; 404; 409 `evals-phase2-off`. Refused to a chat\'s token (403).', params: obj({ runId: str('Run id') }), body: obj({ caseId: str('Case id'), idx: { type: 'integer', description: 'Index of the judged expectation in the case' } }), ok: ref('EvalGate') }),
  'POST /projects/:id/evals/:name/draft-cases': d('Evals', 'Draft cases for an eval with the assistant', { description: 'Phase 2. Starts an assistant run of kind `evals` that reads the target file and proposes up to five cases (a supportive and a neutral prompt, deterministic expectations first); accepting a proposal appends it through the file write with `ifMatch`. 404 for a missing eval; 409 `evals-phase2-off` or the daily `spend-cap`. Refused to a chat\'s token (403).', params: obj({ id: str('Project id'), name: str('Eval name, without `.json`') }), body: obj({ model: str('Model of the run'), effort: str('Effort of the run') }), ok: ref('AssistantRun'), created: true }),
  'DELETE /eval-runs/:runId': d('Evals', 'Delete an eval run', { description: 'Removes an ended run with its samples, calls and checks. 409 `eval-running` while it is live. Refused to a chat\'s token (403).', params: obj({ runId: str('Run id') }), ok: OK }),
  'GET /eval-runs/:runId/export': d('Evals', 'Export an eval run as JSON or Markdown', { description: 'A download (`content-disposition: attachment`). `json` (default) is `{ version, run, calls }`: the run, its definition as run and every sample\'s calls. `markdown` is for a person: the variants, the tally, and each case with its samples and failing checks. Accepts the credential as `?token=`.', params: obj({ runId: str('Run id') }), querystring: obj({ format: str('Output format', { enum: ['json', 'markdown'] }) }) }),
  'GET /projects/:id/flow': d('Team', "What a project's flow is doing", { description: "The flow by column's runs going now (oldest first) and queued (in the order they will start), each with its item, role, agent, model and stage, and the chat it runs in once started. `enabled` is `flow.enabled` with the Team and Board modules on; `maxParallel` is the per-project cap (2 unless the settings say otherwise). Readable with the flow off. Each run is announced as `flow.run` (`queued`, `started`, `ended`).", params: obj({ id: str('Project id') }), ok: ref('ProjectFlow') }),
  'GET /projects/:id/flow/runs': d('Team', "The team's activity", { description: "Every flow run of the project, newest first (in the order they were queued), a page at a time: queued, running and ended, each with its item, member, stage and step (`check` is the Product Owner's refine in todo), outcome, error, cause (a code to word in the person's language) and chat, and for a failed run whether it can be retried and the run that came after it. `agent`, `role` and `status` are comma separated lists of alternatives (`status` is `queued`, `running` or an outcome: `passed`, `rejected`, `failed`, `cancelled`; `outcome` is another name for it); `itemId` keeps one item's runs and `before` those queued before a moment (ISO 8601). `total` counts every run that passes the filter; pass `nextCursor` back as `cursor` for the next page, which a run queued meanwhile does not shift. Readable with the flow off. 400 for an unknown status, a limit out of range, a `before` that is not a date or a cursor this list did not give out.", params: obj({ id: str('Project id') }), querystring: obj({ agent: str('Members, by agent file name, comma separated'), role: str('Members, by team role, comma separated'), status: str('Run statuses, comma separated'), outcome: str('Another name for `status`'), before: str('Runs queued before this moment (ISO 8601)'), itemId: str('Runs of this work item only'), limit: { type: 'integer', description: 'Runs per page: default 50, at most 200' }, cursor: str('`nextCursor` of the previous page') }), ok: ref('FlowRunPage') }),
  'GET /projects/:id/flow/waiting': d('Team', 'The cards waiting for the flow', { description: "The cards switching the flow on did not start, since only a card entering a column starts a run: those that are not epics nor done, in a column whose role has a member playing it, with no flow run queued or running, and, in todo, not refined and left unchanged since. `total`, and per column (in board order, only those with a waiting card) the role that answers for it and the count. `total` is 0 while the flow, the Team module or the Board module is off. 404 for an unknown project.", params: obj({ id: str('Project id') }), ok: ref('FlowWaiting') }),
  'POST /projects/:id/flow/start-waiting': d('Team', 'Start the waiting cards', { description: "Queues one flow run per waiting card (as `GET /projects/:id/flow/waiting` counts them), as if each had just entered its column, in board order: backlog, todo, in progress, in review, and by rank inside each. The waiting test runs again as they are queued, so calling it twice queues nothing the second time. Each run has `queuedBy: \"person\"`. `startingNow` is `min(queued, maxParallel − running)`; the rest wait in the queue. 409 while the flow is off, 404 for an unknown project. Emits `flow.run` (`queued`) per run.", params: obj({ id: str('Project id') }), ok: ref('FlowStartWaitingResult') }),
  'GET /work-items/:itemId/runs': d('Team', "A work item's flow runs", { description: "Every run the flow by column made on the item, newest first, whatever its state: an older failed run still reads as failed, with its error and its chat, and a chat's page finds the run it was for by `chatId`. Readable as the item is.", params: ITEM, ok: list('FlowRun') }),
  'POST /work-items/:itemId/spend-pass': d('Team', "Let a held card's run start past today's spend cap", { description: "Records the card's pass for today (the server's local day, a row in `flow_spend_passes`) so its queued flow run starts although the daily cap was reached; tomorrow it is under that day's cap. The same mechanism as `POST /orchestrations/:id/spend-pass`. Answers `{ itemId, day }`; 404 for an unknown item. Refused to a chat's token with `403`.", params: obj({ itemId: str('Work item id') }), ok: ref('FlowSpendPass') }),
  'POST /flow-runs/:runId/retry': d('Team', 'Retry a failed flow run', { description: "Queues the failed run's step again on its item, as the member who answers for the run's column now; the new run's `retryOf` names the failed one, whose `retriedBy` then names the new one. Counts as a person's move: the item starts a new round (its bounces back to 0 and whatever it waited for cleared), and a todo check runs even on an item refined since. 409 unless the run failed, nothing has run that step on the item since (a retry or the card entering the column again), the item is still in the run's column, and the flow is on with a member answering for it (`retryable` on the run says so beforehand); 404 for an unknown run. Emits `flow.run` (`queued`).", params: obj({ runId: str('Flow run id') }), ok: ref('FlowRun'), created: true }),
  // ---- Assistant
  'POST /projects/:id/assistant/runs': d('Assistant', 'Start an assistant run', { description: "`project` proposes a team, resources and first work items (only the kinds whose modules are on: team members need Team, work items need Board); `work-items` proposes work items (409 with the Board module off), in the area `focus` names when it is given (400 on another kind); `resources` proposes agents, skills and commands, or with `description` and `resourceKind` builds that one resource (\"Create with AI\"). `model` defaults to `sonnet`. One run at a time per project and kind (409). `supersede` sets the latest finished run's pending proposals aside (\"Suggest again\"). The chat is titled in the language of `Accept-Language`, which the run keeps for a restart. A project with nothing to read (no files, no chats, no git history) and no `description` or `focus` starts no chat: the run completes at once, `empty`, with its template's team offered. Emits `assistant.run` with `started`, `read` while it reads, and `ended` or `failed`.", params: obj({ id: str('Project id') }), body: ref('StartAssistantRunRequest'), ok: ref('AssistantRunDetail'), created: true }),
  'GET /projects/:id/assistant/runs': d('Assistant', "A project's assistant runs", { description: 'Latest first, the last 50, of every kind unless `kind` names one. Each carries what it read, what it found, its proposals counted by kind and status, its model, cost and duration.', params: obj({ id: str('Project id') }), querystring: obj({ kind: str('`project`, `work-items` or `resources`') }), ok: list('AssistantRun') }),
  'GET /assistant/runs/:runId': d('Assistant', 'An assistant run with its proposals', { description: "Every proposal it made, by kind (team, resources, work items) then in its order. A work item proposal names the existing epic it belongs to and an existing item it resembles (`similarTo`), and, once accepted, the item it created. A running \"Create with AI\" carries `draft`, the file as its chat has written it so far, refreshed through `assistant.run` events with `read`.", params: obj({ runId: str('Assistant run id') }), ok: ref('AssistantRunDetail') }),
  'POST /assistant/runs/:runId/stop': d('Assistant', 'Stop an assistant run', { description: 'Stops its chat; a stopped run proposes nothing. Refused with 409 unless it is running. Emits `assistant.run` with `ended` and status `stopped`.', params: obj({ runId: str('Assistant run id') }), ok: ref('AssistantRunDetail') }),
  'POST /assistant/chats': d('Assistant', 'Start a Claudio assistant chat', { description: "A global chat that answers about Claudio (projects, the board, orchestrations, chats, usage) through Claudio's own MCP server. It has no built-in tool, no settings file and no uploads directory, runs in `dontAsk` and is never switched to `bypassPermissions`; resume, fork and a restart apply the same confinement again, whatever a request asks (`allowedTools`, `disallowedTools`, `toolPreset`, `mcp`, `permissionMode` and `appendSystemPrompt` are ignored on it), and a fork of it is an assistant chat. `projectId` is context, not a requirement (404 when unknown); the chat runs in its directory when it exists, else in the workspace. `model` defaults to `sonnet`. The answer language is read from `Accept-Language` and kept on the chat. Answers what `POST /chats` answers (`Chat.claudioAssistant` tells it apart); 400 for an empty prompt.", body: ref('StartClaudioAssistantChatRequest'), ok: ref('ChatSummary'), created: true }),
  'POST /assistant/proposals/:proposalId/accept': d('Assistant', 'Accept a proposal', { description: "Writes it, with the person's edits: a team member through the team service, agent file included (409 with the Team module off, or when the agent or its role is already on the team); a resource saved at its scope, which is the editor's save (409 when one of that name exists there); a work item created in `backlog` with its reason as its first comment (409 with the Board module off). Refused with 409 unless the proposal is pending; if writing fails it stays pending. Emits `assistant.proposal` with `accepted`, and what the write emits itself (`team.changed`, `workitem.created`).", params: obj({ proposalId: str('Proposal id') }), body: ref('AcceptAssistantProposalRequest'), ok: ref('AssistantProposal') }),
  'POST /assistant/proposals/:proposalId/discard': d('Assistant', 'Discard a proposal', { description: 'Nothing is written. Refused with 409 unless it is pending. Emits `assistant.proposal` with `discarded`.', params: obj({ proposalId: str('Proposal id') }), ok: ref('AssistantProposal') }),
  'POST /assistant/proposals/:proposalId/restore': d('Assistant', 'Restore a discarded proposal', { description: 'It waits for the person again. Refused with 409 unless it was discarded. Emits `assistant.proposal` with `restored`.', params: obj({ proposalId: str('Proposal id') }), ok: ref('AssistantProposal') }),
  // ---- Events
  'GET /events': d('Events', 'Live feed of everything that changes (Server-Sent Events)', {
    description:
      'One stream for the whole app. Every message has an SSE `id`, an `event:` line naming its `type` and `data: <ClaudioEvent JSON>`: run created/updated/ended/removed, prompts waiting for a person (`run.waiting`, `permission.*`), rate limits and account rotation, background tasks, subagents and workflows starting and ending, orchestration, task and merge-conflict changes, what each chat is doing right now (`chat.activity`) and what each subagent is doing (`subagent.activity`), schedules created, edited, switched, rescheduled or deleted (`schedule.changed`) and every run row a schedule writes (`schedule.fired`), work items created, updated, moved and removed (`workitem.*`), milestones created, edited, closed, reopened or deleted (`milestone.changed`), a project imported or created (`project.created`), removed (`project.removed`), or its name, key, modules or settings changing (`project.updated`), `sessions.changed` when the CLI writes under its projects directory, `system.release` once per newer Claudio release a check finds, and Collaborators: `collaborators.changed` (settings, roster, links or sharing), `collaborators.peer` (a teammate install online or offline, and its path), `collaborators.synced` (a kind of a shared project copied from its owner) `collaborators.join-request` (on the owner install, a join waiting for an answer) `collaborators.join-answered` (that join accepted, denied or dropped) and `collaborators.join-ended` (on the joining install, its join denied or its invite expired unanswered). Events describe what changed and carry the ids to refetch it; `run.updated` and `workflow.progress` are coalesced to about one per 250 ms, `chat.activity` to at most one per chat per second, and `subagent.activity` to at most one per subagent per second. The stream opens with `stream.hello` (no id) carrying the server `bootId` and the Claudio `version` it runs. Reconnect with `Last-Event-ID` (or `since`) to receive what was missed from a bounded in-memory buffer; when that id has fallen out of it, or belongs to a previous server process, `stream.resync` is sent instead and the client must refetch everything it shows. A `: ping` comment is sent every 15 s.',
    querystring: obj({ since: str('Last event id already received; the `Last-Event-ID` header wins') }),
    ok: ref('ClaudioEvent'),
    produces: 'text/event-stream',
  }),

  // ---- Chats
  'GET /chats': d('Chats', 'Chats, newest first', {
    description:
      'One entry per Claude Code conversation, whoever started it and however many times it was resumed: the id is the session id. Workers of an orchestration and housekeeping chats are left out unless asked for with `origin`. `state` says what is happening (`working`, `waiting` for a person, `idle`), `control` what can be done now and why not when it cannot. `assistant=1` keeps only the chats of the Claudio assistant.',
    querystring: obj({
      project: str('Only chats of this project'),
      loose: str('`1` for chats under no project'),
      origin: str('Comma-separated origins to include: `claudio`, `external`, `orchestration`, `internal` (default `claudio,external`)'),
      workers: str('`0` leaves out the workers of orchestrations and keeps their syntheses, which share the `orchestration` origin', { enum: ['0', '1'] }),
      state: str('Only chats in this state', { enum: ['working', 'waiting', 'idle'] }),
      assistant: str('`1` for the chats of the Claudio assistant only', { enum: ['1'] }),
      limit: str('Max chats to return'),
    }),
    ok: list('ChatSummary'),
  }),
  'GET /spend': d('Usage', "Today's spend against the daily cap", { description: "The sum of the `total_cost_usd` each `result` reported today (the server's local day), against the cap: `level` is `off` with no cap, `ok` below 60 %, `warn` from 60 %, `bad` from 75 % and `exhausted` from 100 %, and `blocked` says whether new work waits. `unreported` counts results without a cost, which are never estimated. A chat's token may read it.", ok: ref('SpendState') }),
  'GET /usage': d('Chats', 'What the chats spent, per day, per project and per orchestration', {
    description:
      'Tokens come from the transcripts, so they cover every chat, subagents included, and are kept per model with the variant suffix whole. The cost is what the CLI reported (`total_cost_usd`), which exists only for chats Claudio launched: nothing is estimated from a price table, `costUsd` is `null` when nothing reported one, and `chatsWithoutCost` counts the chats a total leaves out. A day is a calendar day where the server runs; a cost is put on the day its execution ended.',
    querystring: obj({ from: str('First day, `YYYY-MM-DD` (inclusive)'), to: str('Last day, `YYYY-MM-DD` (inclusive)') }),
    ok: ref('UsageReport'),
  }),
  'GET /usage/series': d('Chats', 'Cost and tokens over time, by day or by week', {
    description:
      'One point per bucket from `from` to `to`, empty buckets included so a chart has no gaps; without a range it spans the days that have something, up to today. A week starts on Monday and is named by that day. Days are cut by the range before they are bucketed, so the first week of a range that starts mid-week holds only the days asked for. `costUsd` is what the CLI reported and is `null` for a bucket where no chat reported one: nothing is estimated from token counts. At most 1000 points.',
    querystring: obj({ bucket: str('Width of a point', { enum: ['day', 'week'] }), from: str('First day, `YYYY-MM-DD` (inclusive)'), to: str('Last day, `YYYY-MM-DD` (inclusive)') }),
    ok: ref('UsageSeries'),
  }),
  'GET /usage/breakdown': d('Chats', 'What the chats spent, per project and per model', {
    description:
      'The same range cut two ways, most spent first. Tokens come from the transcripts and cover every chat. The cost per model is the CLI\'s own (`modelUsage[model].costUSD` of each result); an execution recorded before Claudio kept that split is put on the model it ran. `costUsd` is `null` for a slice no chat reported a cost for. Chats under no project are the slice `loose`; messages that named no model are the slice `unknown`.',
    querystring: obj({ from: str('First day, `YYYY-MM-DD` (inclusive)'), to: str('Last day, `YYYY-MM-DD` (inclusive)') }),
    ok: ref('UsageBreakdown'),
  }),
  'GET /chats/:id/export': d('Chats', 'Export a chat\'s transcript as Markdown or JSON', {
    description:
      'A download. `markdown` (default) is for a person: a header with the project, models, cost as the CLI reported it and tokens, then the turns, each tool call folded into a `<details>` block with its result (results over 4000 characters are cut) and subagent messages left out. `json` is a `ChatExport`: the chat and every transcript entry in order, subagents included, nothing cut.',
    querystring: obj({ format: str('Output format', { enum: ['markdown', 'json'] }) }),
    ok: ref('ChatExport'),
  }),
  'POST /chats': d('Chats', 'Start a chat', { description: 'Spawns `claude -p` with stream-json I/O under a session id Claudio chooses. With `keepAlive` (default) the process stays up for follow-up turns.', body: ref('NewChatRequest'), ok: ref('ChatSummary'), created: true }),
  'GET /chats/:id': d('Chats', 'A chat and a window of its transcript', {
    description:
      'The chat with its branches (subagents, background tasks, workflows), environment and `health` — computed when it is read, so a chat that is working should be read again: a command that has run too long sends no event — and the newest `limit` transcript entries by default — a long conversation runs to tens of megabytes, which nobody reads at once. `from` is the index the window starts at and `total` what the transcript holds, so passing the `from` of a page back as `before` reads the one before it. A chat with no transcript (housekeeping, or one that has not written its first line) is read from what its process streamed.',
    querystring: obj({ sidechains: str('`1` includes subagent messages'), limit: str('Entries per page (default 200, max 1000)'), before: str('Index to read backwards from: the `from` of the previous response') }),
    ok: ref('ChatDetail'),
  }),
  'GET /chats/:id/search': d('Chats', 'Search the whole transcript', { description: 'Case-insensitive plain-text match over what the transcript view shows of each entry: text, thinking, tool names and inputs, tool results. Any run of whitespace in `q` matches any run in the text. One hit per matching entry, `index` in the same space as a page\'s `from` and `total`, so a hit on a page not loaded yet is reached by reading back to it. At most 500 hits, the newest; `truncated` says older ones were left out.', querystring: obj({ q: str('Text to find (required, up to 200 characters)'), sidechains: str('`1` includes subagent messages, as the page read with it does') }, ['q']), ok: ref('TranscriptSearchResult') }),
  'GET /chats/:id/changes': d('Chats', 'What a chat changed on disk', {
    description: `For a chat in a git worktree, the branch, its base, the commits and the files it changed against that base, what it has not committed yet, and \`working\`: every file that differs from the base in the working tree, with the counts its default diff shows. Any chat also gets the files its \`Write\`/\`Edit\`/\`NotebookEdit\` calls touched, read from the transcript, so a chat outside git still answers. A worker of an orchestration is measured from where its own branch was cut. ${SCOPE_NOTE}`,
    querystring: SCOPE_QUERY,
    ok: ref('ChatChanges'),
  }),
  'GET /chats/:id/changes/diff': d('Chats', 'The diff of one file of a chat in a worktree', {
    description: `Everything the branch did to the file since its base, committed or not. A file created and not yet added shows as all new. Refused for a chat with no worktree of its own. ${DIFF_NOTE}`,
    querystring: DIFF_QUERY,
    ok: ref('FileDiff'),
  }),
  'GET /chats/:id/changes/steps': d('Chats', 'Every edit a chat made, step by step', {
    description: STEPS_NOTE,
    ok: list('EditStep'),
  }),
  'GET /chats/:id/checklist': d('Chats', "The chat's own checklist", {
    description: 'The plan the agent kept with its `TaskCreate`/`TaskUpdate` or `TodoWrite` calls, as of its last update. Empty for one that never planned.',
    ok: ref('Checklist'),
  }),
  'GET /chats/:id/stream': d('Chats', 'Live event stream (Server-Sent Events)', {
    description:
      'Replays buffered events with `seq > since` (or `Last-Event-ID`), then streams live ones. Each message is `data: <RunEvent JSON>`. Ephemeral `partial` events carry the text generated so far (token streaming); they have no SSE id and are never replayed. Only a chat Claudio has driven has a stream; to follow one, take the last event\'s `seq` from the page you hold and pass it as `since`.',
    querystring: obj({ since: str('Last seq already received') }),
    ok: ref('RunEvent'),
    produces: 'text/event-stream',
  }),
  'POST /chats/:id/resume': d('Chats', 'Continue a chat in place', { description: 'Adds an execution to the same chat, which keeps its id: it never creates one. Whether something else holds the session is checked on the server at this moment, from the CLI\'s own list and the process table, whatever the client last saw. A chat from a terminal that nothing holds is adopted and stays `external`; one a terminal holds, or that belongs to an orchestration, is refused with 409 and the reason, and `fork` is the way forward. The chat keeps its tools and MCP servers unless the request picks others; with no `mcp`, the config file the CLI reads is written again from the current definitions of the same servers, so a server edited since starts as it is now (one removed since is left out). `account: null` unpins a chat pinned to one account.', body: ref('ResumeChatRequest'), ok: ref('ChatSummary') }),
  'POST /chats/:id/fork': d('Chats', 'Continue a chat in a copy', { description: 'Creates a new chat with the same history that records where it came from (`derivedFrom`), and leaves the original untouched. Available on any chat, held or not. The copy runs with the source\'s tools and MCP servers (preset, allowed and disallowed tools, server selection, the servers as they are defined now) unless the request picks others.', body: ref('ForkChatRequest'), ok: ref('ChatSummary'), created: true }),
  'POST /chats/:id/account': d('Chats', "Switch a chat's account", { description: "A person's choice from the composer: the chat's next execution resumes the same session under `accountId`, with that account's own sign-in. An idle chat moves at once (a live process is ended between turns); a working chat keeps its turn and moves when it ends, answering `pending: true`. Naming the chat's current account while a switch is pending cancels it (`pending: false`). The choice is not a pin: the rotation still moves the chat at a limit. Recorded as a rotation event with reason `person`. 400 for a missing `accountId`; 404 for an unknown chat or account; 409 with a `code` (`disabled`, `sign-in-expired` for a `signInState` of `expired` or `incomplete`, `signed-out`, `exhausted`, `model-unavailable`, `same-account`) when the account cannot be chosen. Refused to a chat's token with 403.", params: obj({ id: str('Chat id') }), body: ref('SwitchChatAccountRequest'), ok: ref('SwitchChatAccountResponse') }),
  'POST /chats/:id/wait': d('Chats', 'Wait for the limit to reset', { description: 'A person\'s choice at the banner: the chat stays where it is and its turn goes on when the provider\'s limit resets (or when a later reading says it is over), up to the longest wait the settings allow. Answers with the wait, a `waiting` row of `GET /limits/waits`. `409` when the chat has not reached a limit or is already waiting. Refused to a chat\'s token with 403.', params: obj({ id: str('Chat id') }), ok: ref('ProviderMove'), created: true }),
  'POST /chats/:id/messages': d('Chats', 'Send another turn', { description: 'To a chat with a live execution. `attachments` are upload ids from `POST /uploads`; with attachments the text may be empty. A chat without one is refused with 409: resume it. `id` is a UUID the client chooses so a retry is written once: a second request with an id already taken writes nothing and answers as the first did (`message.duplicate`). The answer is the chat with `message`: the id the message goes by and how it was taken (`written` into the running turn, `started` a turn, `held` for the process that replaces one on its way out). The chat stream then carries a `delivery` event when the agent takes it, or when it is lost (docs/chat-delivery.md).', body: ref('ChatMessageRequest'), ok: ref('ChatMessageResponse') }),
  'POST /chats/:id/stop': d('Chats', 'Stop what is working on the chat', { description: 'The execution Claudio runs, or for a background session the CLI itself holds, `claude stop`, so no pid is signalled directly. The conversation is kept and can be resumed.', ok: ref('ChatSummary') }),
  'POST /chats/:id/interrupt': d('Chats', 'Interrupt the current turn', { description: 'Ends the turn in progress and keeps the process, which reads what waits for it, then the next message. Any prompt the chat was holding is withdrawn. With `messageId` ("Send now"), only while that message still waits in the agent\'s queue: once the agent has read it, or it is not waiting in this chat, the answer is 409 and nothing is interrupted.', body: ref('ChatInterruptRequest'), ok: ref('ChatSummary') }),
  'POST /chats/:id/hint': d('Chats', 'Send a hint to a chat that is working', { description: 'A nudge: the text reaches the worker as its next user message. For a chat whose process is up; one with none is refused with 409, and a message resumes it. The suggested text for each signal of the chat\'s health is on the signal (`hint`).', body: ref('HintRequest'), ok: ref('ChatSummary') }),
  'POST /chats/:id/commands/:toolUseId/cancel': d('Chats', 'Cancel one command without ending the turn', { description: 'Kills the process tree of one shell command the chat is running, found under the CLI process by the tree and by when each process started, never by matching a command line. The CLI hands the worker a failed result for that call and the turn goes on; the worker is told a person did it. Refused with 409 when the call is not a command that is running, or its process cannot be told apart from another. Needs `/proc`, so Linux only. Which call to cancel is on the health signal (`toolUseId`).', body: ref('CancelCommandRequest'), ok: ref('CancelCommandResult') }),
  'GET /settings/supervisor': d('Chats', 'Supervisor settings (deprecated)', { deprecated: true, description: "Deprecated: the Supervisor is the `supervisor.intervene` decision point; read `GET /decisions/settings`. The optional supervisor is a housekeeping chat of the CLI that wakes once per signal per chat when a worker's health turns `bad`, reads the signal and the worker's last steps, and drafts a hint of a line or two. This view is derived from the point: `enabled` is its mode not being `off`, `autoSend` its mode being `active`; `model` and `maxCostUsd` are the engine's `cli.model` and `cli.maxCostUsd`.", ok: ref('SupervisorConfig') }),
  'PUT /settings/supervisor': d('Chats', 'Change the supervisor settings (deprecated)', { deprecated: true, description: "Deprecated: set the `supervisor.intervene` point's mode through `PUT /decisions/settings`. Maps `enabled` and `autoSend` onto that mode (`enabled: false` is `off`, `enabled` alone `shadow`, which proposes hints for a person to send, `enabled` with `autoSend` `active`, which sends them on its own and, under Jev, only when the engine expects a hint to help); `model` and `maxCostUsd` are accepted and ignored, the engine's CLI settings being the Supervisor's. Answers the derived view. Refused to a chat's token with 403.", body: ref('UpdateSupervisorConfigRequest'), ok: ref('SupervisorConfig') }),
  // ---- Decisions
  // ---- Providers
  'GET /hosts': d('Integrations', 'Every code host\'s status', { description: 'One status per code host (GitHub through `gh`, GitLab through `glab`), from the detector\'s cache (5 minutes; a stale one is answered and re-detected in the background). `state` says whether it is ready and `reason` why not; `hosts` lists the host names the CLI knows and whether it is signed in to each.', ok: list('CodeHostStatus') }),
  'POST /hosts/refresh': d('Integrations', 'Detect the code hosts again now', { description: 'Skips the cache and runs every enabled host\'s probes, each under its own timeout. Emits `hosts.changed` when a status differs. Refused to a chat\'s token with 403.', ok: list('CodeHostStatus') }),
  'GET /hosts/settings': d('Integrations', 'Code host settings', { description: 'The document from `hosts.json`: per host whether it is enabled and the binary to use instead of searching for one. Absent until the first save, which reads as every host on.', ok: ref('CodeHostsSettings') }),
  'PUT /hosts/settings': d('Integrations', 'Change the code host settings', { description: 'Replaces the document, validated: known host ids, `binaryPath` absolute or null. A host left out keeps the defaults. Hosts are detected again in the background, every project\'s readiness is read again, and `hosts.changed` follows. A disabled host\'s projects read `unsupported-host`. Refused to a chat\'s token with 403.', body: ref('CodeHostsSettings'), ok: ref('CodeHostsSettings') }),
  'GET /hosts/:id': d('Integrations', 'One code host\'s status', { description: '404 for an id that is not a code host.', params: obj({ id: str('Code host id: `github` or `gitlab`') }), ok: ref('CodeHostStatus') }),
  'GET /trackers': d('Integrations', 'Every issue tracker\'s status', { description: 'One status per tracker: `github-issues` and `gitlab-issues` reuse the CLI and the sign-in of their code host (`gh`, `glab`) and are `ready` when the host is; `youtrack` runs `youtrack-app` with the address and token Claudio keeps, and is `signed-out` with `no-credentials` or `token-rejected`, or `unknown` with `host-unreachable`, until the instance answers; a tracker turned off is `unknown` with no reason.', ok: list('TrackerStatus') }),
  'POST /trackers/refresh': d('Integrations', 'Detect the trackers again now', { description: 'Detects the code hosts again, then derives every tracker from them. Refused to a chat\'s token with 403.', ok: list('TrackerStatus') }),
  'GET /trackers/settings': d('Integrations', 'Tracker settings', { description: 'The document from `trackers.json`: per tracker whether it is enabled and the binary to use instead of its host\'s. Absent until the first save, which reads as every tracker on.', ok: ref('TrackersSettings') }),
  'PUT /trackers/settings': d('Integrations', 'Change the tracker settings', { description: 'Replaces the document, validated: known tracker ids, `binaryPath` absolute or null. A tracker left out keeps the defaults. The trackers are detected again in the background. Refused to a chat\'s token with 403.', body: ref('TrackersSettings'), ok: ref('TrackersSettings') }),
  'GET /trackers/youtrack/credentials': d('Integrations', 'What is saved for YouTrack', { description: "The instance address, whether a token is saved and whether it is encrypted with the desktop app's key. The token itself is never returned. Refused to a chat's token with 403.", ok: ref('YoutrackCredentialsStatus') }),
  'PUT /trackers/youtrack/credentials': d('Integrations', 'Save the YouTrack address and token', { description: "The address of the instance (for YouTrack Cloud, with its `/youtrack` path when it has one) and a permanent token, kept in a 0600 file and handed to `youtrack-app` only in its environment. Leave `token` out to keep the saved one. YouTrack is detected again before the answer. Refused to a chat's token with 403.", body: ref('PutYoutrackCredentialsRequest'), ok: ref('YoutrackCredentialsStatus') }),
  'DELETE /trackers/youtrack/credentials': d('Integrations', 'Forget the YouTrack address and token', { description: "Removes the file; YouTrack reads `signed-out` with `no-credentials` afterwards. Refused to a chat's token with 403.", ok: ref('YoutrackCredentialsStatus') }),
  'GET /trackers/:id': d('Integrations', 'One issue tracker\'s status', { description: '404 for an id that is not a tracker.', params: obj({ id: str('Tracker id: `github-issues`, `gitlab-issues` or `youtrack`') }), ok: ref('TrackerStatus') }),
  // ---- Change requests: checks and their fixes
  'GET /change-requests/:id': d('Integrations', 'One change request, neutral', { description: "The pull or merge request of a work item or an orchestration, by the row id of either table (UUIDs, unique across both): `kind` says which and `ownerId` is the item's or the orchestration's id. Carries the host, `ref` (`#12` on GitHub, `!12` on GitLab), phase, the CI rollup as the watcher last read it, and the fix state (`fixState`, `fixOrigin`, `fixAttempts`, `fixHead`). 404 for an id no table has.", params: CHANGE_REQUEST, ok: ref('ChangeRequest') }),
  'GET /change-requests/:id/checks': d('Integrations', "The checks of a change request's head commit", { description: "One read of the head commit's checks, shared by the board and every open page: an answer under 30 s old is served from the store, and `?refresh=1` skips it. Each check has its state (`queued`, `running`, `passed`, `failed`, `cancelled`, `skipped`, `manual`, `neutral`), whether the pipeline lets it fail (`allowedToFail`, shown as a warning), whether a rule of the base branch needs it (`required`), `rerunnable` and `hasLog`. `truncated` marks a list cut at its ceiling. While the host's rate limit is used up the last list is answered with `limitedUntil`. A refusal carries a `code`, the host's reason: 404 `not-found`; 409 for a host that is signed out or refuses (`cli-signed-out`, `auth-failed`, `forbidden`, `cli-missing`); 429 `rate-limited` with no earlier list to serve; 502 `unreachable`, `server-error` or `timeout`.", params: CHANGE_REQUEST, querystring: obj({ refresh: str('`1` reads from the host now instead of serving a stored answer', { enum: ['1'] }) }), ok: ref('ChangeRequestChecks') }),
  'GET /change-requests/:id/checks/:checkId/log': d('Integrations', "The tail of one check's log", { description: "The last 200 lines (16 KiB) of the job's log plus windows around its first error markers, with escape sequences, carriage returns, section markers and secrets removed; each line is cut at 500 characters. `truncated` says lines were left out. `noOutputYet` marks a running or never-run job that has printed nothing, which is not an unavailable log. `annotations` are what the check says about files, best effort: a failed read gives an empty list. A check with no log (a bridge, a commit status, another app's check) answers 409 `log-unavailable`.", params: CHECK, ok: ref('CheckLog') }),
  'POST /change-requests/:id/checks/rerun': d('Integrations', 'Run checks again', { description: "Asks the host to run the failed jobs (`scope: failed`), one job (`scope: check` with `checkId`) or everything (`all`) again, then reads the list again and answers it. Never retried: a timeout is answered 409 `write-unconfirmed` after that re-read, a host that refuses 409 `rerun-refused`, a check the host cannot run again 409 `check-not-rerunnable`. Calls for one change request are serialised, so a double click never overlaps. 400 for a scope or `checkId` that does not fit. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('ChecksRerunRequest'), ok: ref('ChangeRequestChecks') }),
  'POST /change-requests/:id/checks/cancel': d('Integrations', 'Cancel the running checks', { description: "Cancels the head pipeline or the running workflow runs, then reads the list again and answers it. A host answers `running`, then `canceling`, never `canceled` at once, so a cancel counts as done when nothing is queued or running after the re-read. Never retried. Refused to a chat's token with 403.", params: CHANGE_REQUEST, ok: ref('ChangeRequestChecks') }),
  'POST /change-requests/:id/checks/:checkId/run': d('Integrations', 'Play a manual job', { description: "GitLab only: plays a job waiting for a person (`state: manual`; it keeps its id), then reads the list again and answers it. A failed call counts as done when the job is no longer manual. 409 `check-not-rerunnable` for a check that is not a manual job. Refused to a chat's token with 403.", params: CHECK, ok: ref('ChangeRequestChecks') }),
  'POST /change-requests/:id/checks/fix': d('Integrations', 'Fix the failing checks', { description: "Starts a fix of the failing checks on the head commit (an allowed failure is not one). For a work item the row stays open with `fixState: fixing`, the item moves to In progress (cause `pr.checks-fix`, the person's) and the flow's Developer starts with each failure's log tail in its prompt, as untrusted data; QA verifies the result and, for a person's fix, Claudio then pushes with no second click (a plain push, never forced). With the project's flow off nothing moves and `started` is false: `prompt` and `worktree` are for a chat of the person's own. For an orchestration a chat runs in the integration worktree with the fixer's model and cost limit and commits there; the person then pushes it with `push-fix`. The fix is of the owner's newest change request. 409 with a `code`: `not-open`, `fix-under-way`, `busy`, `no-failing-checks`, `not-in-review`, `checks-unavailable`, `no-worktree` or `fix-unavailable` (orchestrations), or the host's reason. Refused to a chat's token with 403.", params: CHANGE_REQUEST, ok: obj({ started: { type: 'boolean', description: "False when the project's flow is off and nothing moved" }, prompt: str('The prompt the fixer got, or the one to take to a chat'), worktree: { type: ['string', 'null'], description: 'Where the work is, or would be' }, pullRequest: { anyOf: [ref('WorkItemPullRequest'), ref('OrchestrationPullRequest'), { type: 'null' }] } }, ['started', 'prompt', 'worktree', 'pullRequest']) }),
  'POST /change-requests/:id/push-fix': d('Integrations', 'Push the fix', { description: "Pushes a finished fix that waits for the person (`fixState: awaiting-push`): a decision's fix on a work item, or an orchestration's. Commits what the fixer left uncommitted and runs a plain `git push`, never forced. A failure keeps the fix waiting with the error in `error`, so the same call retries it. Answers the change request's row as the contract carries it. 409 `no-fix-to-push` when nothing waits. Refused to a chat's token with 403.", params: CHANGE_REQUEST, ok: { anyOf: [ref('WorkItemPullRequest'), ref('OrchestrationPullRequest')] } }),
  'GET /change-requests/:id/threads': d('Integrations', "Review threads of a change request", { description: "The threads of the head commit with their comments, oldest first, cached 30 s by head (`?refresh=1` reads the host now; a rate-limited read serves the last list). A thread is drawn on its new-side `line` when current and folded as outdated (with `originalLine`) when not. Comment bodies are other people's text and carry no Claudio markers. `truncated` is true when the list reached its ceiling.", params: CHANGE_REQUEST, querystring: obj({ refresh: str('`1` reads the host now') }), ok: ref('ChangeRequestThreads') }),
  'GET /change-requests/:id/review-drafts': d('Integrations', "The draft review", { description: "The notes the person left and has not posted, as rows: they survive a reload and a second tab.", params: CHANGE_REQUEST, ok: list('ReviewDraft') }),
  'GET /change-requests/:id/review-posts': d('Integrations', "The review posts of a change request", { description: "The attempts to post a review, newest first (`posting`, `posted`, `partly`, `failed`), as they were recorded, so a review that stopped partway is known after a reload. `savedOnHost` counts, for each partly posted review, the draft notes Claudio saved that are still waiting on the host (GitLab): empty when no post is partly posted, null when the host could not be read.", params: CHANGE_REQUEST, ok: ref('ChangeRequestReviewPosts') }),
  'POST /change-requests/:id/review-drafts': d('Integrations', "Add a note to the draft review", { description: "Adds a note on a line (`path`, `side`, `line`, optional `startLine`) or a general one (`path` null). `suggestion: true` makes `body` the replacement lines of a suggestion block, on the new side only. 400 for an empty note, a bad range or more than 200 notes. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('ReviewDraftInput'), ok: ref('ReviewDraft'), created: true }),
  'PUT /change-requests/:id/review-drafts/:draftId': d('Integrations', "Change a note of the draft review", { description: "Replaces the note, validated as on creation; 404 for a draft that is not there. Refused to a chat's token with 403.", params: obj({ id: str('Change request id'), draftId: str('Draft id') }), body: ref('ReviewDraftInput'), ok: ref('ReviewDraft') }),
  'DELETE /change-requests/:id/review-drafts/:draftId': d('Integrations', "Delete a note of the draft review", { description: "Removes the note from the draft review; nothing reaches the host. Refused to a chat's token with 403.", params: obj({ id: str('Change request id'), draftId: str('Draft id') }), ok: OK }),
  'POST /change-requests/:id/reviews': d('Integrations', "Post the draft review", { description: "Posts the drafts and `body` as one review. `headSha` is the head commit the person looked at: the review is posted on it (GitHub's `commit_id`) and an approval is given on it, and a head that moved is refused with `head-moved` before anything is posted; without it the head read at that moment is used. `comment` works on both hosts; `approve` is GitLab only (the comment is posted first, then the approval); `request-changes` is never offered (409 `not-offered`). The body carries a marker so a timeout is settled by looking for it. GitHub is one request, all or nothing; GitLab saves each note as a draft and publishes. 409 with a `code`: `pending-review-exists` (a review or draft of the person's own is in the way, never deleted), `line-not-in-diff`, `own-change-request`, `write-unconfirmed`, or `review-partly-posted` with a `postId` (settle it with publish-saved or discard-saved). Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('ReviewSubmitRequest'), ok: ref('ReviewPost') }),
  'POST /change-requests/:id/reviews/:postId/publish-saved': d('Integrations', "Publish the notes of a partly posted review", { description: "GitLab: publishes the draft notes a failed post left saved. `glab mr note publish` cannot pick notes (it sends every draft of the person), so it is refused with 409 `pending-review-exists` while a draft note Claudio did not save is waiting; the person's own drafts are never published. Only the rows whose note went out are dropped. 409 `not-offered` when the post is not partly posted. Refused to a chat's token with 403.", params: obj({ id: str('Change request id'), postId: str('Review post id') }), ok: ref('ReviewPost') }),
  'POST /change-requests/:id/reviews/:postId/discard-saved': d('Integrations', "Discard the notes of a partly posted review", { description: "GitLab: deletes the draft notes a failed post left saved (only the ones Claudio recorded for that post, or that carry its marker: the person's other draft notes stay). 409 `not-offered` when the post is not partly posted. Refused to a chat's token with 403.", params: obj({ id: str('Change request id'), postId: str('Review post id') }), ok: ref('ReviewPost') }),
  'POST /change-requests/:id/threads/:threadId/reply': d('Integrations', "Reply to a review thread", { description: "Adds a comment to the thread and answers the thread as the host now has it. 409 `pending-review-exists` on GitHub when a pending review of the person is in the way. Refused to a chat's token with 403.", params: obj({ id: str('Change request id'), threadId: str('The thread id: a GitHub PRRT node id or a GitLab discussion id') }), body: ref('ReviewReplyRequest'), ok: ref('ReviewThread') }),
  'POST /change-requests/:id/threads/:threadId/resolve': d('Integrations', "Resolve a review thread", { description: "Idempotent: the re-read decides. 409 `not-resolvable` when the host refuses, 404 for an unknown thread. Refused to a chat's token with 403.", params: obj({ id: str('Change request id'), threadId: str('The thread id: a GitHub PRRT node id or a GitLab discussion id') }), ok: ref('ReviewThread') }),
  'POST /change-requests/:id/threads/:threadId/unresolve': d('Integrations', "Reopen a review thread", { description: "Idempotent, as resolve. Refused to a chat's token with 403.", params: obj({ id: str('Change request id'), threadId: str('The thread id: a GitHub PRRT node id or a GitLab discussion id') }), ok: ref('ReviewThread') }),
  'GET /change-requests/:id/approval': d('Integrations', "The viewer's approval", { description: "Whether the viewer approved, how many approvals are left and who gave them. `canApprove` and `canRevoke` are true on GitLab only.", params: CHANGE_REQUEST, ok: ref('ApprovalState') }),
  'POST /change-requests/:id/approval': d('Integrations', "Approve a change request", { description: "GitLab only, on the head the person looked at (`sha`). 409 `head-moved` when the head changed since, `not-offered` on GitHub, where Claudio does not approve. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('ApprovalRequest'), ok: ref('ApprovalState') }),
  'DELETE /change-requests/:id/approval': d('Integrations', "Revoke the approval", { description: "GitLab only; revoking what was never given answers the state it wanted. 409 `not-offered` on GitHub. Refused to a chat's token with 403.", params: CHANGE_REQUEST, ok: ref('ApprovalState') }),
  'GET /change-requests/:id/reviewers': d('Integrations', "Reviewers and the review decision", { description: "The requested reviewers with their state, the host's decision in Claudio's words and the unresolved thread count.", params: CHANGE_REQUEST, ok: ref('ChangeRequestReviewers') }),
  'POST /change-requests/:id/reviewers': d('Integrations', "Request reviewers", { description: "Adds (and on GitLab removes) reviewers, never replacing the list, then answers what the host now says: an unknown login on GitHub is accepted with no effect, so check the answer. 409 `own-change-request` for the author, `not-offered` for removal on GitHub. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('ReviewersRequest'), ok: ref('ChangeRequestReviewers') }),
  'POST /change-requests/:id/address': d('Integrations', "Address review threads with an agent", { description: "Hands the chosen unresolved threads (all of them, at most 40, when `threadIds` is empty) to the fixer on the same path as the checks fix, with `fixKind: review`: the thread text goes into the prompt as untrusted data, the agent is told not to reply, resolve or push, and Claudio resolves nothing. A person's request pushes after QA; an orchestration's waits for push-fix. Answers as checks/fix does. 409 with a `code`: `not-open`, `fix-under-way`, `busy`, `not-in-review`, `not-found`, `already-resolved`, `no-threads`, `reviews-unavailable`, `no-worktree` or `fix-unavailable`. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('AddressReviewRequest'), ok: obj({ started: { type: 'boolean', description: "False when the project's flow is off and nothing moved" }, prompt: str('The prompt the fixer got, or the one to take to a chat'), worktree: { type: ['string', 'null'], description: 'Where the work is, or would be' }, pullRequest: { anyOf: [ref('WorkItemPullRequest'), ref('OrchestrationPullRequest'), { type: 'null' }] } }, ['started', 'prompt', 'worktree', 'pullRequest']) }),
  'GET /change-requests/:id/merge': d('Integrations', 'What the person may do about merging', { description: "The merge state, read from the host: `methods` the repository allows (squash, merge, rebase, in the order Claudio offers them) with `defaultMethod` preselected, the branch box's default (`deleteBranchDefault`), `canMerge`, the first `blocker` (a `code`, the host's `detail` and the one `action` the person can take) and the `others` after it, `warning` for a failing check that is not required, `autoMerge` (whether it can be armed and why not, whether it is armed, with which method, by whom and when), `waitingForPipeline` (GitLab: the head's pipeline has not attached yet, read again every 10 s), `canRebaseOnHost` (a GitLab `ff` project) and `headSha`, the full id a merge carries back as `expectedHead`. On GitHub `computing` is read again 3 times, 5 s apart, before it is shown; GitLab is not waited for and shows `computing` for 15 s after a head is first seen. `autoMergeOff` says that Claudio turned auto-merge off (`by`, `at`, `why`: `push` or `update`, and `pushing` while its push is going on) until the person arms it again. `rebaseOnHostWhy` says why Rebase on GitLab is not offered when it would apply (`uncommitted-changes`, `unpushed-commits`). A short answer is cached 60 s for the settings it needs, and `?refresh=1` reads the host now. While the rate limit is used up the last state is answered with `limitedUntil`. 404 `not-found`; 409 for a host that is signed out or refuses; 429 `rate-limited`; 502 `unreachable`, `server-error` or `timeout`.", params: CHANGE_REQUEST, querystring: obj({ refresh: str('`1` reads from the host now', { enum: ['1'] }) }), ok: ref('MergeState') }),
  'POST /change-requests/:id/merge': d('Integrations', 'Merge a change request', { description: "Merges with the `method` the person chose, on the head they looked at (`expectedHead`, the full id: a short one is read as a moved head). `deleteBranch` is the branch box, and `subject` and `body` are the commit's, for `squash` and `merge`. The click is recorded before the host is called, with the caller as the actor; after it the item moves to Done as that person. Never `--admin`, never the host's own auto-merge; on GitLab a project that requires a pipeline never merges before one has run. The re-read decides the answer, not the exit code. 409 with a `code`: `head-moved` (the head changed: nothing is merged), `busy` (another call for this change request is running), `merge-failed` (the message names the blocker or the host's own words), `write-unconfirmed` (the host did not confirm, after a re-read), or the host's own reason (`forbidden`, `auth-failed`, `cli-signed-out`…); 404 `not-found`; 429 `rate-limited`; 502 `unreachable`, `server-error` or `timeout`. 400 for a body that does not fit. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('MergeRequestBody'), ok: ref('MergeResult') }),
  'POST /change-requests/:id/auto-merge': d('Integrations', 'Arm auto-merge', { description: "Arms the host's own auto-merge, with the `method` and on the head the person looked at: GitHub through `enablePullRequestAutoMerge` with `expectedHeadOid` (never `gh pr merge --auto`, which merges at once when it can), GitLab through `glab mr merge --auto-merge --sha`. Offered only when the repository allows it and something is left to wait for: on GitHub a required check or review, on GitLab a pipeline running for the head. Answers the merge state, re-read. 409 with a `code`: `auto-merge-not-allowed`, `auto-merge-not-needed`, `waiting-for-pipeline`, `head-moved`, `busy` or the host's reason. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('AutoMergeRequestBody'), ok: ref('MergeState') }),
  'DELETE /change-requests/:id/auto-merge': d('Integrations', 'Turn auto-merge off', { description: "Turns the armed auto-merge off and answers the merge state, re-read: the host's own answer to the call is never trusted, the re-read decides. Turning off what is not armed answers the state it wanted. Claudio does the same before it pushes to the branch (a fix, an address run, an update from the base) and the person arms it again afterwards. 409 `busy` or the host's reason. Refused to a chat's token with 403.", params: CHANGE_REQUEST, ok: ref('MergeState') }),
  'POST /change-requests/:id/update-branch': d('Integrations', 'Update the branch from its base', { description: "Brings the base into the branch. On a GitLab project whose merge method is `ff` it is the host's rebase (`via: rebase`), waited for, and the item's clean checkout then follows the branch; everywhere else it is Claudio's own merge of the base into the branch in the item's checkout, pushed (a plain push, never forced), with `via: merge`. Auto-merge is turned off first, recorded as the person who clicked. A host rebase that conflicts falls back to Claudio's own merge. A merge that conflicts is aborted and pushes nothing: 409 `conflicts`, naming the paths. 409 also for `not-offered` (the row has no checkout), `busy` (also while a chat or a run works in the checkout), `merge-failed` and the host's reasons. Refused to a chat's token with 403.", params: CHANGE_REQUEST, ok: ref('UpdateBranchResult') }),
  'POST /change-requests/:id/ready': d('Integrations', 'Mark ready for review, or back to a draft', { description: "`ready: true` marks the change request ready, `false` puts it back to a draft, and the host is read again: a host that did not do it is 409 `write-unconfirmed` or its reason. Answers the merge state. Refused to a chat's token with 403.", params: CHANGE_REQUEST, body: ref('MergeReadyRequest'), ok: ref('MergeState') }),
  'GET /projects/:id/code-host': d('Integrations', 'Whether a project can open pull and merge requests', { description: 'The readiness (`ready`, or the `reason` it is not, with the host, its hostname and a `remedy`) and the parsed `origin`: its hostname, path and protocol, never the URL, which can carry a user. 404 for an id that is not an imported project.', params: obj({ id: str('Project id') }), ok: ref('ProjectCodeHost') }),
  'GET /providers': d('Providers', 'Every provider\'s status', { description: 'One status per provider in the order of the settings, from the detector\'s cache (5 minutes; a stale one is answered and re-detected in the background). `state` says whether it is ready and `reason` why not.', ok: list('ProviderStatus') }),
  'POST /providers/refresh': d('Providers', 'Detect the providers again now', { description: 'Skips the cache and runs every enabled provider\'s probes, each under its own timeout. Emits `providers.changed` when a status differs. Refused to a chat\'s token with 403.', ok: list('ProviderStatus') }),
  'GET /providers/settings': d('Providers', 'Provider settings', { description: 'The document from `providers.json`: per provider whether it is enabled and the binary to use instead of searching for one, the order the UI lists them in and the default provider. Absent until the first save, which reads as every provider on.', ok: ref('ProvidersSettings') }),
  'PUT /providers/settings': d('Providers', 'Change the provider settings', { description: 'Replaces the document, validated: known provider ids, `binaryPath` absolute or null. A provider left out keeps the defaults and one missing from `order` is appended. Providers are detected again in the background and `providers.changed` follows. Refused to a chat\'s token with 403.', body: ref('ProvidersSettings'), ok: ref('ProvidersSettings') }),
  'GET /limits/waits': d('Providers', 'Waits for a limit reset', { description: 'The history and the queue of the waits for a reset, in one list, newest first. A row with `state` `waiting` or `resuming` is an open wait.', querystring: obj({ chatId: str('The chat'), projectId: str('The project'), state: str('`waiting`, `resuming`, `resumed`, `failed` or `cancelled`'), limit: str('Max rows (default 100, max 500)') }), ok: list('ProviderMove') }),
  'POST /limits/waits/:id/cancel': d('Providers', 'Stop waiting for a reset', { description: 'Closes an open wait as `cancelled`. The flow run or task that waited then ends `stopped`; a person\'s chat just stays at its limit. `404` for an unknown wait and `409` when the wait is already over. Refused to a chat\'s token with 403.', params: obj({ id: str('Wait id') }), ok: ref('ProviderMove') }),
  'POST /limits/waits/:id/run-now': d('Providers', 'Run a waiting turn now', { description: "The other way out of a wait, beside stopping it: the wait closes `resumed` and its turn goes on at once in the same chat, on the first account the readings allow. An account with a reading taken since the wait began that says it has room comes first; otherwise the person's request passes over the accounts the turn already died on, and only an account whose reading says it is out is never chosen. A graph task or a workflow goes on as after a reset. `404` for an unknown wait; `409` with a `code`: `wait-over` (closed already, or being resumed), `not-owned` (its chat runs in another Claudio process on this data directory), `no-room` (every account reads out; the message says until when). Refused to a chat's token with 403.", params: obj({ id: str('Wait id') }), ok: ref('RunLimitWaitNowResponse') }),
  'GET /providers/:id': d('Providers', 'One provider\'s status', { description: '404 for an id no manifest declares.', params: obj({ id: str('Provider id') }), ok: ref('ProviderStatus') }),
  'GET /providers/:id/models': d('Providers', 'What a provider offers for the model picker', { description: 'The catalog of the provider\'s driver, each model with its display name and, where the provider ranks them, its tier (`fast`, `balanced`, `strong`). 404 for a provider with no driver.', params: obj({ id: str('Provider id') }), ok: list('ModelOption') }),
  'GET /accounts': d('Accounts', 'The Claude accounts', { description: 'The CLI\'s own login (`default`) first, while it has a credential (a credentials file, a key or token in its environment, or a sign-in that failed or was confirmed), then the accounts added here. Each carries its identity (email, organization and plan for a `login` account; an alias for a `token` or `api-key` one), whether it is enabled and signed in, and its last usage reading with when it was taken and where it came from (`stream`, `cli`, `cache` or `failure`), plus, once refreshed, `limits.cli`: the plan, the per-model weekly limits and the credits. The cache can be days old.', ok: list('Account') }),
  'POST /accounts': d('Accounts', 'Add a login account and start its sign-in', { description: 'Creates an empty config dir and runs `claude auth login` in it. Answers 201 with the sign-in: its `url` is what the person opens once the CLI printed it; poll `GET /accounts/logins/:id` until `state` is `succeeded`, `failed` or `cancelled`. A sign-in that ends without having signed in removes the account again. Refused to a chat\'s token with 403.', body: ref('AddLoginAccountRequest'), ok: ref('AccountLoginSession'), created: true }),
  'POST /accounts/token': d('Accounts', 'Add a token or API-key account', { description: 'A `claude setup-token` token or an API key, with the alias that names it (it has no identity of its own). The secret is write-only: it is kept in a 0600 file of the account\'s dir and is in no response, log or event. 400 for a missing alias or secret or an alias already taken. Refused to a chat\'s token with 403.', body: ref('AddTokenAccountRequest'), ok: ref('Account'), created: true }),
  'POST /accounts/:id/login': d('Accounts', 'Sign an existing login account in again', { description: 'Runs `claude auth login` in the account\'s own dir, for an account whose sign-in expired or is incomplete. Answers 201 with the sign-in, followed like the one `POST /accounts` starts; a sign-in already open for the account is answered instead of a second one. The account stays whatever the outcome, and a success clears its expired mark. 400 for a token or api-key account. Refused to a chat\'s token with 403.', params: obj({ id: str('Account id') }), ok: ref('AccountLoginSession'), created: true }),
  'POST /accounts/refresh': d('Accounts', 'Read the real usage of every enabled account', { description: 'Asks the CLI itself, with `get_usage` over its stream-json control protocol (no prompt, no turn, no tokens; never an HTTP call of ours), once per enabled account, one after the other, each with a 30 s timeout. The reading carries the account-wide windows, the weekly limits that apply to one model, the credits and the plan, and becomes the newest reading when it is newer than the stream\'s. A `login` account\'s sign-in is read again too. An account whose read fails or times out keeps its last reading and is named in `failed`. Refused to a chat\'s token with 403.', ok: ref('AccountsRefreshResult') }),
  'POST /accounts/:id/refresh': d('Accounts', 'Read the real usage of one account', { description: 'The same as `POST /accounts/refresh` for one account, which answers as `GET /accounts` lists it. 404 for an unknown account; 400 when the CLI could not read it (the message says why). Refused to a chat\'s token with 403.', params: obj({ id: str('Account id') }), ok: ref('Account') }),
  'GET /accounts/logins/:id': d('Accounts', 'One account sign-in', { description: '404 for an unknown sign-in. Refused to a chat\'s token with 403.', params: obj({ id: str('Sign-in id') }), ok: ref('AccountLoginSession') }),
  'POST /accounts/logins/:id/code': d('Accounts', 'Give the sign-in the code the page showed', { description: 'For a sign-in whose browser could not open on the machine: the person pastes the code here and it is handed to the CLI. Write-only. 409 when the sign-in is over. Refused to a chat\'s token with 403.', params: obj({ id: str('Sign-in id') }), body: ref('AccountLoginCodeRequest'), ok: ref('AccountLoginSession') }),
  'DELETE /accounts/logins/:id': d('Accounts', 'Cancel an account sign-in', { description: 'Stops the CLI. The account is removed again if it never signed in. Refused to a chat\'s token with 403.', params: obj({ id: str('Sign-in id') }), ok: ref('AccountLoginSession') }),
  'GET /accounts/settings': d('Accounts', 'Account rotation settings', { description: 'From `accounts.json`: whether work switches account at a limit, the threshold and hysteresis (0-100), the seconds an account is left alone after a rejection that gave no reset (`cooldownSeconds`, kept on that account\'s reading), the strategy (`order` or `least-used`), the `preferred` account new work starts on while it has room (null for none) and the global `order` the `order` strategy follows (empty for the listed order).', ok: ref('AccountsSettings') }),
  'PUT /accounts/settings': d('Accounts', 'Change the account rotation settings', { description: 'Merges the given fields over the stored ones, validated: threshold between 50 and 99.9, hysteresis between 0 and the threshold, `preferred` an enabled account\'s id or null, `order` every enabled account\'s id once (a disabled one may be named too; empty for the listed order). A pin wins over the preferred account, and a project policy that does not list it too. 400 for a field that breaks a rule. Refused to a chat\'s token with 403.', body: ref('AccountsSettings'), ok: ref('AccountsSettings') }),
  'GET /accounts/:id/models': d('Accounts', 'The models an account can run', { description: 'Read from the CLI\'s `initialize` handshake (no prompt, no tokens) and cached per account; the cache is refreshed when the CLI version or the account\'s plan changes, or with `refresh=true`. 404 for an unknown account.', params: obj({ id: str('Account id') }), querystring: obj({ refresh: str('`true` to read the list again') }), ok: list('ModelOption') }),
  'GET /accounts/model-fallbacks': d('Accounts', 'The accepted model fallbacks', { description: 'From `model-fallbacks.json`: each `{ from, to }` a person accepted, with its `origin` (`user` or `suggestion`) and when. Without one for a model, a chat that no account can run waits instead of changing model.', ok: list('ModelFallback') }),
  'PUT /accounts/model-fallbacks': d('Accounts', 'Replace the model fallbacks', { description: 'The whole list, validated: an empty model id, a mapping to itself, a duplicate `from`, an unknown `origin` or more than 50 entries is a 400. A pair already stored keeps its `origin` and `at`. Refused to a chat\'s token with 403.', body: ref('ModelFallbacksRequest'), ok: list('ModelFallback') }),
  'POST /accounts/model-fallbacks/suggest': d('Accounts', 'Ask for a fallback for a model', { description: 'The `account.model-fallback` point: the models the accounts with headroom offer (the same line first, then the tier below) and the one it picks. `suggestion` is null when the point is off, has no consent, is unavailable or answered none; nothing is saved either way.', body: ref('ModelFallbackSuggestRequest'), ok: ref('ModelFallbackSuggestion') }),
  'GET /accounts/policies': d('Accounts', 'Rotation policies', { description: 'Which accounts the chats of some projects may use, in what order and from what threshold. A project with no policy takes the global settings.', ok: list('RotationPolicy') }),
  'POST /accounts/policies': d('Accounts', 'Create a rotation policy', { description: 'At most one policy governs a project, and one the chats that belong to no project (`looseChats`). 400 for an unknown account in `order` or a project already governed. Refused to a chat\'s token with 403.', body: ref('RotationPolicyRequest'), ok: ref('RotationPolicy'), created: true }),
  'PUT /accounts/policies/:id': d('Accounts', 'Replace a rotation policy', { description: '404 for an unknown policy. Refused to a chat\'s token with 403.', params: obj({ id: str('Policy id') }), body: ref('RotationPolicyRequest'), ok: ref('RotationPolicy') }),
  'DELETE /accounts/policies/:id': d('Accounts', 'Delete a rotation policy', { description: '404 for an unknown policy. Refused to a chat\'s token with 403.', params: obj({ id: str('Policy id') }), ok: obj({ deleted: { type: 'boolean' } }) }),
  'GET /accounts/usage-history': d('Accounts', 'Usage readings over time', { description: 'The rows of `usage_history`, oldest first: one whenever an account\'s window percentage changed. `limit` keeps the newest rows of the range.', querystring: obj({ account: str('Account id'), window: str('`five_hour` or `seven_day`'), since: str('From this moment (ISO 8601)'), until: str('Until this moment (ISO 8601)'), limit: str('Max rows (default 5000)') }), ok: list('UsageHistoryPoint') }),
  'GET /accounts/events': d('Accounts', 'Account switches and waits', { description: 'The rows of `rotation_events`, oldest first: each time a chat moved to another account (`switch`) or found none left (`wait`), with the reason. `limit` keeps the newest rows.', querystring: obj({ limit: str('Max rows (default 200)'), since: str('Only after this moment (ISO 8601)') }), ok: list('RotationEvent') }),
  'PATCH /accounts/:id': d('Accounts', 'Rename, enable or disable an account', { description: 'A disabled account is never chosen for new work. A `token` or `api-key` account keeps an alias. 404 for an unknown account. Refused to a chat\'s token with 403.', params: obj({ id: str('Account id') }), body: ref('UpdateAccountRequest'), ok: ref('Account') }),
  'DELETE /accounts/:id': d('Accounts', 'Remove an account', { description: 'Deletes the account\'s config dir (its sign-in or secret) and takes it out of every policy, the preferred account and the order. Sessions stay: they live in the shared `projects/`. `409 account-in-use` while a live chat\'s process runs on it, with the ids of those chats in `chats` (`AccountInUseResponse`): stop them or move them to another account first. 400 for the default account, which is the CLI\'s own. Refused to a chat\'s token with 403.', params: obj({ id: str('Account id') }), ok: obj({ deleted: { type: 'boolean' } }) }),

  'GET /decisions/settings': d('Decisions', 'Decision engine settings', { description: 'The global settings from `decisions.json`: the default provider, the `cli` model, effort and cost cap, each point\'s mode, threshold and consent, and how many days the history keeps. The Jev key is never returned, only `keySet` and the last four characters as `keyHint`.', ok: ref('DecisionSettings') }),
  'PUT /decisions/settings': d('Decisions', 'Change the decision engine settings', { description: "Replaces the whole document, validated. Consent is not part of it and is kept as it was: it changes only through the consent route. Refused to a chat's token with 403.", body: ref('DecisionSettingsUpdate'), ok: ref('DecisionSettings') }),
  'PUT /decisions/credentials': d('Decisions', 'Save the Jev key', { description: "Saved with mode 0600 and never returned. The answer carries the general privacy notice. Refused to a chat's token with 403.", body: ref('DecisionCredentialsUpdate'), ok: ref('DecisionCredentialsResult') }),
  'DELETE /decisions/credentials': d('Decisions', 'Remove the Jev key', { description: "Points on `jev` then behave as if off, and warn. Refused to a chat's token with 403.", ok: ref('DecisionCredentialsResult') }),
  'POST /decisions/test': d('Decisions', 'Test a provider', { description: 'One small fixed question, with no data of yours in it: whether the provider answers, how long it took and with which model. Nothing is recorded.', body: ref('DecisionTestRequest'), ok: ref('DecisionTestResult') }),
  'GET /decisions/points': d('Decisions', 'The decision points', { description: "The catalogue with the settings in force: a project's override (`?projectId=`), then the global one, then the point's default.", querystring: obj({ projectId: str('Project id; omit for the global scope') }), ok: list('DecisionPointInfo') }),
  'GET /decisions/points/:point/preview': d('Decisions', 'Preview what a point sends', { description: "The exact state of the point's latest request (`source: last`), or, when it never asked, the fields it may carry (`source: built`), built locally and not sent. It is what the consent is given to.", params: obj({ point: str('Decision point id, e.g. `flow.bounce`') }, ['point']), querystring: obj({ projectId: str('Project id, for the provider in force there') }), ok: ref('DecisionPreview') }),
  'PUT /decisions/points/:point/consent': d('Decisions', 'Grant or withdraw consent for a point', { description: "Bound to the state version that was previewed and to the providers it covers: a point on `jev` needs consent naming `jev`. 409 when the state changed since the preview. Refused to a chat's token with 403.", params: obj({ point: str('Decision point id') }, ['point']), body: ref('DecisionConsentRequest'), ok: ref('DecisionSettings') }),
  'GET /decisions': d('Decisions', 'Decision history', { description: 'Newest first, filtered and paged by `nextCursor`.', querystring: obj({ point: str('Decision point id'), projectId: str(), subjectKind: str('What it was about, e.g. `work_item` or `change_request`'), subjectId: str('Id of the subject'), visible: str('`true` for only the rows that changed something a person sees'), provider: str('`cli` or `jev`'), mode: str('`shadow` or `active`'), status: str('`answered` or `unavailable`'), since: str('ISO timestamp, inclusive'), until: str('ISO timestamp, inclusive'), cursor: str("The previous page's `nextCursor`"), limit: str('Rows on the page: a whole number from 1; default 50') }), ok: ref('DecisionPage') }),
  'DELETE /decisions': d('Decisions', 'Clear decision history', { description: 'Deletes the rows matching the filter of `GET /decisions`; with none, every row.', querystring: obj({ point: str(), projectId: str(), provider: str(), mode: str(), status: str(), since: str(), until: str() }), ok: ref('DecisionClearResult') }),
  'GET /decisions/stats': d('Decisions', 'Decision metrics', { description: 'Per point over a window: count, acted, mean confidence, resolved and agreed, useful and not useful, unavailable, cost, and Claude runs saved; plus the totals for Jev cost and runs saved. Points with no row in the window are absent.', querystring: obj({ days: str('Window in days; default 30'), since: str('ISO start of the window; wins over `days`') }), ok: ref('DecisionStats') }),
  'POST /decisions/palette': d('Decisions', 'Route a palette query to a command', { description: 'The `palette.intent` point: the query and the ids and titles of the commands, answered with the command the query most likely means. `commandId` is null when the point is off, has no consent, is unavailable or is unsure, and the palette then keeps its own search.', body: ref('DecisionPaletteRequest'), ok: ref('DecisionPaletteResult') }),
  'GET /decisions/:id': d('Decisions', 'One decision', { description: 'The state sent, the questions, the answers with their probabilities, the provider, and the outcome once known.', ok: ref('DecisionRecord') }),
  'POST /decisions/:id/feedback': d('Decisions', 'Rate a decision', { description: "`useful` or `not_useful`. The person's word overrides the inferred agreement.", body: ref('DecisionFeedbackRequest'), ok: ref('DecisionRecord') }),
  'POST /decisions/:id/palette-action': d('Decisions', 'Report what the palette did with a proposal', { description: "`commandId` is the command that ran, or null when the palette closed without one. The row classifies it against its `command` answer as `proposed`, `other` or `dismissed`, and the first report wins. 404 for an unknown id; 400 for a row that is not `palette.intent` or a `commandId` that is neither a string nor null. Refused to a chat's token with 403.", body: ref('DecisionPaletteActionRequest'), ok: ref('DecisionRecord') }),
  'POST /decisions/notification-opened': d('Decisions', 'Report that a notification opened the app', { description: "Sets `openedAt`, if unset, on the newest `notification.urgency` row for the push `key`. `decisionId` is null when no row matches, which is not an error. Refused to a chat's token with 403.", body: ref('DecisionNotificationOpenedRequest'), ok: ref('DecisionNotificationOpenedResult') }),
  'DELETE /decisions/:id': d('Decisions', 'Delete a decision', { ok: OK }),

  'POST /chats/:id/supervisor/:proposalId/send': d('Chats', "Send the supervisor's proposal", { description: "Delivers the proposed hint through the hint route (the task's, for a worker of an orchestration) and marks it `sent`. 409 when it was already sent or dismissed, or the chat has no live process to take it. The proposal is on the chat's `health.proposal` and in the `supervisor.proposed` event.", params: obj({ id: str(), proposalId: str() }), ok: ref('SupervisorProposal') }),
  'POST /chats/:id/supervisor/:proposalId/dismiss': d('Chats', "Dismiss the supervisor's proposal", { description: 'Marks it `dismissed`; nothing reaches the worker. 409 when it was already sent or dismissed.', params: obj({ id: str(), proposalId: str() }), ok: ref('SupervisorProposal') }),
  'GET /chats/:id/context': d('Chats', "What fills a chat's context window", { description: "The breakdown the CLI gives for the live process (`get_context_usage`): categories, MCP servers by weight, memory files, agents and the warnings Claudio draws from them. `detail=summary` (default) answers from the last response and local estimates; `full` counts each category and is only honoured while the chat is idle. `snapshot` is always the transcript's figure. A chat with no process of ours is `live: false`, and a CLI that cannot or will not answer is `unreported`: both are a 200, never an error. 404 for an unknown chat, 400 for a `detail` that is neither.", params: obj({ id: str() }), querystring: obj({ detail: str('`summary` (default) or `full`', { enum: ['summary', 'full'] }) }), ok: ref('ChatContextUsage') }),
  'POST /chats/:id/compact': d('Chats', 'Compact a chat now', { description: "Sends `/compact` to the chat as a user turn: a paid model call over about the whole context. `focus` (at most 500 characters) tells it what to keep; `structuredNote` (default true) asks for the summary in the session-note shape. Answers 202 with the compaction row, which then goes `requested`, `running` and `done`, `failed` or `cancelled`; follow it on `GET /chats/{id}/compactions`. 404 for an unknown chat; 400 for a `focus` that is not a string or too long, or a `structuredNote` that is not a boolean; 409 with a `code` (`busy`, `waiting`, `open`, `read-only`, `housekeeping`, `at-limit`, `run`, `unsupported`, `no-history`) when it cannot start now. Not open to a chat's token.", params: obj({ id: str() }), body: ref('CompactChatRequest'), ok: ref('ChatCompaction') }),
  'GET /chats/:id/compactions': d('Chats', "A chat's compactions", { description: "Every compaction Claudio asked for or saw (the CLI's own included), newest first, at most 50. 404 for an unknown chat.", params: obj({ id: str() }), ok: list('ChatCompaction') }),
  'GET /chats/:id/notes': d('Chats', "A chat's session notes", { description: 'The notes kept for the chat, newest first, at most 50: from a structured compaction, asked of the agent, or a summary a person saved. 404 for an unknown chat.', params: obj({ id: str() }), ok: list('ChatSessionNote') }),
  'POST /chats/:id/notes': d('Chats', 'Add a session note', { description: "`{ from: 'agent' }` asks the chat for a note in a paid housekeeping turn and answers 202 with the note pending. `{ from: 'summary', entryUuid }` keeps a compaction summary of the transcript and answers 201 with the note ready. 404 for an unknown chat; 400 for a bad body or an `entryUuid` that is not a summary of this chat; 409 with a `code`: a compaction refusal for `agent`, or `saved` when that summary already is a note. Not open to a chat's token.", params: obj({ id: str() }), body: ref('CreateChatNoteRequest'), ok: ref('ChatSessionNote') }),
  'DELETE /chats/:id/notes/:noteId': d('Chats', 'Delete a session note', { description: "`204`. 404 for an unknown chat or note, with the same body for a note of another chat. Not open to a chat's token.", params: obj({ id: str(), noteId: str('Note id') }) }),
  'GET /chats/:id/mcp': d('Chats', "The MCP servers of a live chat", { description: "As the chat's process reports them now (the CLI's `mcp_status`): every server it loaded, claude.ai connectors included (scope `claudeai`), each with its status (`connected`, `pending`, `needs-auth`, `failed`, `disabled`) and the tools it offers once connected. The servers' own config is left out. `live: false` with no servers when no process of ours runs the chat.", ok: ref('ChatMcpServers') }),
  'PUT /chats/:id/mcp/:name': d('Chats', 'Switch an MCP server of a live chat on or off', { description: "Sent to the running process (the CLI's `mcp_toggle`), and answered with the servers as they are after it. The CLI keeps the choice for the chat's folder (`disabledMcpServers`), as `/mcp` does in a terminal, so later chats there start with it too. 400 when the chat has no live process: choose its servers when it is resumed or forked.", params: obj({ id: str(), name: str('The server name, as listed') }), body: ref('ChatMcpToggle'), ok: ref('ChatMcpServers') }),
  'PUT /chats/:id/claudio-mcp': d('Chats', "Switch Claudio's own MCP server on or off in a live chat", { description: "Hands the running process Claudio's `claudio` server with all its tools (the CLI's `mcp_set_servers`), or takes it away, and stores the choice on the chat (`tools.claudioMcp`): a resume, a fork and Claudio's own respawns start with it in their `--mcp-config`. Its tools obey the chat's permission mode. Answered with the servers as they are after it; a server the CLI refused is in `claudio.error`. 400 when the chat has no live process, is the assistant's or does not run on Claude Code; 409 when a server of the person's is already named `claudio`; 503 when the server cannot be built (the API's address is unknown).", params: obj({ id: str() }), body: ref('ChatClaudioMcpToggle'), ok: ref('ChatMcpServers') }),
  'PATCH /chats/:id': d('Chats', 'Change the permission mode or the model', { description: 'A live process switches at once; a chat whose process has exited gets the new settings when the next execution starts. The effort is not one of them: it cannot change on a live chat, and a new one is given when the chat is resumed or forked (400 if it is sent here).', body: ref('ChatSettingsUpdate'), ok: ref('ChatSummary') }),
  'DELETE /chats/:id': d('Chats', 'Delete a chat', { description: 'Its transcript, its sidecar files and Claudio\'s record of it. Refused with 409 while something is running on it.', ok: OK }),
  'GET /chats/:id/logs': d('Chats', "A background session's recent terminal output", { description: 'From `claude logs`: the process output, which the transcripts do not contain.', ok: obj({ logs: str('Raw terminal output') }) }),
  'GET /chats/:id/permissions': d('Chats', 'Prompts waiting for a person', { description: 'Tool calls to approve, questions (`AskUserQuestion`) and plans (`ExitPlanMode`). Populated only when the chat was started with `permissionPrompts: "host"`. A notice on the chat\'s event stream announces each one.', ok: list('PermissionRequest') }),
  'POST /chats/:id/permissions/:requestId': d('Chats', 'Answer a prompt', { description: 'Allow, optionally with edited arguments and with the request\'s `suggestions` to remember them, or deny with a message the model can read and adapt to. A question is answered by allowing it with `updatedInput.answers` mapping each question to the chosen label(s). A request nobody answers is denied after ten minutes.', body: ref('PermissionDecision'), ok: ref('PermissionRequest') }),
  'GET /chats/:id/subagents': d('Chats', 'Subagents of a chat', { description: 'A branch of the chat: its messages live inside the chat\'s transcript. Read from what the CLI writes beside the transcript, so it covers chats started from a terminal as well as Claudio\'s. An agent is running until it stops, and again whenever it writes after stopping — the CLI can resume one.', ok: list('ChatSubagentEntry') }),
  'GET /chats/:id/subagents/:agentId': d('Chats', 'One subagent: prompt, outcome and full transcript', { description: 'Carries the prompt, type, status, duration, token usage, the final result, the conversation normalised like the chat\'s, and the background tasks the subagent launched. `after` skips the first N entries, so a live view can append: pass back the `total` of the previous response. `agentId` is the `id` of the subagent in the chat.', querystring: obj({ after: str('Entries already held: only those from this index on are returned') }), ok: ref('AgentTranscript') }),
  'GET /chats/:id/tasks': d('Chats', 'Commands a chat sent to the background', { description: 'The command, who sent it to the background, and how it ended. One still marked running when nothing is left to run it is reported as `stopped`. Those a subagent launched are listed too, with its id as `ownerId`.', ok: list('ChatBackgroundTaskEntry') }),
  'GET /chats/:id/tasks/:taskId/output': d('Chats', 'What a background command printed', { description: 'Read from the CLI\'s temp dir, which a reboot clears. Without `offset`, the last 64 KiB of the file. With it, up to 64 KiB of what was written after that byte, so a running task can be followed by passing back the `offset` of the previous response; `offset` less than `bytes` means more is waiting. An `offset` past the end of the file (it was replaced) restarts from the tail with `reset: true`.', querystring: obj({ offset: str('Byte position to resume from: the `offset` of the previous response') }), ok: ref('BackgroundTaskOutput') }),
  'GET /chats/:id/workflows': d('Chats', 'Workflow runs of a chat', { description: 'Runs of the Workflow tool: a script that orchestrates subagents inside the chat, with its phases and the progress of every agent it launched.', ok: list('ChatWorkflowEntry') }),
  'GET /chats/:id/workflows/:workflowId/agents/:agentId': d('Chats', 'One workflow agent: prompt, outcome and full transcript', { description: 'The same as a subagent\'s, for an agent a workflow launched: `workflowId` is the workflow\'s and `agentId` comes from its `agents`. Status and timing come from the workflow\'s record or journal.', querystring: obj({ after: str('Entries already held: only those from this index on are returned') }), ok: ref('AgentTranscript') }),
  'GET /environments': d('Chats', 'What Claude actually loaded, per directory', { description: 'Tools, MCP server status, agents, skills, plugins, slash commands and memory paths, captured from the `init` event of the latest chat started in each directory.', querystring: obj({ cwd: str('Absolute directory to filter by') }), ok: list('EffectiveEnvironment') }),
  'GET /tasks': d('Chats', 'Background commands across every chat', { description: 'Commands sent to the background, monitors and remote agents, each with the chat that sent it: the inbox sees a hung command wherever it is. A chat with a process reports from its stream; the others (terminal chats live or ended in the last day, ended chats of Claudio) are read from their files, so the list survives a restart. The CLI reports long foreground commands as tasks too; those are left out, and so are subagents (`/subagents`) and workflows (`/workflows`).', ok: list('ChatBackgroundTaskEntry') }),
  'GET /subagents': d('Chats', 'Subagents across every chat', { description: 'Agents spawned with the Agent tool, in the foreground or the background, each with the chat it belongs to. Agents a workflow launched are listed with their workflow.', ok: list('ChatSubagentEntry') }),
  'GET /workflows': d('Chats', 'Workflow runs across every chat', { description: 'Runs of the Workflow tool, each with the chat it runs in, with its phases and the progress of every agent it launched.', ok: list('ChatWorkflowEntry') }),
  'GET /workflows/saved': d('Chats', 'Saved workflows', { description: 'Scripts in the project\'s `.claude/workflows/` (for `cwd`) and the user\'s, which the Workflow tool runs by name. A project workflow shadows a user one of the same name.', querystring: obj({ cwd: str('Project directory') }), ok: list('WorkflowDefinition') }),
  'POST /workflows/saved/run': d('Chats', 'Run a saved workflow', { description: 'Starts a chat that asks Claude to run the workflow with the Workflow tool: the CLI has no command of its own for it. Prompts go to the panel.', body: ref('RunWorkflowRequest'), ok: ref('ChatSummary'), created: true }),

  // ---- Orchestration
  'GET /orchestrations': d('Orchestration', 'List orchestrations', { description: 'Each graph as a summary: every task\'s `prompt` and `result`, the synthesis (`finalResult`, with `hasFinalResult` saying whether there is one) and what each check printed are left out. `GET /orchestrations/{id}` has them whole.', ok: list('OrchestrationSummary') }),
  'POST /orchestrations': d('Orchestration', 'Launch an orchestration', { description: 'Independent tasks run in parallel up to `concurrency`; results of dependencies are passed to dependent tasks; `synthesize` adds a final report worker. Task ids must be unique and the graph acyclic. `limits` (on the graph, as the default, and on each task) cap what a worker may spend: `maxCostUsd` is passed to the CLI as `--max-budget-usd`, and `maxMinutes` is enforced by Claudio, which tells the worker to wrap up at 80% and stops the task at the limit, failing it with the reason. A task that names a `workItemId` (as a draft from `POST /projects/:id/work-items/orchestrate` does) is linked to that item, which then follows it: `in_progress` when it starts running, `in_review` when it completes; the item must be of a project whose Board module is on and in which the task runs (its `cwd`, or else that of the graph), and only one task may name it. As `POST /work-items/{itemId}/work`, an epic is refused with 400, and an item in `done` or one a chat or a node is working on now with 409.', body: ref('OrchestrationSpec'), ok: ref('Orchestration'), created: true }),
  'POST /orchestrations/plan': d('Orchestration', 'Draft a task graph from an objective', { description: 'Runs a planner agent with structured output; can take a couple of minutes. The draft is not launched.', body: ref('PlanRequest'), ok: ref('OrchestrationSpec') }),
  'POST /orchestrations/plan/start': d('Orchestration', 'Start the planner without waiting', { description: 'Returns the planner chat immediately; stream it at `/chats/:id/stream` and fetch the draft from `/orchestrations/plans/:runId` (the id of the planner chat) when it finishes. Preferred over `POST /orchestrations/plan`, which holds the request open for the whole run.', body: ref('PlanRequest'), ok: ref('ChatSummary'), created: true }),
  'GET /orchestrations/plans': d('Orchestration', 'Plans generated but not yet launched', { description: 'Recorded when a planner run finishes, so a draft survives a lost response or a reload.', querystring: obj({ limit: str('Max drafts to return (default 20, max 100)') }), ok: list('PlanDraftSummary') }),
  'GET /orchestrations/plans/:runId': d('Orchestration', 'The draft a planner run produced', { ok: ref('OrchestrationSpec') }),
  'GET /orchestrations/:id': d('Orchestration', 'State of every task, results and cost', { description: 'A task that is running carries its `health`, worked out when it is read: the same signals as a chat\'s, with the call to cancel and a suggested hint on each. The list carries it too.', ok: ref('Orchestration') }),
  'GET /orchestrations/:id/timings': d('Orchestration', 'Where the time went', { description: "Computed when it is read from the graph and the executions of the chats Claudio started for it (tasks, integrator, fixer, synthesis); nothing is stored for it. The phases in order, the time after the last task, the effective parallelism, the critical path (from the task that ended last, back through the dependency that ended last) with the waits before and inside each link, the time tasks waited for a slot, on a limit or for a retry, and every run of every verification check with the fixer's attempts. What is still running counts up to `at`. A graph stored before these were recorded answers with what it has and names the rest in `missing`.", ok: ref('OrchestrationTimings') }),
  'POST /orchestrations/:id/resume': d('Orchestration', 'Resume a stopped orchestration', { description: 'Runs again every task that did not complete and keeps the results of those that did; a task that already has a chat continues it, in a new execution. The body can correct the settings that stopped it — worktrees, where permission prompts go, allowed tools, permission mode — so a graph started with the wrong ones is picked up instead of rebuilt.', body: ref('ResumeOrchestrationRequest'), ok: ref('Orchestration') }),
  'POST /orchestrations/:id/tasks/:taskId/retry': d('Orchestration', 'Run a failed task again in its own chat', { description: 'Only a task that failed for good (its attempts ran out, or it failed in a way that is never retried automatically). A new execution of the same chat, in the worktree it left, told what went wrong; the tasks blocked behind it go back to waiting for their turn. One more execution, however many attempts the graph allows: if it fails again the task is left for a decision again.', ok: ref('Orchestration') }),
  'POST /orchestrations/:id/tasks/:taskId/retry-clean': d('Orchestration', 'Start a failed task over', { description: 'A new chat, in a worktree rebuilt from the base commit: the failed chat stays listed as what was tried, and its worktree and branch are removed, uncommitted work included.', ok: ref('Orchestration') }),
  'POST /orchestrations/:id/tasks/:taskId/rerun': d('Orchestration', 'Run a task of a finished graph again', { description: 'For a graph that completed, failed or was stopped: the task and every task that depends on it start over, each in a new chat and a worktree rebuilt from what it now depends on, and the graph integrates and synthesises again. The integration branch is rebuilt from the base. Tasks that do not depend on it keep their work. Refused while the graph runs or waits for a decision (use retry or skip there), for a workflow, while any affected task has a process, and once the integration branch was pushed for a pull request.', ok: ref('Orchestration') }),
  'POST /orchestrations/:id/relaunch': d('Orchestration', 'Relaunch a graph with corrections as a new orchestration', { description: 'Starts from what the graph ran with. `spec` overrides its settings (name, objective, model, concurrency, worktrees…), and `tasks` replaces the whole task list: merging two graphs by task id is not attempted. The new orchestration records the original in `relaunchedFrom`; the original is left as it was. Each node keeps its `workItemId`, and the nodes are checked as `POST /orchestrations` checks them. Refused while the original runs.', body: ref('RelaunchOrchestrationRequest'), ok: ref('Orchestration'), created: true }),
  'GET /orchestrations/templates': d('Orchestration', 'List orchestration templates', { description: 'Saved graphs, by name. Stored as a JSON file in the data directory.', ok: list('OrchestrationTemplate') }),
  'POST /orchestrations/templates': d('Orchestration', 'Save a graph as a template', { description: 'Give the graph as `spec` (a draft plan, say) or as `fromOrchestration`, the id of an orchestration to take it from. The task graph is validated as for a launch; names are unique.', body: ref('SaveOrchestrationTemplateRequest'), ok: ref('OrchestrationTemplate'), created: true }),
  'GET /orchestrations/templates/:templateId': d('Orchestration', 'One orchestration template', { ok: ref('OrchestrationTemplate') }),
  'PATCH /orchestrations/templates/:templateId': d('Orchestration', 'Edit an orchestration template', { description: 'Rename it, change its description or replace its spec.', body: ref('UpdateOrchestrationTemplateRequest'), ok: ref('OrchestrationTemplate') }),
  'DELETE /orchestrations/templates/:templateId': d('Orchestration', 'Delete an orchestration template', { description: 'Orchestrations launched from it are not affected.', ok: OK }),
  'POST /orchestrations/templates/:templateId/launch': d('Orchestration', 'Launch an orchestration template', { description: "Launches the template's graph with a new `objective`, `cwd`, `name` or `model`; what is given applies to this run only, and the template is not changed. The orchestration records the template in `templateId`.", body: ref('LaunchOrchestrationTemplateRequest'), ok: ref('Orchestration'), created: true }),
  'POST /orchestrations/:id/tasks/:taskId/skip': d('Orchestration', 'Give a branch up', { description: 'Skips a failed or blocked task and every task that depends on it, so the graph can finish without them. Nothing is deleted. A graph waiting on nothing else then integrates and synthesises.', ok: ref('Orchestration') }),
  'POST /orchestrations/:id/tasks/:taskId/hint': d('Orchestration', 'Send a hint to a running worker', { description: 'A nudge for a worker whose task is still running, delivered as a message to its chat. Refused for a task that finished: its result already fed the tasks that depend on it, and its way forward is a fork of its chat.', body: ref('TaskHintRequest'), ok: ref('Orchestration') }),
  'POST /orchestrations/:id/tasks/:taskId/supervisor/:proposalId/send': d('Orchestration', "Send the supervisor's proposal to a worker", { description: "The same as the chat route, from the board: the hint goes through the task hint route, so a task that is no longer running refuses it. What the supervisor cost is already on the graph's `costUsd`.", params: obj({ id: str(), taskId: str(), proposalId: str() }), ok: ref('SupervisorProposal') }),
  'POST /orchestrations/:id/tasks/:taskId/supervisor/:proposalId/dismiss': d('Orchestration', "Dismiss the supervisor's proposal for a worker", { description: 'Marks it `dismissed`; nothing reaches the worker.', params: obj({ id: str(), taskId: str(), proposalId: str() }), ok: ref('SupervisorProposal') }),
  'GET /orchestrations/:id/tasks/:taskId/changes': d('Orchestration', 'What a task changed on disk', {
    description: `The task's branch, the commit it started from (its dependencies' work is not counted as its own), the commits and the files it changed since, what it has not committed yet, and \`working\`: every file that differs from that commit in the working tree. Refused for a graph without worktrees. A task that has not started has an empty summary. Announced by a \`changes.updated\` event while the worker runs. ${SCOPE_NOTE}`,
    querystring: SCOPE_QUERY,
    ok: ref('ChangeSummary'),
  }),
  'GET /orchestrations/:id/tasks/:taskId/changes/diff': d('Orchestration', 'The diff of one file of a task', {
    description: `Everything the task did to the file since it started, committed or not. A file created and not yet added shows as all new. ${DIFF_NOTE}`,
    querystring: DIFF_QUERY,
    ok: ref('FileDiff'),
  }),
  'GET /orchestrations/:id/tasks/:taskId/changes/steps': d('Orchestration', 'Every edit a task made, step by step', {
    description: `Read through the task's chat. ${STEPS_NOTE} A task that has not started has none.`,
    ok: list('EditStep'),
  }),
  'GET /orchestrations/:id/tasks/:taskId/checklist': d('Orchestration', "A task's own checklist", {
    description: "The plan the worker kept with its `TaskCreate`/`TaskUpdate` or `TodoWrite` calls, read from its chat's transcript, as of its last update. Empty for a worker that never planned or one that has not started.",
    ok: ref('Checklist'),
  }),
  'GET /orchestrations/:id/integration/changes': d('Orchestration', 'What the integration branch changed', {
    description: `The same summary for the branch that merges every task's work, against the graph's base commit. Empty until the graph starts integrating. ${SCOPE_NOTE}`,
    querystring: SCOPE_QUERY,
    ok: ref('ChangeSummary'),
  }),
  'GET /orchestrations/:id/integration/changes/diff': d('Orchestration', 'The diff of one file of the integration branch', {
    description: DIFF_NOTE,
    querystring: DIFF_QUERY,
    ok: ref('FileDiff'),
  }),
  'DELETE /orchestrations/:id': d('Orchestration', 'Delete an orchestration', { description: 'Refused while it runs. Removes its worktrees and keeps their branches; refused if one holds uncommitted work, so a deletion never takes it.', ok: OK }),
  'POST /orchestrations/:id/integrate': d('Orchestration', 'Integrate the task branches again', { description: "Merges every completed task's branch into the graph's integration branch (`claudio/<name>-<id>`), handing conflicts to an integrator agent. Runs by itself when a worktree graph finishes; this retries it after resolving by hand, or integrates a graph that finished before orchestrations did so. Returns at once; follow `integration.status`.", ok: ref('Orchestration') }),
  'GET /orchestrations/:id/workflow': d('Orchestration', 'The graph as a workflow script', { description: 'The script a graph with `engine: "workflow"` runs: generated from its tasks, dependencies, concurrency and synthesis. For a graph that never ran as a workflow it is generated on the spot.', ok: obj({ path: str('Where the wrapper keeps it'), script: str() }) }),
  'POST /orchestrations/:id/workflow/save': d('Orchestration', 'Save the graph as a project workflow', { description: "Copies the script into the project's `.claude/workflows/`, where the Workflow tool (and `GET /workflows/saved`) can run it by name. Refuses to replace an existing one unless `overwrite`.", body: ref('SaveOrchestrationWorkflowRequest'), ok: ref('WorkflowDefinition'), created: true }),
  'GET /orchestrations/:id/review': d('Orchestration', 'The review gate of a graph', { description: "The gate's summary (`state`, as on `verification.review`), every round, and one page of the findings of a round: the latest unless `round` names another. `blocking=1` keeps only the findings that block; `limit` is 1 to 500 (default 100) and `offset` starts at 0; a value out of bounds is a 400. 404 when the orchestration is unknown or its graph has no review gate. Open to a chat's token.", params: obj({ id: str('Orchestration id') }), querystring: obj({ round: str('Round number; the latest when omitted'), blocking: str('`1` keeps the blocking findings only'), limit: str('Page size, 1 to 500, default 100'), offset: str('Findings to skip, default 0') }), ok: ref('ReviewGateDetail') }),
  'POST /orchestrations/:id/review/retry': d('Orchestration', 'Run the review gate again', { description: "Starts a new review round on the integration branch, without running the checks again, and answers at once; follow `verification.review`. Allowed only when the checks passed on the current head and no review runs. 404 for an unknown orchestration; 409 with a `code`: `review-running`, `checks-not-passed`, `head-moved`, or `review-not-acceptable` when the graph has no review gate. Open to a chat's token: it only re-runs Claudio's own gate.", params: obj({ id: str('Orchestration id') }), ok: ref('Orchestration') }),
  'POST /orchestrations/:id/review/accept': d('Orchestration', 'Accept a blocked or incomplete review gate', { description: "A person's decision, with a written reason, bound to the head commit the gate stopped on: any new commit voids it. An `incomplete` gate is accepted only after a retry also ended `incomplete`. 404 for an unknown orchestration; 400 `bad-reason` for a reason that is too short or too long; 409 `review-not-acceptable` when the gate is neither blocked nor incomplete, or `review-running`. Refused to a chat's token with 403.", params: obj({ id: str('Orchestration id') }), body: ref('AcceptReviewRequest'), ok: ref('Orchestration') }),
  'POST /orchestrations/:id/verify': d('Orchestration', 'Run the graph\'s checks on the integration branch', { description: 'Runs `verification.commands` in order on the merged branch, each under its time limit (an entry that is a list is a parallel group: its commands run at the same time, each row carries the entry\'s index as `group`, and the next entry starts when all of them have ended), and records the outcome on `verification`: `passed`, `fixed` (with the fixer\'s commits) or `failed` (with a report). With a fixer, a failing command goes to an agent whose rules come from Claudio, told the spec files its output reports as failed (`✗ <file>` lines), up to `maxAttempts` times; one attempt covers every failed command of a group and counts against each, and every command runs again from the first after a fix. It runs by itself when a worktree graph finishes; this runs it by hand, or again after the branch changed. Give `verification` to check a graph launched without any. Returns at once; follow `verification.status`. Before the commands comes an install step, as its own row with `install: true`: `verification.install` when it is a command, none when it is `null`, and otherwise the one the lockfile of the worktree asks for (`pnpm-lock.yaml`: `pnpm install --frozen-lockfile`, `package-lock.json`: `npm ci`, `yarn.lock`: `yarn install --frozen-lockfile`). `maxCostUsd` caps what the fixer spends over its attempts, passed to the CLI as `--max-budget-usd` with what is left; once spent the outcome is `failed`, and `verification.costUsd` says what it cost. With `failGraph`, failed checks leave the orchestration `failed` with `error` set, and passing them again brings it back to `completed`. Refused while the graph runs or waits, without a merged integration branch, and while the checks already run. Stopping the orchestration stops them.', body: ref('VerifyOrchestrationRequest'), ok: ref('Orchestration') }),
  'POST /orchestrations/:id/pull-request': d('Orchestration', 'Push the integration branch and open a pull request', { description: "Pushes the integrated branch to `origin` and opens a pull request (GitHub) or merge request (GitLab) with the project's host CLI, using the objective and final report as its body. The project's readiness is checked first: a project that cannot open one is refused with 409 and its `reason` (`not-git`, `no-remote`, `unsupported-host`, `no-default-branch`, `cli-missing`, `cli-incompatible`, `cli-signed-out`), and nothing is pushed; so is a branch with no commit ahead of the default branch (`nothing-to-propose`). A second call while one is being opened or is open is answered with the one already there. When the host fails after the push, the branch stays pushed and `detail` says why no request was opened. The row it opens, `pullRequest` (host, `ref`, number, URL, phase, CI), is watched until it is merged or closed and announced with `orchestration.pull-request`. Refused while the checks run, and when they failed on a graph launched with `verification.failGraph`.", ok: ref('OrchestrationPullRequestAnswer') }),
  'POST /orchestrations/:id/worktrees/prune': d('Orchestration', "Remove the graph's worktrees", { description: 'Branches are always kept, so committed work survives. A worktree with uncommitted changes is left alone and reported unless `force` is set.', body: obj({ force: str('Remove even with uncommitted changes') }), ok: obj({ results: str('One entry per task: removed, and why not when it was kept') }) }),
  'POST /orchestrations/:id/spend-pass': d('Orchestration', "Let a graph run past today's spend cap", { description: "Sets the graph's pass to today (`spendPass`, the server's local day) so its tasks start although the daily cap was reached; tomorrow it is under that day's cap. Answers the orchestration. Refused to a chat's token with `403`.", ok: ref('Orchestration') }),
  'POST /orchestrations/:id/stop': d('Orchestration', 'Stop all workers', { ok: ref('Orchestration') }),

  // ---- Configuration
  'GET /config/settings': d('Configuration', 'Read settings.json', { querystring: scopeQuery({ variant: VARIANT }), ok: ref('SettingsDoc') }),
  'PUT /config/settings': d('Configuration', 'Replace settings.json', { querystring: scopeQuery({ variant: VARIANT }), body: obj({ settings: { type: 'object', additionalProperties: true } }, ['settings']), ok: ref('SettingsDoc') }),
  'GET /config/instructions': d('Configuration', 'Read CLAUDE.md', { querystring: scopeQuery({ variant: VARIANT }), ok: ref('InstructionsDoc') }),
  'PUT /config/instructions': d('Configuration', 'Replace CLAUDE.md', { querystring: scopeQuery({ variant: VARIANT }), body: obj({ content: str() }, ['content']), ok: ref('InstructionsDoc') }),
  'GET /config/mcp': d('Configuration', 'MCP servers, tagged by scope', { description: 'User scope returns user servers. Project scope returns `local`, `project` (.mcp.json) and the inherited `user` servers.', querystring: scopeQuery(), ok: list('McpServerEntry') }),
  'GET /config/mcp/health': d('Configuration', 'Real MCP connection checks', { description: 'Runs `claude mcp list`; takes several seconds. Call on demand.', querystring: scopeQuery(), ok: list('McpServerHealth') }),
  'PUT /config/mcp/:name': d('Configuration', 'Create or replace an MCP server', { description: 'Written through `claude mcp add-json`. `config` is e.g. `{"type":"http","url":"…"}` or `{"command":"npx","args":["-y","pkg"],"env":{}}`.', querystring: scopeQuery(), body: obj({ config: { type: 'object', additionalProperties: true }, scope: ref('McpScope') }, ['config']), ok: ref('McpServerEntry') }),
  'DELETE /config/mcp/:name': d('Configuration', 'Remove an MCP server', { querystring: scopeQuery({ scope: ref('McpScope') }), ok: OK }),
  'GET /config/tool-presets': d('Configuration', 'Tool presets', { description: 'Named sets of `--allowedTools` / `--disallowedTools`, picked with `toolPreset` when a chat is created, resumed or forked. A fresh install lists the shipped ones (`builtIn`); they are edited like any other. `defaultPresetId` is the preset a new chat takes when it names neither `toolPreset` nor `allowedTools`.', ok: ref('ToolPresetsOverview') }),
  'PUT /config/tool-presets/default': d('Configuration', 'Set the default tool preset', { description: 'The preset a new chat takes when its request names neither `toolPreset` nor `allowedTools`; `null` leaves such a chat with the CLI\'s own tools. A request with `toolPreset: null` opts out. Resumes and forks keep the tools their chat already has. Deleting the preset clears the default. `default` is therefore not a valid preset id.', body: ref('ToolPresetsConfig'), ok: ref('ToolPresetsConfig') }),
  'POST /config/tool-presets/restore': d('Configuration', 'Restore the shipped tool presets', { description: 'Rewrites `read-only`, `no-network` and `everything` as they ship, whether they were edited or deleted. Every other preset, and the default, are left alone.', ok: ref('ToolPresetsOverview') }),
  'PUT /config/tool-presets/:id': d('Configuration', 'Create or replace a tool preset', { params: obj({ id: str('Lowercase letters, digits and `-`') }), body: obj({ name: str(), description: str(), allowedTools: { type: 'array', items: str() }, disallowedTools: { type: 'array', items: str() } }, ['name']), ok: ref('ToolPreset') }),
  'DELETE /config/tool-presets/:id': d('Configuration', 'Delete a tool preset', { description: 'A chat already running with it keeps the tools it was given.', params: obj({ id: str() }), ok: OK }),
  'GET /settings/app': d('Configuration', 'Runtime settings', { description: 'The settings that change without a restart (`allowedHosts`, `maxConcurrentRuns`, `defaultPermissionMode`, `setupSeen`), and in `sources` where each value comes from: `env` (the environment set it, so it is read-only here), `file` (`app-settings.json`) or `default`. `allowedHosts` is the configured allowlist, the environment\'s hosts followed by the ones added here; their layers add up instead of replacing each other, so for this key `sources` names the highest layer that names any host and does not make it read-only. `allowedHostLayers` splits it by layer: `env` (fixed by `CLAUDIO_ALLOWED_HOSTS`), `file` (editable) and `runtime`, the exact hosts lent while their owner runs (a running tunnel\'s host), listed for reading only and never part of `allowedHosts`.', ok: ref('AppSettings') }),
  'PUT /settings/app': d('Configuration', 'Change runtime settings', { description: 'Only the settings the body names. A setting the environment set is refused with `400`, and so is an unknown key. `allowedHosts` is the exception: it replaces the hosts added here, which add to those of `CLAUDIO_ALLOWED_HOSTS`, so it is accepted even when the variable is set; a host the variable names already is not stored again, and the variable\'s hosts cannot be removed. It follows the rule of `CLAUDIO_ALLOWED_HOSTS` (a `*.domain` pattern needs two labels below the wildcard), takes no ports and applies to the next request. `maxConcurrentRuns` and `defaultPermissionMode` apply to the next run. `openaiToolCallTimeoutMinutes` (1 to 1440 minutes, 10 by default) applies to the next held client tool call of the OpenAI surface; `null` resets it to the default. Emits `settings.changed`.', body: ref('UpdateAppSettingsRequest'), ok: ref('AppSettings') }),
  'GET /dashboard/layout': d('Configuration', 'Read a Home layout', { description: 'The layout saved for one Home: `?project=<id>` for a project\'s, `?project=all` for All projects. `layout` is `null` when none is saved and the default applies. 404 for an unknown project.', querystring: obj({ project: str('A project id, or `all`') }, ['project']), ok: ref('StoredDashboardLayout') }),
  'PUT /dashboard/layout': d('Configuration', 'Save a Home layout', { description: 'Replaces the layout of one Home. The body is the whole layout: `{ version: 1, widgets: [{ id, type, size, config? }] }`, in the order they are drawn. 400 when a widget type is unknown or does not belong on that Home, a size is not one the type offers, an id repeats, or there are more than 40 widgets; 404 for an unknown project. A chat\'s token gets 403. Emits `dashboard.layout`.', querystring: obj({ project: str('A project id, or `all`') }, ['project']), body: ref('SaveDashboardLayoutRequest'), ok: ref('StoredDashboardLayout') }),
  'GET /settings/state': d('Configuration', 'Where each setting stands against its default', { description: 'Every server-side setting a settings row can reset, keyed by the row\'s `data-setting` id (`runs.concurrent`, `lessons.miner-model`, `point-flow-bounce`, `guards.rule.push`, `accounts.threshold`…). Each says whether it is `changed` (the store holds a value for it and that value differs from the default: a stored value equal to the default is not changed), its `source` (`env`, `stored` or `default`; a row set by the environment is never changed here) and its `default`, as the store defines it on this install (the image\'s `defaultPermissionMode`, the container\'s terminal `remote`). The browser\'s own settings (theme, language, motion, notification kinds) are not here: they never reach the server.', ok: ref('SettingsState') }),
  'DELETE /settings/state/:setting': d('Configuration', 'Reset a setting to its default', { description: 'Removes the stored value of one row, so its default applies again, and a default that changes later too; the value is never written back as the default. The reset goes through the store\'s own write and emits the event its `PUT` emits (`settings.changed`, `guards.changed`, `terminal.changed`, `tunnel.changed`, `collaborators.changed`, `providers.changed` after the re-detection, or nothing for the stores that emit nothing). A decision point\'s reset removes its `mode` and `threshold` and keeps its consent, which is withdrawn on its own. Answers the row\'s state after the reset. `404 setting-unknown` for an id that is not one, `409 setting-from-env` for a row the environment sets, `403` for a chat\'s token on every id, and for a `terminal.*` id the refusals of the terminal\'s own gate. A reset the store\'s rules refuse (a replay longer than the scrollback, say) is a `400` naming why.', params: obj({ setting: str('The row\'s `data-setting` id') }), ok: ref('SettingState') }),
  'GET /settings/overrides': d('Configuration', 'Projects that override a global setting', { description: 'For each global setting a project overrides, the ids of those projects, sorted by project name; an id no project overrides is absent. Counted: `engine.who-answers` (a project\'s decision provider other than `inherit`), `point-<id>` (a point\'s `mode` or `threshold`), `provider.limits` (any field of `providers.onLimit`) and `guards.rule.<rule>` (any flow stage that switches the rule). A project\'s provider order is not counted: the project settings drop it, since one provider runs. Project-only settings (`lessons`, `guards.chats`) are not counted: no global row is the same setting.', ok: ref('SettingOverrides') }),
  'DELETE /dashboard/layout': d('Configuration', 'Reset a Home layout', { description: 'Forgets the saved layout of one Home, so the default applies again. Answers `layout: null`. A chat\'s token gets 403. Emits `dashboard.layout`.', querystring: obj({ project: str('A project id, or `all`') }, ['project']), ok: ref('StoredDashboardLayout') }),
  'GET /config/resources/:kind': d('Configuration', 'List resources', { description: 'Saved workflows of the scope only: `GET /workflows/saved` also merges in the user\'s.', params: obj({ kind: KIND }), querystring: scopeQuery(), ok: list('ConfigResource') }),
  'GET /config/resources/:kind/:name': d('Configuration', 'Read a resource', { params: obj({ kind: KIND, name: str() }), querystring: scopeQuery(), ok: ref('ConfigResource') }),
  'PUT /config/resources/:kind/:name': d('Configuration', 'Create or replace a resource', { description: 'Skills are stored as `skills/<name>/SKILL.md`, workflows as the script `workflows/<name>.js` (an existing one keeps its own file, and is named by its `meta.name`), the other kinds as `<kind>/<name>.md`. `format` says which of the two the content is.', params: obj({ kind: KIND, name: str() }), querystring: scopeQuery(), body: obj({ content: str() }, ['content']), ok: ref('ConfigResource') }),
  'DELETE /config/resources/:kind/:name': d('Configuration', 'Delete a resource', { params: obj({ kind: KIND, name: str() }), querystring: scopeQuery(), ok: OK }),

  // ---- Config files
  'GET /config/files/roots': d('Config files', 'Available roots', { ok: list('ConfigFileRoot') }),
  'GET /config/files/tree': d('Config files', 'Nested file tree of a root', { querystring: obj({ root: ROOT }), ok: list('ConfigFileNode') }),
  'GET /config/files/content': d('Config files', 'Read a text file', { description: 'Up to 1 MB. Binary, hidden and out-of-root paths return 400.', querystring: obj({ root: ROOT, path: str('Path relative to the root') }, ['path']), ok: ref('ConfigFileContent') }),
  'PUT /config/files/content': d('Config files', 'Create or overwrite a file', { description: 'Parent directories are created. `executable` sets the mode (hook scripts).', body: ref('WriteConfigFileRequest'), ok: ref('ConfigFileContent') }),
  'DELETE /config/files/content': d('Config files', 'Delete a file or directory', { querystring: obj({ root: ROOT, path: str('Path relative to the root') }, ['path']), ok: OK }),

  // ---- Memory
  'GET /memory': d('Memory', 'Imported projects with their memory file counts', { ok: list('MemoryProjectSummary') }),
  'GET /memory/:project': d('Memory', 'Memory files of a project', { description: '`MEMORY.md` (the index loaded into every session) comes first.', ok: list('MemoryFile') }),
  'PUT /memory/:project/:name': d('Memory', 'Create or overwrite a memory file', { description: '`name` must end in `.md`.', body: obj({ content: str() }, ['content']), ok: ref('MemoryFile') }),
  'DELETE /memory/:project/:name': d('Memory', 'Delete a memory file', { ok: OK }),

  // ---- Project memory: the journal and memory proposals
  'GET /projects/:id/journal': d('Project memory', "A project's journal", { description: "Newest first, `limit` entries a page (50 by default, 200 at most); pass a page's `nextBefore` as `before` for the next one. `handed` says how many of the newest entries a flow run is handed with `--append-system-prompt`, up to 16 KiB: it stops at the first entry that does not fit, so what a run reads has no hole in it.", params: obj({ id: str('Project id') }), querystring: obj({ limit: str('Entries per page'), before: str("The `nextBefore` of the page read last") }), ok: ref('JournalPage') }),
  'POST /projects/:id/journal': d('Project memory', 'Write a journal entry', { description: 'A `decision` or a `note` (the default), written as the person, optionally about an item of the project (an item of another project, or none, is refused with 400) and referring to a document. `closed` entries are written when an item reaches `done`, once per item; `memory` entries when a proposal to the journal is approved. Refused with 409 while the Memory module is off. Emits `journal.changed`.', params: obj({ id: str('Project id') }), body: ref('CreateJournalEntryRequest'), ok: ref('JournalEntry'), created: true }),
  'DELETE /journal/:entryId': d('Project memory', 'Delete a journal entry', { description: 'Any kind. A proposal it came from keeps its decision and loses the reference. Refused with 409 while the Memory module is off. Emits `journal.changed`.', params: obj({ entryId: str('Journal entry id') }), ok: OK }),
  'GET /projects/:id/memory/proposals': d('Project memory', "The team's memory proposals", { description: 'Newest first, every status unless `status` names one. A proposal comes from a flow run\'s structured result and names its target: the project\'s `CLAUDE.md` (under a heading), a file of its CLI memory directory, the journal, or a path-scoped rule (`rule`: `.claude/rules/<file>` with `paths` as front matter, loaded by the CLI only for files matching them; 1 to 10 relative globs, no `..`).', params: obj({ id: str('Project id') }), querystring: obj({ status: str('`pending`, `approved` or `rejected`') }), ok: list('MemoryProposal') }),
  'POST /memory-proposals/:proposalId/approve': d('Project memory', 'Approve a memory proposal', { description: "Writes it, with `text` instead of the proposed text when given: appended under its heading of `CLAUDE.md` (a new `##` section when there is none), appended to its memory file (or created with frontmatter and indexed in `MEMORY.md`), added to the journal as a `memory` entry, or written as a rule: a new `.claude/rules/<file>` with the `paths` front matter, or the text appended to a rule file that already has the same paths. `file` renames a `rule` target's file for this approval. A rule file that exists with other paths (or none) is refused with 409 and nothing is written: approve it again with another `file`. A target that cannot be written leaves the proposal pending. Refused with 409 once decided, and while the Memory module is off. Emits `memory.proposal`, and `journal.changed` for the journal. Refused with 403 to a chat token: deciding what goes into memory is the person's.", params: obj({ proposalId: str('Memory proposal id') }), body: ref('ApproveMemoryProposalRequest'), ok: ref('MemoryProposal') }),
  'POST /memory-proposals/:proposalId/reject': d('Project memory', 'Reject a memory proposal', { description: 'Writes nothing but the decision and its optional reason. Refused with 409 once decided, and while the Memory module is off. Emits `memory.proposal`. Refused with 403 to a chat token.', params: obj({ proposalId: str('Memory proposal id') }), body: ref('RejectMemoryProposalRequest'), ok: ref('MemoryProposal') }),

  // ---- Lessons
  'GET /projects/:id/lessons': d('Project memory', "A project's lessons", { description: "Lessons mined from the person's corrections. `status` is `active` (the default), `proposed`, `retired`, `rejected`, `superseded` or `all`; anything else is 400. `handed` says what a run in the project is handed now: how many lessons, how many bytes of the budget, and how many were due but did not fit.", params: obj({ id: str('Project id') }), querystring: obj({ status: str('Lesson status, or `all`') }), ok: ref('LessonList') }),
  'GET /projects/:id/lessons/export': d('Project memory', "Download a project's lessons", { description: 'Every lesson of every status, as a JSON download (`Content-Disposition: attachment`). Nothing reads lessons back in: this is an export only.', params: obj({ id: str('Project id') }), ok: list('Lesson') }),
  'GET /projects/:id/lessons/jobs': d('Project memory', "A project's lesson mining jobs", { description: 'Newest first, `limit` jobs (20 by default, 100 at most; anything that is not a whole number from 1 is 400).', params: obj({ id: str('Project id') }), querystring: obj({ limit: str('Jobs to return') }), ok: list('LessonJob') }),
  'GET /lessons/global': d('Project memory', 'Global lessons', { description: "The lessons a person promoted to every project. `handed` is what a chat outside any project is handed. `status` works as on a project's list.", querystring: obj({ status: str('Lesson status, or `all`') }), ok: ref('LessonList') }),
  'GET /lessons/settings': d('Project memory', 'Lesson settings', { description: 'The global `lessons.json` document, with defaults for what it does not hold.', ok: ref('LessonSettings') }),
  'PUT /lessons/settings': d('Project memory', 'Change the lesson settings', { description: 'A partial update over the current document, validated as a whole: 400 names the field that is out of range. Refused with 403 to a chat token.', body: ref('LessonSettings'), ok: ref('LessonSettings') }),
  'GET /lessons/:lessonId': d('Project memory', 'A lesson', { description: 'With its evidence, the chats it names and the same rule found in other projects (`alsoInProjects`).', params: obj({ lessonId: str('Lesson id') }), ok: ref('Lesson') }),
  'PATCH /lessons/:lessonId': d('Project memory', 'Edit or pin a lesson', { description: "Changes the words (`trigger`, `action`), pins it, or both; the person's words are kept in whatever language they write. Active lessons only: 409 for another status or when it changed meanwhile, 400 when the text fails the checks. Refused with 409 while the Memory module is off and with 403 to a chat token. Emits `lesson.changed`.", params: obj({ lessonId: str('Lesson id') }), body: ref('UpdateLessonRequest'), ok: ref('Lesson') }),
  'POST /lessons/:lessonId/confirm': d('Project memory', 'Confirm a lesson', { description: 'Says it still holds: raises its confidence and restarts its decay. 409 unless active. Refused with 403 to a chat token. Emits `lesson.changed`.', params: obj({ lessonId: str('Lesson id') }), ok: ref('Lesson') }),
  'POST /lessons/:lessonId/retire': d('Project memory', 'Retire a lesson', { description: 'Keeps it but stops handing it to runs. 409 unless active. Refused with 403 to a chat token. Emits `lesson.changed`.', params: obj({ lessonId: str('Lesson id') }), body: ref('RetireLessonRequest'), ok: ref('Lesson') }),
  'POST /lessons/:lessonId/restore': d('Project memory', 'Restore a retired lesson', { description: 'Hands it to runs again. 409 unless retired. Refused with 403 to a chat token. Emits `lesson.changed`.', params: obj({ lessonId: str('Lesson id') }), ok: ref('Lesson') }),
  'DELETE /lessons/:lessonId': d('Project memory', 'Delete a lesson', { description: 'Removes the lesson and its evidence. 409 while it is still `proposed`: reject its proposal instead. Refused with 403 to a chat token. Emits `lesson.changed`.', params: obj({ lessonId: str('Lesson id') }), ok: OK }),
  'POST /lessons/:lessonId/promote': d('Project memory', 'Make a lesson global', { description: 'Copies an active project lesson into a global one, handed in every project, and answers the global lesson. 409 unless it is an active project lesson. Refused with 403 to a chat token. Emits `lesson.changed`.', params: obj({ lessonId: str('Lesson id') }), ok: ref('Lesson') }),
  'POST /lessons/:lessonId/demote': d('Project memory', 'Move a global lesson back to a project', { description: 'Goes back to the project it was promoted from, or to `projectId` when it has no origin (400 when neither exists). 409 unless it is a global lesson. Refused with 403 to a chat token. Emits `lesson.changed`.', params: obj({ lessonId: str('Lesson id') }), body: ref('DemoteLessonRequest'), ok: ref('Lesson') }),
  'POST /lessons/:lessonId/instructions': d('Project memory', 'Propose a lesson for CLAUDE.md', { description: 'Writes an `instructions` memory proposal made from the lesson, under `section` (`Lessons` by default); the person approves it after seeing the diff, and approving it retires the lesson. 409 when one is already waiting, when the lesson is not active, and while the Memory module is off. Refused with 403 to a chat token.', params: obj({ lessonId: str('Lesson id') }), body: ref('LessonInstructionsRequest'), ok: ref('MemoryProposal'), created: true }),
  'POST /memory-proposals/:proposalId/preview': d('Project memory', 'Preview an instructions proposal against CLAUDE.md', { description: 'The `CLAUDE.md` as it is now, its sha256, the unified diff the approval would make and the size after. `text` previews an edit. Send the sha256 as `previewOf` when approving: a `CLAUDE.md` that changed since is refused with 409. 400 unless the proposal targets `instructions`; 409 when its project is not imported. Writes nothing.', params: obj({ proposalId: str('Memory proposal id') }), body: ref('PreviewMemoryProposalRequest'), ok: ref('MemoryProposalPreview') }),
  'POST /chats/:id/lessons/mine': d('Project memory', 'Look for lessons in a chat', { description: "Queues a mining job for the chat now, even while the `lesson.mine` point is off, and skips the gate; the cost cap is `miner.maxCostUsd`. 404 for an unknown chat; 409 for a chat outside a project, the Memory module off, a job already open for the chat, or `manualMining` off; 429 when the chat was mined by hand in the last 10 minutes or the day's cap is reached. Refused with 403 to a chat token. Emits `lesson.job`.", params: obj({ id: str('Chat id') }), ok: ref('LessonJob'), accepted: true }),

  // ---- Connectors
  'POST /connectors/:id/authorise': d('Connectors', "Start a connector's sign-in", { description: "Asks the CLI (`mcp_authenticate`, from a short-lived process on the default account) for the connector's sign-in link and returns it: a claude.ai page the person opens in their browser, which runs the whole sign-in (`callbackExpected: false`). Claudio never fetches or logs the link. Poll `GET /connectors?refresh=true` afterwards for the connector to read `connected`. `:id` is the connector's id as listed. 404 for an unknown connector, 409 when it is not `needs-auth`, 502 when the CLI cannot start the sign-in. Not open to a chat's token.", params: obj({ id: str('Connector id, as listed (e.g. `claude.ai Gmail`)') }), ok: ref('ConnectorAuthorisation') }),
  'GET /connectors': d('Connectors', 'claude.ai connectors and their status', { description: 'Read from `claude mcp list` (it connects to every server, so it takes seconds and is cached for a minute). Only servers named `claude.ai …` count as connectors. Each has prepared prompts a client can open a new chat with; the answer also says what a person has to do to authorise one and which claude.ai features (web artifacts, claude.ai memory) have no CLI surface.', querystring: obj({ refresh: str('`true` skips the one-minute cache', { enum: ['true', 'false'] }) }), ok: ref('ConnectorsOverview') }),

  // ---- Plugins
  'GET /plugins': d('Plugins', 'Installed plugins and marketplaces', { ok: ref('PluginsOverview') }),
  'GET /plugins/available': d('Plugins', 'Search the marketplaces', { querystring: obj({ q: str('Free-text filter') }), description: 'At most 100 results.', ok: list('AvailablePlugin') }),
  'GET /plugins/details': d('Plugins', "A plugin's component inventory", { querystring: obj({ plugin: str('`name@marketplace`') }, ['plugin']), ok: ref('CliTextResult') }),
  'POST /plugins/install': d('Plugins', 'Install a plugin', { body: ref('PluginActionRequest'), ok: ref('CliTextResult') }),
  'POST /plugins/uninstall': d('Plugins', 'Uninstall a plugin', { body: ref('PluginActionRequest'), ok: ref('CliTextResult') }),
  'POST /plugins/enable': d('Plugins', 'Enable a plugin', { body: ref('PluginActionRequest'), ok: ref('CliTextResult') }),
  'POST /plugins/disable': d('Plugins', 'Disable a plugin', { body: ref('PluginActionRequest'), ok: ref('CliTextResult') }),
  'POST /plugins/marketplaces': d('Plugins', 'Add a marketplace', { body: obj({ source: str('GitHub `owner/repo`, URL or path') }, ['source']), ok: ref('CliTextResult') }),
  'POST /plugins/marketplaces/update': d('Plugins', 'Update one or all marketplaces', { body: obj({ name: str('Omit to update all') }), ok: ref('CliTextResult') }),
  'DELETE /plugins/marketplaces/:name': d('Plugins', 'Remove a marketplace', { ok: ref('CliTextResult') }),

  // ---- Push
  'GET /push/key': d('Push', 'The VAPID public key to subscribe with', { description: 'The keypair is made on first use and kept as `push.json` in the data directory (mode 600). The private half never leaves the server. `configured: false` means it could not be made and nothing will be sent.', ok: ref('PushKeyInfo') }),
  'GET /push/subscriptions': d('Push', 'Installs registered to be pushed to', { description: 'Endpoints are truncated: a full push endpoint URL is a capability to notify that install. Each row carries the `id` its registration returned, which is how a browser recognises itself in the list.', ok: list('PushSubscriptionSummary') }),
  'POST /push/subscriptions': d('Push', 'Register or refresh a subscription', { description: "The browser's `PushSubscription` JSON plus the notification kinds this install wants (every kind when omitted) and a label for the list. An endpoint that is already registered is refreshed, keeping its `createdAt`.", body: ref('RegisterPushSubscriptionRequest'), ok: ref('PushSubscriptionSummary'), created: true }),
  // ---- Terminal
  'GET /terminal': d('Terminal', 'The terminal feature', {
    description:
      'Whether the terminal is on and can be opened from here: `enabled`, `available`, and when it is not, the `reason` (`off`, `disabled-by-env`, `pty-missing`, `host-failed`, or what the caller adds: `needs-auth`, `remote-off`, `needs-tunnel`, `from-agent`). The settings come with `sources` (where each value is set: `env` is read-only here), whether the peer-process check can run on this machine (`peerCheck`) and how many shells run. It answers while the feature is off, which is how the person finds out why. `405` in read-only mode and `403` to a chat\'s token.',
    ok: ref('TerminalStatus'),
  }),
  'PUT /terminal/settings': d('Terminal', 'Change the terminal settings', {
    description:
      '`enabled`, `remote` (`off`: this machine only, `tunnel`: another device only through the tunnel, `any`: also over the plain LAN address, which sends the token and every keystroke unencrypted), `maxTerminals` (1–32), `idleMinutes` (5–1440), `scrollbackLines` (500–10000), `replayLines`, `shell` (an absolute path listed in `/etc/shells`, or null for the login shell) and `loginShell`. Turning it off closes every terminal and is the one change a caller who could not open one may make. `409 terminal.env-locked` for a value `CLAUDIO_TERMINAL` fixes. Emits `terminal.changed`.',
    body: obj({
      enabled: { type: 'boolean' },
      remote: ref('TerminalRemote'),
      maxTerminals: { type: 'integer' },
      idleMinutes: { type: 'integer' },
      scrollbackLines: { type: 'integer' },
      replayLines: { type: 'integer' },
      shell: { type: ['string', 'null'] },
      loginShell: { type: 'boolean' },
    }),
    ok: ref('TerminalStatus'),
  }),
  'GET /terminal/history': d('Terminal', 'Terminal sessions and attempts', {
    description:
      'Sessions newest first, each with its attachments: who attached, from where, with which `Origin`, when, and how many bytes went each way, never what they were. An attempt the gate or the socket turned away (a chat\'s token, a chat\'s process, a request from another device with authentication off, a bad ticket or `Origin`) is an attachment with `refused` set; one that names no terminal is an entry of its own with an empty `id`.',
    querystring: obj({ limit: str('Entries on the page, 1–200; default 50'), offset: str('Entries to skip') }),
    ok: ref('TerminalHistoryPage'),
  }),
  'GET /terminals': d('Terminal', 'Open terminals', {
    description: 'The running terminals and those that ended in the last hour, oldest first. Filter by `project` (a project id) or `chat` (a chat id).',
    querystring: obj({ project: str('Only the terminals opened for this project'), chat: str('Only the terminals opened for this chat') }),
    ok: list('Terminal'),
  }),
  'POST /terminals': d('Terminal', 'Open a terminal', {
    description:
      'A shell in the project\'s directory (`projectId`, and optionally one of its `worktree` paths as `GET /projects/:id/worktrees` lists it), in the chat\'s worktree or directory (`chatId`), or in the configured workspace (`workspace: true`, where chats outside any project run): ids go in and the path comes out, never the other way. A chat outside any project opens in its own directory, which must be inside the workspace. `cols` and `rows` default to 80 × 24. `409 terminal.limit` past `maxTerminals`, `400 terminal.no-project` for a chat whose project is gone, `400 terminal.bad-cwd` for a directory outside its project or the workspace. Emits `terminal.changed`.',
    body: obj({ projectId: str(), worktree: str(), chatId: str(), cols: { type: 'integer' }, rows: { type: 'integer' } }),
    ok: ref('Terminal'),
    created: true,
  }),
  'GET /terminals/:id': d('Terminal', 'One terminal', { ok: ref('Terminal') }),
  'POST /terminals/:id/ticket': d('Terminal', "A ticket for the terminal's socket", {
    description:
      'The browser\'s `WebSocket` cannot send `Authorization`, so the socket takes a ticket instead of the token: 32 random bytes, valid 30 seconds, good for one connection, and bound to this terminal, the caller and the `Origin` that asked. A new one is asked for on every (re)connect.',
    ok: ref('TerminalTicket'),
  }),
  'GET /terminals/:id/socket': d('Terminal', "The terminal's stream", {
    description:
      'A WebSocket, opened with `?ticket=` and an `Origin` that is the page\'s own. Server to client: binary frames are the shell\'s output, text frames are `TerminalServerFrame` (`hello` with the screen to repaint, then the unfinished tail as a binary frame; `size`, `exit`, `closed`). Client to server: binary frames are input (at most 64 KiB each), text frames are `TerminalClientFrame` (`resize`, `ack` of the bytes xterm has parsed, `focus`). Refused before the upgrade with `401` (ticket), `403` (gate, `Origin`), `404`, `405` (read-only), `409`.',
    querystring: obj({ ticket: str('From `POST /terminals/:id/ticket`') }, ['ticket']),
    ok: {},
  }),
  'DELETE /terminals/:id': d('Terminal', 'Close a terminal', {
    description: 'Sends SIGHUP, then SIGTERM, then SIGKILL after 3 seconds to the shell\'s process group and what descends from it. Emits `terminal.changed`.',
    ok: ref('Terminal'),
  }),

  'DELETE /push/subscriptions': d('Push', 'Unregister a subscription', { description: 'By `endpoint` (what a browser turning the switch off knows) or by `id` (what the Settings list shows). `removed: false` when no such install was registered.', body: ref('RemovePushSubscriptionRequest'), ok: obj({ removed: { type: 'boolean' } }, ['removed']) }),
  'POST /push/test': d('Push', 'Send one test notification', { description: 'Proves push works without waiting for a chat to stop. Aimed at one install by `endpoint` or `id`, or at every registered one when the body names none. An endpoint the push service reports as gone (404/410) is deleted and counted in `removed`.', body: ref('SendTestPushRequest'), ok: ref('PushSendResult') }),

  // ---- Security
  'GET /security/auth': d('Security', 'How the API is guarded', { description: 'The token is never returned: only whether one is set. `firstRunPending` is true while the owner token a container made on its first start has not been used yet, and `firstRunToken` while that token is still the one set, until it is rotated.', ok: ref('AuthConfig') }),
  'PUT /security/auth': d('Security', 'Change the auth mode or read-only', { description: 'Turning on `token` needs a token already set, and `oidc` an issuer and an audience, so a mode cannot lock everyone out. This route stays reachable in read-only mode: it is the switch.', body: ref('UpdateAuthConfigRequest'), ok: ref('AuthConfig') }),
  'POST /security/allowed-hosts/claim': d('Security', 'Add the host this request came in on to the allowed hosts', { description: 'The one route the host check lets through for a host that is not allowed, so the owner can add the address they are using. It adds the request\'s own `Host` name (port stripped) to the file layer that `PUT /settings/app` edits, and answers the resulting list. It needs the owner\'s token or OIDC identity: `403 host.needs-auth` when the mode is `none`, `403 host.not-owner` for the desktop credential or a chat\'s token, `400 host.invalid` for a name the allowlist refuses, `405` in read-only mode. A wrong credential is `401` and counts in the same back-off as any other route.', ok: ref('ClaimHostResult') }),
  'POST /security/token': d('Security', 'Set or rotate the bearer token', { description: 'Returns the token once and keeps only its SHA-256. Omit `token` to have one generated. Send it as `Authorization: Bearer …`; `GET /events`, `GET /chats/{id}/stream`, `GET /uploads/{id}/content`, `GET /chats/{id}/export` and `GET /projects/{id}/export` also accept `?token=`, because a browser cannot set a header on those.', body: ref('SetAuthTokenRequest'), ok: ref('AuthTokenResult') }),
  'DELETE /security/token': d('Security', 'Remove the bearer token', { description: 'Refused while the mode is `token`.', ok: ref('AuthConfig') }),
  'GET /settings/guards': d('Security', 'The guard settings, their status and the rules', { description: 'Whether guards are on for automated runs, the mode (`enforce` or `observe`), each rule, the protected-config globs and the extra roots, with whether the guard can run on this machine and why not. A chat\'s token may read it.', ok: ref('GuardSettingsView') }),
  'PUT /settings/guards': d('Security', 'Change the guard settings', { description: 'Only the keys sent change; `rules` merges over the stored ones. `integrity` is not a key: it cannot be switched off. Applies to the next process spawned, since a running CLI keeps the hooks it started with. 400 for an unknown key, a non-boolean, a mode not in the list, more than 200 globs, an absolute glob or one with `..`, or an `extraRoots` entry that is not an absolute, existing directory (not `/`, the home folder or the data dir). 403 for a chat\'s token.', body: ref('UpdateGuardSettingsRequest'), ok: ref('GuardSettingsView') }),
  'GET /guard-events': d('Security', 'What the guards did, newest first', { description: 'Blocks and the other outcomes of guarded tool calls. `next` is the `before` cursor of the following page, null at the end. A chat\'s token may read only its own `chatId`; any other filter answers 403.', querystring: obj({ chatId: str('Events of this chat'), orchestrationId: str('Events of this graph'), flowRunId: str('Events of this flow run'), projectId: str('Events of this project'), rule: str('One rule id'), outcome: str('`blocked`, `observed`, `missing`, `unarmed`, `error` or `allowed-once`'), before: str('The `seq` of the last event of the previous page'), limit: str('1-200, default 50') }), ok: ref('GuardEventPage') }),
  'POST /guards/check': d('Security', 'Ask the guard about one tool call', { description: 'Runs the decision engine in-process with the current settings, unless `rules` or `roots` say otherwise. Nothing is run or recorded. 400 for a bad input or a root that is not absolute. 403 for a chat\'s token: an agent must not have an oracle to probe the rules with.', body: ref('GuardCheckRequest'), ok: ref('GuardCheckResult') }),
  'GET /audit': d('Security', 'Mutating requests, newest first', { description: 'When, who (`token:<id>` for the owner token, an OIDC subject, `desktop` for the desktop app, `chat:<id>` for a chat\'s own token, `env` or `claudio` for what the wrapper did itself, `local` when nothing guards the API, `anonymous` for a request refused before it was identified), method, path, status, a one-line English summary built from the route, and `route`: the matched `METHOD /pattern` (`POST /chats/:id/stop`), null on older rows and on what the wrapper records itself, which the web uses to word the row in the reader\'s language. Bodies are never recorded: they carry prompts and secrets.', querystring: obj({ limit: str('1-500, default 50'), from: str('Offset within the filtered set'), path: str('Matches anywhere in the path; `%`, `_` and `\\` are taken literally'), method: str('Exact, case-insensitive: `POST`'), status: str('A code (`404`) or a class (`4xx`)') }), ok: ref('AuditPage') }),

  // ---- Remote access
  'GET /tunnel': d('Remote access', 'The tunnel', { description: 'Its state (`stopped`, `starting`, `verifying`, `active`, `stopping`, `failed`), the tailnet address and since when it works (only while `active`), why it failed (only while `failed`, with a `code` to translate), whether this deploy offers the tunnel at all (`enabled`, `CLAUDIO_TUNNEL`), whether Claudio runs the `tailscaled` itself and so signs it in from the setup (`managed`, the Docker image), whether Tailscale can carry it (`tailscale`: `missing`, `unsupported`, `daemonDown`, `loggedOut`, `stopped`, `httpsDisabled` or `ready`, with the CLI version, the node name and a translatable `reason`), the Serve `port` and its settings. Asks the `tailscale` CLI again when its last answer is older than two seconds.', ok: ref('TunnelStatus') }),
  'PUT /tunnel/settings': d('Remote access', 'Change the tunnel settings', { description: '`startWithClaudio` opens the tunnel whenever Claudio starts; off by default. `startWithAgentry`, its name before the rename, is still accepted. Emits `tunnel.changed`.', body: ref('UpdateTunnelSettingsRequest'), ok: ref('TunnelStatus') }),
  'POST /tunnel/start': d('Remote access', 'Start the tunnel', { description: 'Refused with `409` while the auth mode is `none`: the address would hand the machine to whoever on the tailnet has it. Also `409`, with `tunnel.disabled`, where the deploy does not offer the tunnel (`enabled` false). Answers at once, in `starting`, after reading Tailscale\'s readiness; a Tailscale that is not `ready` answers `failed` with its reason. Claudio then adds `tailscale serve --bg --https=<port>` to this server, refusing a port that already serves something else (`tunnel.portTaken`), reads the Serve config back, and only then does the node\'s exact name join the allowlist. Emits `tunnel.changed` on every move.', ok: ref('TunnelStatus') }),
  'POST /tunnel/stop': d('Remote access', 'Stop the tunnel', { description: 'Takes the node\'s name off the allowlist, then removes Claudio\'s Serve rule (`tailscale serve --https=<port> off`), only if the port still holds exactly that rule. Turning the auth mode to `none` does this first by itself.', ok: ref('TunnelStatus') }),

  // ---- Uploads
  'GET /v1/models': d('OpenAI-compatible', 'The models a chat can run on, in OpenAI\'s list shape', {
    description: 'Every model of every provider with a driver, as `{ object: "list", data: [{ id, object: "model", created, owned_by }] }`. `id` is the value the CLI takes (`sonnet`); `owned_by` is the provider id; `created` is 0 because the catalogue has no date.',
  }),
  'GET /v1/models/:id': d('OpenAI-compatible', 'One model, by its value or a concrete id it stands for', {
    description: 'Also found by a concrete id an alias resolves to (`claude-sonnet-5-5` for `sonnet`). An unknown id is `404` with `code: "model_not_found"`.',
    params: obj({ id: str('Model id') }, ['id']),
  }),
  'POST /v1/chat/completions': d('OpenAI-compatible', 'A Chat Completions turn, answered whole or streamed', {
    description:
      'Body: OpenAI\'s Chat Completions request. The turn runs in a Claudio chat: a new one, or the one the history (or `X-Claudio-Chat-Id`) leads to, resumed with only the new messages. `stream: true` answers `text/event-stream` with `data: <chunk>` lines ending in `data: [DONE]`, a usage chunk with `choices: []` before it when `stream_options.include_usage` is set, and `X-Claudio-Cost-Usd` as a trailer. `response_format` `json_schema` or `json_object` holds the answer to that schema (the CLI\'s `--json-schema`): the content is the structured output as JSON text, streamed as one chunk before the finish chunk, and a turn that ends without it is a `500 server_error`. Client `tools` (type `function`) are handed back: the turn ends with `finish_reason: \"tool_calls\"` while the chat\'s CLI holds the calls, and the next request, whose trailing `tool` messages answer every call, continues the same turn (the results must match the calls, else `400`; a chat whose process is gone resumes cold and answers `X-Claudio-Resume: cold`). `tool_choice` `none` ignores the tools (named in `X-Claudio-Ignored`), a named function and `parallel_tool_calls: false` are enforced, `required` is an instruction. Refused with `400`: `n > 1`, the legacy `functions`, tools together with `response_format` (`unsupported_parameter`), and tool names that are too long or name one of Claude Code\'s tools (`invalid_request_error`). `X-Claudio-Chat-Id` and the conversation key only continue chats this surface started (origin `api`). Bodies up to about 27 MB, for inline images. Requests on one conversation run one after another. A client that disconnects interrupts the turn.',
    headers: obj({
      'x-claudio-chat-id': str('Continue this chat, one with origin `api`; any other id is 404'),
      'x-claudio-cwd': str('An absolute directory inside the workspace or an imported project, for a new chat'),
      'x-claudio-tool-preset': str('A stored tool preset id (`GET /config/tool-presets`); the default preset otherwise'),
      'x-claudio-spend-override': str('`1` goes on past the daily spend cap', { enum: ['1'] }),
    }),
  }),
  'POST /v1/responses': d('OpenAI-compatible', 'A Responses API turn, answered whole or streamed', {
    description:
      'Body: OpenAI\'s Responses request. `input` is a string or a list of items (`message` with roles `user`, `assistant`, `system` and `developer` and parts `input_text`, `input_image` by data URL or http(s), `output_text`, `refusal`; `function_call`; `function_call_output`; `reasoning` items are dropped). `instructions` join the system prompt but not the conversation key. `previous_response_id` continues the chat of a stored response with only the new items; an unknown, deleted or `store: false` id, or one whose chat is gone, is `404 not_found` (`param: previous_response_id`). Without it, a resent history finds its chat by the conversation key, as on `/v1/chat/completions`. `store` (true by default) keeps the response for `GET /v1/responses/:id` and `previous_response_id` for 7 days; it goes with its chat. The answer is the response object (`output` of `message` and `function_call` items, `usage` with `input_tokens_details.cached_tokens`, `status` `completed`, or `incomplete` with `incomplete_details.reason` `max_output_tokens` when a budget cut it). `stream: true` answers the semantic events (`event: <type>` and `data: <event>` with a rising `sequence_number`), from `response.created` to `response.completed`, `response.incomplete` or `response.failed`, with `X-Claudio-Cost-Usd` as a trailer. `text.format` `json_schema` / `json_object` is the structured output, as `response_format` is on Chat Completions. Flat function `tools` are handed back: the response ends `completed` with `function_call` items while the chat\'s CLI holds the calls, and the next request\'s `function_call_output` items (with `previous_response_id` or the whole history) continue the same turn. Refused with `400 unsupported_parameter`: `background: true`, `conversation`, `prompt`, hosted tools (`web_search`, `file_search`, `code_interpreter`, computer use, `image_generation`, `mcp`…) and their items, `allowed_tools`, `item_reference`, and tools together with `text.format`. Headers in and out as on `/v1/chat/completions`.',
    headers: obj({
      'x-claudio-chat-id': str('Continue this chat, one with origin `api`; any other id is 404'),
      'x-claudio-cwd': str('An absolute directory inside the workspace or an imported project, for a new chat'),
      'x-claudio-tool-preset': str('A stored tool preset id (`GET /config/tool-presets`); the default preset otherwise'),
      'x-claudio-spend-override': str('`1` goes on past the daily spend cap', { enum: ['1'] }),
    }),
  }),
  'GET /v1/responses/:id': d('OpenAI-compatible', 'A stored response', {
    description: 'The response object as `POST /v1/responses` answered it, while it is stored (`store` not false, not deleted, not expired after 7 days, its chat not deleted). Otherwise `404 not_found`.',
    params: obj({ id: str('Response id, `resp_…`') }, ['id']),
  }),
  'DELETE /v1/responses/:id': d('OpenAI-compatible', 'Delete a stored response', {
    description: 'Removes the stored response, not its chat: `{ id, object: "response.deleted", deleted: true }`. It can no longer be retrieved or continued with `previous_response_id`; a client resending the whole history still finds the chat. `404 not_found` when no such response is stored.',
    params: obj({ id: str('Response id, `resp_…`') }, ['id']),
  }),
  'GET /v1/responses/:id/input_items': d('OpenAI-compatible', "A stored response's input items", {
    description: 'The items the request carried, each with an id (the client\'s, or one Claudio gave it), in OpenAI\'s list shape `{ object: "list", data, first_id, last_id, has_more }`. Newest first unless `order=asc`; `limit` 1 to 100 (20 by default); `after` an item id to page from.',
    params: obj({ id: str('Response id, `resp_…`') }, ['id']),
    querystring: obj({ after: str('An item id: list the items after it'), limit: str('1 to 100, 20 by default'), order: str('`asc` or `desc` (the default)') }),
  }),
  'POST /openai/client-tools/:id/mcp': d('OpenAI-compatible', "The stub MCP server of one chat's client tools", {
    description:
      "Called by the chat's own CLI process, never by a client: JSON-RPC over MCP's Streamable HTTP, answered as plain JSON (`initialize`, `ping`, `tools/list`, `tools/call`; notifications get `202`; anything else `-32601`). Lists the client's `tools` with `readOnlyHint`; `tools/call` returns the result the client already sent, by `_meta[\"claudecode/toolUseId\"]` or, without it, the oldest result for that tool, and never waits. Only the process's own `CLAUDIO_API_TOKEN` is accepted, and only for the chat the session belongs to (`401` otherwise). The session goes with the chat: once the chat is removed, its URL answers `401`.",
    params: obj({ id: str("The session id in the stub's URL") }, ['id']),
  }),
  'GET /openai/client-tools/:id/mcp': d('OpenAI-compatible', 'No server-initiated stream', { description: 'Always `405`: the stub has no stream of its own to offer.', params: obj({ id: str("The session id in the stub's URL") }, ['id']) }),
  'DELETE /openai/client-tools/:id/mcp': d('OpenAI-compatible', 'No MCP session to end', { description: 'Always `405`: the stub keeps no MCP session; it goes with the chat.', params: obj({ id: str("The session id in the stub's URL") }, ['id']) }),
  'POST /uploads': d('Uploads', 'Upload a file to attach', { description: 'The request body is the file itself, sent as `application/octet-stream`; `name` is its file name. The type is read from the bytes. Limits: images (PNG, JPEG, GIF, WebP) 5 MB, PDFs 32 MB, anything else 50 MB. Files are kept in the data dir, outside every project, and every run can read them.', querystring: obj({ name: str('File name') }), ok: ref('Attachment'), created: true }),
  'GET /uploads/:id': d('Uploads', "An upload's metadata", { ok: ref('Attachment') }),
  'GET /uploads/:id/content': d('Uploads', 'The uploaded file', { description: 'Images and PDFs are served inline; any other type as a download, never rendered.' }),
  'POST /workspaces': d('Workspaces', 'Create a workspace from a tar.gz', { description: "Either `{ url }` as JSON, an `https` URL on a host of `CLAUDIO_WORKSPACE_HOSTS` (`codeload.github.com` by default) that Claudio downloads, following at most three redirects, each to an allowed host and a public address; or the archive itself as the body with `Content-Type: application/gzip`, read as a stream. The URL is never logged, stored or put in an error: the workspace keeps its host alone. Extraction is streamed and takes regular files and directories only: a link, a device, an absolute path, a `..`, or a `.git` folder refuses the archive (`400 workspace-bad-archive`). When the archive holds one top-level directory, chats run in it. Caps: 100 MB compressed, 500 MB extracted, 50 000 entries, 60 s, 2 GB under the root (`413 workspace-too-large`, `408 workspace-timeout`) and 20 workspaces (`429 workspace-limit`); over a cap nothing is left on disk. A host off the list is `400 workspace-host-not-allowed`, a private address `400 workspace-address-blocked`, a download that fails `502 workspace-download-failed`.", body: ref('CreateWorkspaceRequest'), ok: ref('Workspace'), created: true }),
  'GET /workspaces/:id': d('Workspaces', 'A workspace', { description: '`404 workspace-not-found` for an id that never was, `410 workspace-expired` for one that expired or was removed.', params: obj({ id: str('Workspace id (`ws_…`)') }), ok: ref('Workspace') }),
  'DELETE /workspaces/:id': d('Workspaces', 'Remove a workspace', { description: 'Stops the chats running in it first, then removes its folder. `204`, also for one already removed; `404` for an unknown id, `409` while it is still being created.', params: obj({ id: str('Workspace id (`ws_…`)') }) }),

  // ---- Schedules
  'GET /schedules': d('Schedules', 'List schedules', { description: 'Oldest first, each with when it last fired and when it fires next (null while disabled).', ok: list('Schedule') }),
  'GET /schedules/preview': d('Schedules', 'Say what a cron expression will do', { description: 'Nothing is saved. An invalid expression answers `valid: false` with the field that is wrong, so a form can show it while it is typed.', querystring: obj({ cron: str('Five fields, or `@hourly`, `@daily`, `@weekly`, `@monthly`, `@yearly`'), timezone: str('IANA zone; the server\'s when omitted'), count: { type: 'integer', description: 'How many upcoming fires to list (default 5, at most 20)' } }, ['cron']), ok: ref('SchedulePreview') }),
  'POST /schedules': d('Schedules', 'Create a schedule', { description: 'The target is a chat (a `NewChatRequest`) or an orchestration (an `OrchestrationSpec`). It starts enabled unless `enabled` is false. `overlap` says what a slot does while the last run is still going (its chat working or waiting on a person, its orchestration running): `parallel` (the default) starts it anyway, `skip` records it as `overlapped` and starts nothing, `queue` starts it when that run ends, one pending at most. The clock starts now: slots before creation are not missed windows.', body: ref('CreateScheduleRequest'), ok: ref('Schedule'), created: true }),
  'GET /schedules/:id': d('Schedules', 'One schedule', { ok: ref('Schedule') }),
  'PATCH /schedules/:id': d('Schedules', 'Edit a schedule', { description: 'Changing the expression or the zone, or switching it on, starts its clock afresh: the time it was off is not counted as missed.', body: ref('UpdateScheduleRequest'), ok: ref('Schedule') }),
  'DELETE /schedules/:id': d('Schedules', 'Delete a schedule and its history', { description: 'Chats and orchestrations it already started are not touched.', ok: OK }),
  'POST /schedules/:id/enable': d('Schedules', 'Switch a schedule on', { ok: ref('Schedule') }),
  'POST /schedules/:id/disable': d('Schedules', 'Switch a schedule off', { ok: ref('Schedule') }),
  'POST /schedules/:id/run': d('Schedules', 'Run a schedule now', { description: 'Starts its target immediately, whatever the timetable says and even while it is disabled. The run is recorded without a slot and does not affect when it fires next; the overlap policy does not apply to it. A target that fails to start is a run with status `failed` and its error, not an HTTP error.', ok: ref('ScheduleRun'), created: true }),
  // ---- Collaborators
  'GET /collaborators': d('Collaborators', 'Collaborators: on or off, identity and connection', { description: "The settings (`collaborators/settings.json`), this install's endpoint id (null until it is first turned on), how the endpoint is connected (`off`, `starting`, `online`, `no-relay`, `offline`) and its home relay. `unavailable` names why the module cannot run here (`platform`, `load`, `host`), with the rest of Claudio unaffected.", ok: ref('CollaboratorsStatus') }),
  'PUT /collaborators': d('Collaborators', 'Turn Collaborators on or off, or change its settings', { description: 'Only the fields sent change: `enabled`, `displayName`, `label`, `relayUrl`, `assistantReads` (the assistant reads what teammates share, on by default). Turning it on generates the install\'s key once (kept in the secret vault) and binds the endpoint; off lets it go and opens no socket. 503 when the module is unavailable. Emits `collaborators.changed` (`settings`).', body: ref('UpdateCollaboratorsRequest'), ok: ref('CollaboratorsStatus') }),
  'GET /collaborators/groups': d('Collaborators', 'The groups this install belongs to', { description: "Each with its roster head, owner, members, whether it is frozen and any conflict the owner's install found, plus the joins this install sent: waiting for an owner, or `denied` by the owner or `expired` before it answered until they are dismissed.", ok: ref('GroupList') }),
  'POST /collaborators/groups': d('Collaborators', 'Create a group', { description: 'This install becomes its owner, at roster version 1. 409 while Collaborators is off; 400 for a missing name or one over 100 characters. Emits `collaborators.changed` (`roster`).', body: ref('CreateGroupRequest'), ok: ref('Group'), created: true }),
  'DELETE /collaborators/groups/:id': d('Collaborators', 'Leave a group', { description: "Deletes the copies of what its members share and tells the owner. The owner cannot leave a group that still has members (409): transfer it first. Emits `collaborators.changed` (`roster`).", params: obj({ id: str('Group id') }), ok: OK }),
  'POST /collaborators/groups/:id/invites': d('Collaborators', 'Make an invite', { description: 'The owner only (403 otherwise): a one-time invite, valid 7 days, as the text an invitee pastes (the QR code encodes the same). It names up to three online members to relay a join through while the owner is away. 409 `not-ready` until the endpoint is bound.', params: obj({ id: str('Group id') }), ok: ref('GroupInvite'), created: true }),
  'POST /collaborators/join': d('Collaborators', 'Join a group with an invite', { description: '`joined` when the owner signed in the same round trip; `pending` when a member holds the sealed request until the owner is back, who then accepts or denies it. 400 for a damaged invite or one this install made, 400 `expired`, 409 `refused` when the owner refuses it. Emits `collaborators.changed` (`roster`).', body: ref('JoinGroupRequest'), ok: ref('JoinGroupResult') }),
  'DELETE /collaborators/join/:groupId': d('Collaborators', 'Stop waiting for a join, or dismiss one that ended', { description: 'Forgets a request this install sent: one still waiting (a member may still hold it), or one the owner denied or whose invite expired. 404 when there is none.', params: obj({ groupId: str('Group id') }), ok: OK }),
  'GET /collaborators/groups/:id/join-requests': d('Collaborators', 'Joins waiting for the owner', { description: 'The owner only: requests relayed to this install while it was offline, each with who relayed it and when the invite expires.', params: obj({ id: str('Group id') }), ok: list('JoinRequest') }),
  'POST /collaborators/groups/:id/join-requests/:from/accept': d('Collaborators', 'Accept a join', { description: 'The owner signs a roster version that adds the joiner. 404 when there is no such request. Emits `collaborators.changed` (`roster`).', params: obj({ id: str('Group id'), from: str("The joiner's endpoint id") }), ok: ref('Group') }),
  'POST /collaborators/groups/:id/join-requests/:from/deny': d('Collaborators', 'Deny a join', { description: "Drops the request and remembers the denial until the invite would have expired: the joiner is told when it next asks this install, and members learn it on their next sync to tell the joiner while this install is away (the member that held the request is told at once). 404 when there is no such request. Emits `collaborators.join-answered` and `collaborators.changed` (`roster`).", params: obj({ id: str('Group id'), from: str("The joiner's endpoint id") }), ok: OK }),
  'DELETE /collaborators/groups/:id/members/:endpointId': d('Collaborators', 'Remove a member', { description: "The owner only: signs a version without them. Their install stops being served; the copies it already holds stay with it. Emits `collaborators.changed` (`roster`).", params: obj({ id: str('Group id'), endpointId: str("The member's endpoint id") }), ok: ref('Group') }),
  'PUT /collaborators/groups/:id/owner': d('Collaborators', 'Hand a group to another member', { description: 'The owner only: signs a version naming the new owner, who signs every version after it. Emits `collaborators.changed` (`roster`).', params: obj({ id: str('Group id') }), body: ref('TransferGroupOwnershipRequest'), ok: ref('Group') }),
  'GET /projects/:id/sharing': d('Collaborators', "A project's sharing", { description: "The groups it is shared with, its share key (the default is computed from the repository's remote, `upstream` before `origin`, and stored the first time), the `shareId` routes use, the remotes to pick from, the subpath, and `keyInUse` when another local project already shares under the key.", params: obj({ id: str('Project id') }), ok: ref('ProjectSharing') }),
  'PUT /projects/:id/sharing': d('Collaborators', "Change a project's sharing", { description: "Only the fields sent change: `groups`, an edited `shareKey` (`[a-z0-9._/#-]{3,200}`, 400 otherwise), the `remote` to compute it from (null for the default), `agentsMayRead` (teammates' agents may read what this project shares, carried to them with the share; on by default) and `agentReads` (this project's chats may read what teammates share into it; off by default). 409 with `code: 'share-key-in-use'`, `projectId` and `projectName` when another project already shares under the key. The members of every group concerned are told at once. Emits `collaborators.changed` (`sharing`).", params: obj({ id: str('Project id') }), body: ref('UpdateProjectSharingRequest'), ok: ref('ProjectSharing') }),
  'GET /collaborators/shared': d('Collaborators', 'What teammates share with this install', { description: "Every shared project of every member, with its `shareId`, counts per kind, sync state, the local projects whose key matches (`matches`), the one it was linked to by hand and the sharer's `agentsMayRead`. To a chat's token in scope (docs/plans/collaborators-agent-access.md), only the projects that scope reaches, each listing audited.", ok: list('SharedProject') }),
  'GET /collaborators/shared/:owner/:shareId': d('Collaborators', 'One project a teammate shares', { description: 'The shared project as `GET /collaborators/shared` lists it: what the read-only view of a project not cloned here is headed with. 404 once its owner no longer shares it with this install, or with Collaborators off.', params: obj({ owner: str("The sharing install's endpoint id"), shareId: str('`sha256(shareKey)`, 32 hex characters') }), ok: ref('SharedProject') }),
  'PUT /collaborators/shared/:owner/:shareId/link': d('Collaborators', 'Link a shared project to a local one', { description: "From then on it shows in that project's Shared tab; a link held in another group is moved. Emits `collaborators.changed` (`links`).", params: obj({ owner: str("The sharing install's endpoint id"), shareId: str('`sha256(shareKey)`, 32 hex characters') }), body: ref('LinkSharedProjectRequest'), ok: ref('SharedProject') }),
  'DELETE /collaborators/shared/:owner/:shareId/link': d('Collaborators', 'Unlink a shared project', { description: 'Emits `collaborators.changed` (`links`).', params: obj({ owner: str("The sharing install's endpoint id"), shareId: str('`sha256(shareKey)`, 32 hex characters') }), ok: ref('SharedProject') }),
  'GET /collaborators/shared/:owner/:shareId/chats': d('Collaborators', "A shared project's chats", { description: 'The copy held, newest first; `live` marks a chat an agent is working in on the owner\'s machine. `?refresh=1` pulls from the owner first, and an owner away leaves the copy as it is.', querystring: obj({ refresh: str('`1` pulls from the owner first') }), ok: list('SharedChat') }),
  'GET /collaborators/shared/:owner/:shareId/memory': d('Collaborators', "A shared project's memory", { description: 'The copy held, the index first. `?refresh=1` pulls from the owner first.', querystring: obj({ refresh: str('`1` pulls from the owner first') }), ok: list('SharedMemoryFile') }),
  'GET /collaborators/shared/:owner/:shareId/journal': d('Collaborators', "A shared project's journal", { description: 'The copy held, newest first. `?refresh=1` pulls from the owner first.', querystring: obj({ refresh: str('`1` pulls from the owner first') }), ok: list('JournalEntry') }),
  'GET /collaborators/shared/:owner/:shareId/documents': d('Collaborators', "A shared project's documents", { description: "The owner's documents folder and `CLAUDE.md` as they are in the owner's working tree, by path; the content is the blob of each `sha256`. `?refresh=1` pulls from the owner first.", querystring: obj({ refresh: str('`1` pulls from the owner first') }), ok: list('SharedDocument') }),
  'GET /collaborators/shared/:owner/:shareId/work-items': d('Collaborators', "A shared project's board", { description: 'Its work items and milestones, as copied. `?refresh=1` pulls from the owner first.', querystring: obj({ refresh: str('`1` pulls from the owner first') }), ok: ref('SharedBoard') }),
  'GET /collaborators/shared/:owner/:shareId/artifacts': d('Collaborators', "A shared project's artifacts", { description: "Orchestration results, uploads of shared chats and plan drafts. `?refresh=1` pulls from the owner first.", querystring: obj({ refresh: str('`1` pulls from the owner first') }), ok: list('SharedArtifact') }),
  'GET /collaborators/shared/:owner/:shareId/chats/:chatId/transcript': d('Collaborators', 'A copied transcript', { description: "Paged as `GET /chats/:id` pages a local one: the newest `limit` entries (200 by default, 1000 at most), or those just before `before`. Read from the lines the copy holds, subagents' left out; `live` while an agent works in it on the owner's machine.", querystring: obj({ limit: str('Entries on the page'), before: str('Entry index from a previous page, to read further back') }), ok: ref('SharedTranscriptPage') }),
  'GET /collaborators/shared/:owner/:shareId/chats/:chatId/subagents/:agentId': d('Collaborators', "A copied subagent's transcript", { description: "A subagent's transcript, or with `?workflow=` a workflow agent's, pulled with its chat's. Only an agent the copied chat lists (`SharedChat.subagents`); any other is 404. Paged as the chat's transcript is.", querystring: obj({ workflow: str('The workflow run (`wf_…`) of a workflow agent'), limit: str('Entries on the page'), before: str('Entry index from a previous page, to read further back') }), ok: ref('SharedAgentTranscriptPage') }),
  'GET /collaborators/agent-reads': d('Collaborators', "What agents read of teammates' shares", { description: "The audit of agent reads, newest first: one row per read a chat's token made of a copy (the chat, the MCP tool from `x-claudio-tool` or the route's summary, the copy, the kind and the record ids). Filter by `owner` and `shareId` for one copy, `chatId` for one chat, `since` for the reads from then. Closed to a chat's token.", querystring: obj({ owner: str("The sharing install's endpoint id"), shareId: str('`sha256(shareKey)`, 32 hex characters'), chatId: str('One chat'), since: str('An ISO date: the reads at or after it'), limit: { type: 'integer', description: 'At most 1000, default 200' } }), ok: ref('AgentReadList') }),
  'GET /collaborators/shared/:owner/:shareId/blobs/:sha256': d('Collaborators', 'A shared file', { description: "The content of a document or an upload the copy names, fetched from the owner on first open and kept. A hash no copied record names is 404; 502 when the owner cannot be reached. A document comes as `text/plain`, an upload as its type when it is an image or a PDF and as a download otherwise, always with `nosniff` and a sandboxing CSP." }),
  'GET /schedules/:id/runs': d('Schedules', 'History of a schedule', { description: 'Newest first. `started` carries the chat or orchestration it produced; `failed` the error; `skipped` says that slots passed while Claudio was not running: those are never run late. `overlapped` is a slot that came while the last run was still going and was not started (policy `skip`, or a queued slot replaced by a newer one or dropped when the schedule was switched off); `queued` waits for the last run to end, and becomes `started` with the same `slot` when it does.', querystring: obj({ limit: { type: 'integer', description: 'At most 500, default 50' } }), ok: list('ScheduleRun') }),
  // ---- Webhooks
  'GET /projects/:id/webhooks': d('Webhooks', "A project's webhooks", {
    description: "The hooks Claudio registered on the project's repository, with what a registration needs: `available` and, when false, the `reason` (`no-public-url`: Claudio has no public origin, and the tailnet-only tunnel is not one; `no-remote`), the `publicUrl` a hook would deliver to, the `events` it subscribes to and `canRedeliver` (always false: GitHub's redelivery needs a scope the CLI may not hold, and GitLab's resend is not offered). A hook that went quiet is read on the way, so a failure the host reports is said here. The secret is never part of the answer.",
    params: obj({ id: str('Project id') }),
    ok: ref('ProjectWebhooks'),
  }),
  'POST /projects/:id/webhooks': d('Webhooks', "Register the repository's webhook", {
    description: "Creates the hook on the host (GitHub through `gh`, GitLab through `glab`) with a new 32-byte secret put on the CLI's stdin, never in its arguments (GitLab also gets a signing token derived from it), and answers `201` with the registration. A hook that already has a Claudio address is adopted, and one that is not Claudio's is never touched. 409 `no-public-url`, `no-remote` or `already-registered`; 403 `hook-no-permission` when the account cannot manage hooks; 502 `hook-unreachable` or the host's reason. Refused to a chat's token with 403.",
    params: obj({ id: str('Project id') }),
    ok: ref('WebhookRegistration'),
  }),
  'POST /projects/:id/webhooks/:registrationId/test': d('Webhooks', 'Send a ping through a webhook', {
    description: "Asks the host to ping the hook and reads the result back: the registration answered has `lastPingAt` and the host's `lastResponse`, or goes to `failing`. 404 `registration-not-found`; 403 `hook-no-permission`; 502 `hook-unreachable`. Refused to a chat's token with 403.",
    params: obj({ id: str('Project id'), registrationId: str('Registration id') }, ['id', 'registrationId']),
    ok: ref('WebhookRegistration'),
  }),
  'DELETE /projects/:id/webhooks/:registrationId': d('Webhooks', 'Remove a webhook', {
    description: "Deletes the hook on the host and its secret here; the registration stays listed as `removed` and its receiver answers 401 from then on. 404 `registration-not-found`; 403 `hook-no-permission`; 502 `hook-unreachable`. Refused to a chat's token with 403.",
    params: obj({ id: str('Project id'), registrationId: str('Registration id') }, ['id', 'registrationId']),
    ok: ref('WebhookRegistration'),
  }),
  'POST /webhooks/github/:registrationId': d('Webhooks', 'Receive a GitHub delivery', {
    description: "Unauthenticated, signature-checked: `X-Hub-Signature-256` is `sha256=` and the HMAC-SHA256 of the raw body under the registration's secret, compared in constant time before the body is parsed. `204` with no body once it is accepted (a replayed `X-GitHub-Delivery` or signed body too); `401` with no detail for an unknown or removed registration or a wrong signature; `429` beyond 60 verified deliveries a minute for one registration; `413` over 5 MiB, which polling covers. Moves the next read of the change requests it names to now and changes nothing else.",
  }),
  'POST /webhooks/gitlab/:registrationId': d('Webhooks', 'Receive a GitLab delivery', {
    description: "Unauthenticated, token-checked: `X-Gitlab-Token` must equal the registration's secret, compared in constant time. A delivery that carries `webhook-signature` (the hook is registered with a signing token) must also carry a right one: `v1,` and the base64 HMAC-SHA256 of `<webhook-id>.<webhook-timestamp>.<raw body>` within five minutes. Answers and limits as the GitHub receiver, with the replay check on `Idempotency-Key`.",
  }),
};

/**
 * The routes a person's request starts work on, which answer `409 spend-cap` over the daily cap
 * (`X-Claudio-Spend-Override: 1`, described once in the document's introduction, lets the person's
 * request through). A message to a chat that is mid-turn is let in whatever the cap says.
 */
const SPEND_GATED = new Set([
  'POST /chats',
  'POST /chats/:id/messages',
  'POST /chats/:id/resume',
  'POST /chats/:id/fork',
  'POST /workflows/saved/run',
  'POST /schedules/:id/run',
  'POST /change-requests/:id/checks/fix',
  'POST /projects/:id/docs/:docId/ask',
  'POST /orchestrations',
  'POST /orchestrations/plan',
  'POST /orchestrations/plan/start',
  'POST /orchestrations/templates/:templateId/launch',
  'POST /orchestrations/:id/resume',
  'POST /orchestrations/:id/relaunch',
  'POST /orchestrations/:id/verify',
  'POST /orchestrations/:id/tasks/:taskId/retry',
  'POST /orchestrations/:id/tasks/:taskId/retry-clean',
  'POST /orchestrations/:id/tasks/:taskId/rerun',
  'POST /projects/:id/assistant/runs',
  'POST /assistant/chats',
]);

const OPENAI_ERROR = obj(
  { error: obj({ message: str(), type: str('`invalid_request_error`, `rate_limit_error` or `server_error`'), param: { type: ['string', 'null'] }, code: { type: ['string', 'null'] } }, ['message', 'type', 'param', 'code']) },
  ['error'],
);

/** Builds the Fastify route schema for a documented route; path params are derived from the URL. */
export function routeSchema(method: string, path: string): Json | null {
  const doc = ROUTE_DOCS[`${method} ${path}`];
  if (!doc) return null;
  const pathParams = [...path.matchAll(/:(\w+)/g)].map((m) => m[1] as string);
  const params = doc.params ?? (pathParams.length ? obj(Object.fromEntries(pathParams.map((p) => [p, str()])), pathParams) : undefined);
  // The OpenAI-compatible routes answer OpenAI's error body, not Claudio's
  const openAi = path.startsWith('/v1/');
  const error = { description: 'Invalid request or not found', content: { 'application/json': { schema: openAi ? OPENAI_ERROR : ref('ApiError') } } };
  const gated = SPEND_GATED.has(`${method} ${path}`);
  return {
    tags: doc.tags,
    summary: doc.summary,
    ...(doc.description || gated ? { description: `${doc.description ?? ''}${gated ? `${doc.description ? '\n\n' : ''}Over the daily spend cap it answers \`409\` with \`code: 'spend-cap'\` and the day's \`spend\`; send \`X-Claudio-Spend-Override: 1\` (see the introduction) to go on.` : ''}` } : {}),
    ...(params ? { params: { ...params, required: pathParams } } : {}),
    ...(doc.querystring ? { querystring: doc.querystring } : {}),
    ...(doc.body ? { body: doc.body } : {}),
    ...(gated ? { headers: obj({ 'x-claudio-spend-override': str('`1` goes on past the daily spend cap; ignored on a request authenticated by a chat\'s token', { enum: ['1'] }) }) } : doc.headers ? { headers: doc.headers } : {}),
    ...(doc.produces ? { produces: [doc.produces] } : {}),
    ...(doc.deprecated ? { deprecated: true } : {}),
    response: {
      [doc.created ? 201 : doc.accepted ? 202 : 200]: doc.produces
        ? { description: 'Event stream', content: { [doc.produces]: { schema: doc.ok } } }
        : { description: 'Success', content: { 'application/json': { schema: doc.ok ?? {} } } },
      400: error,
      ...(pathParams.length || doc.querystring ? { 404: error } : {}),
      ...(gated ? { 409: { description: 'Daily spend cap reached (`code: spend-cap`), or a conflict', content: { 'application/json': { schema: ref('SpendCapRefusal') } } } } : {}),
    },
  };
}
